__wl_modules["canonical"] = function()
-- RFC 8785 JSON Canonicalization Scheme (JCS) for the whitelist protocol.
--
-- The protocol messages contain only ASCII object keys, strings, and integer
-- numbers. That lets the client use a strict, auditable subset of JCS instead
-- of a permissive JSON serializer. Non-integer numbers and non-ASCII keys are
-- rejected: silently formatting either differently from the server would
-- produce a signature the server cannot verify.

local Json = __wl_require('json')

local Canonical = {}

local function hasNonAsciiByte(value)
  for index = 1, #value do
    if string.byte(value, index) >= 128 then
      return true
    end
  end
  return false
end

local function encodeValue(value, seen, depth)
  if depth > 32 then
    error('Canonical JSON nesting is too deep', 2)
  end

  local valueType = type(value)
  if value == nil or value == Json.null then
    return 'null'
  elseif valueType == 'boolean' then
    return value and 'true' or 'false'
  elseif valueType == 'string' then
    return Json.encodeString(value)
  elseif valueType == 'number' then
    if value ~= value or value == math.huge or value == -math.huge then
      error('Canonical JSON cannot encode non-finite numbers', 2)
    end
    if value % 1 ~= 0 or math.abs(value) > 9007199254740991 then
      error('Canonical protocol messages only support safe integer numbers', 2)
    end
    if value == 0 then
      return '0'
    end
    return string.format('%.0f', value)
  elseif valueType == 'table' then
    if seen[value] then
      error('Canonical JSON cannot encode cyclic tables', 2)
    end
    seen[value] = true

    local out = {}
    if Json.isArray(value) then
      local length = 0
      for key in pairs(value) do
        if type(key) ~= 'number' or key % 1 ~= 0 or key < 1 then
          error('Canonical JSON array contains a non-numeric key', 2)
        end
        if key > length then
          length = key
        end
      end
      for index = 1, length do
        if value[index] == nil then
          error('Canonical JSON arrays cannot contain holes', 2)
        end
        out[#out + 1] = encodeValue(value[index], seen, depth + 1)
      end
      seen[value] = nil
      return '[' .. table.concat(out, ',') .. ']'
    end

    local keys = {}
    for key in pairs(value) do
      if type(key) ~= 'string' then
        error('Canonical JSON object keys must be strings', 2)
      end
      if hasNonAsciiByte(key) then
        error('Canonical JSON protocol keys must be ASCII', 2)
      end
      keys[#keys + 1] = key
    end
    table.sort(keys)
    for _, key in ipairs(keys) do
      out[#out + 1] = Json.encodeString(key) .. ':' .. encodeValue(value[key], seen, depth + 1)
    end
    seen[value] = nil
    return '{' .. table.concat(out, ',') .. '}'
  end
  error('Canonical JSON cannot encode value of type ' .. valueType, 2)
end

function Canonical.encode(value)
  local ok, result = pcall(encodeValue, value, {}, 0)
  if not ok then
    return nil, tostring(result)
  end
  return result
end

return Canonical
end

__wl_modules["config"] = function()
-- Configuration resolution and validation for the whitelist Lua client.
--
-- Every option is validated before any network or storage operation happens.
-- Invalid configuration fails closed instead of falling back to insecure
-- defaults.

local Config = {}

Config.VERSION = '1.2.0'
Config.PROTOCOL_VERSION = 1
Config.AUDIENCE = 'whitelist-platform'
Config.DEFAULT_API_PREFIX = '/api/v1'

local defaults = {
  baseUrl = nil,
  apiPrefix = Config.DEFAULT_API_PREFIX,
  allowInsecureHttp = false,
  licenseKey = nil,
  protocolVersion = Config.PROTOCOL_VERSION,
  audience = Config.AUDIENCE,
  requestTimeoutSeconds = 20,
  maxResponseBytes = 1024 * 1024,
  refreshLeewaySeconds = 60,
  maxClockSkewSeconds = 300,
  challengeMaxTtlSeconds = 300,
  keyRegistrationMaxTtlSeconds = 300,
  serverPublicKey = nil,
  serverKeyId = nil,
  serverEncryptionPublicKey = nil,
  serverEncryptionKeyId = nil,
  deviceName = nil,
  executor = nil,
  platform = nil,
  keyName = 'primary',
  storage = {
    root = 'whitelist',
  },
  sessionStore = nil,
  crypto = nil,
  http = nil,
  telemetry = {
    enabled = true,
    autoFlush = true,
    maxQueue = 50,
    maxMessageLength = 300,
    maxDetailsBytes = 2048,
  },
  protection = {
    enabled = true,
    antiHttpSpy = true,
    antiDump = true,
    failClosed = true,
    strictTransport = false,
    maxViolations = 20,
  },
  logger = nil,
}

local function isTable(value)
  return type(value) == 'table'
end

local function copyTable(value, seen)
  if not isTable(value) then
    return value
  end
  seen = seen or {}
  if seen[value] then
    return seen[value]
  end
  local copy = {}
  seen[value] = copy
  for key, item in pairs(value) do
    copy[copyTable(key, seen)] = copyTable(item, seen)
  end
  return copy
end

local function deepMerge(base, override)
  local result = copyTable(base)
  if not isTable(override) then
    return result
  end
  for key, value in pairs(override) do
    if value ~= nil then
      if isTable(result[key]) and isTable(value) then
        result[key] = deepMerge(result[key], value)
      else
        result[key] = copyTable(value)
      end
    end
  end
  return result
end

local function trim(value)
  if type(value) ~= 'string' then
    return value
  end
  return (value:gsub('^%s+', ''):gsub('%s+$', ''))
end

local function hasControlCharacters(value)
  return value:find('[%z\1-\31\127]') ~= nil
end

local function fail(message)
  return nil, message
end

local function validateString(value, name, minLength, maxLength, optional)
  if value == nil and optional then
    return true
  end
  if type(value) ~= 'string' then
    return fail(name .. ' must be a string')
  end
  if #value < minLength or #value > maxLength then
    return fail(string.format('%s must be between %d and %d characters', name, minLength, maxLength))
  end
  if hasControlCharacters(value) then
    return fail(name .. ' contains control characters')
  end
  return true
end

local function isBase64Url(value)
  return type(value) == 'string' and #value > 0 and value:find('^[A-Za-z0-9_-]+$') ~= nil
end

local function decodeBase64UrlLength(value)
  if not isBase64Url(value) then
    return nil
  end
  local length = #value
  local remainder = length % 4
  if remainder == 1 then
    return nil
  end
  local bytes = math.floor(length / 4) * 3
  if remainder == 2 then
    bytes = bytes + 1
  elseif remainder == 3 then
    bytes = bytes + 2
  end
  return bytes
end

local function parseBaseUrl(baseUrl, allowInsecureHttp, apiPrefix)
  if type(baseUrl) ~= 'string' or #baseUrl == 0 then
    return fail('baseUrl is required')
  end
  baseUrl = trim(baseUrl)
  if baseUrl:find('%s') then
    return fail('baseUrl must not contain whitespace')
  end
  if baseUrl:find('[?#]') then
    return fail('baseUrl must not contain a query string or fragment')
  end

  local scheme, authority, path = baseUrl:match('^(https?)://([^/]+)(/.*)$')
  if not scheme then
    scheme, authority = baseUrl:match('^(https?)://([^/]+)$')
    path = ''
  end
  if not scheme or not authority or #authority == 0 then
    return fail('baseUrl must be an absolute http(s) URL')
  end
  if authority:find('@') then
    return fail('baseUrl must not contain credentials')
  end
  if scheme == 'http' and not allowInsecureHttp then
    return fail('baseUrl must use HTTPS (set allowInsecureHttp only for local testing)')
  end

  path = path or ''
  path = path:gsub('/+$', '')
  if path ~= '' and path:sub(1, 1) ~= '/' then
    return fail('baseUrl path must be absolute')
  end

  local apiBaseUrl
  if path == '' then
    apiBaseUrl = scheme .. '://' .. authority .. apiPrefix
  elseif path == apiPrefix or path:sub(-#apiPrefix) == apiPrefix then
    apiBaseUrl = scheme .. '://' .. authority .. path
  else
    apiBaseUrl = scheme .. '://' .. authority .. path .. apiPrefix
  end
  apiBaseUrl = apiBaseUrl:gsub('/+$', '')
  return {
    origin = scheme .. '://' .. authority,
    apiBaseUrl = apiBaseUrl,
    secure = scheme == 'https',
  }
end

local function validateStorage(storage)
  if storage == nil then
    return true
  end
  if not isTable(storage) then
    return fail('storage must be a table')
  end
  if storage.adapter ~= nil then
    if type(storage.adapter) ~= 'table' then
      return fail('storage.adapter must be a table')
    end
    for _, method in ipairs({ 'read', 'write', 'exists' }) do
      if type(storage.adapter[method]) ~= 'function' then
        return fail('storage.adapter.' .. method .. ' must be a function')
      end
    end
    return true
  end
  if storage.root == nil then
    return fail('storage.root is required when storage.adapter is not provided')
  end
  if type(storage.root) ~= 'string' then
    return fail('storage.root must be a string')
  end
  local root = trim(storage.root):gsub('\\', '/')
  if #root == 0 or #root > 200 then
    return fail('storage.root must be between 1 and 200 characters')
  end
  if root:find('%.%.') or root:sub(1, 1) == '/' or root:find('^%a:') then
    return fail('storage.root must be a relative path without ".." segments')
  end
  if root:find('[^%w%._%-/]') then
    return fail('storage.root contains unsupported characters')
  end
  storage.root = root:gsub('/+$', '')
  return true
end

local function validateTelemetry(telemetry)
  if not isTable(telemetry) then
    return fail('telemetry must be a table')
  end
  if type(telemetry.enabled) ~= 'boolean' then
    return fail('telemetry.enabled must be a boolean')
  end
  if type(telemetry.autoFlush) ~= 'boolean' then
    return fail('telemetry.autoFlush must be a boolean')
  end
  if type(telemetry.maxQueue) ~= 'number' or telemetry.maxQueue % 1 ~= 0 or telemetry.maxQueue < 1 or telemetry.maxQueue > 200 then
    return fail('telemetry.maxQueue must be an integer between 1 and 200')
  end
  if type(telemetry.maxMessageLength) ~= 'number' or telemetry.maxMessageLength % 1 ~= 0 or telemetry.maxMessageLength < 1 or telemetry.maxMessageLength > 300 then
    return fail('telemetry.maxMessageLength must be an integer between 1 and 300')
  end
  if type(telemetry.maxDetailsBytes) ~= 'number' or telemetry.maxDetailsBytes % 1 ~= 0 or telemetry.maxDetailsBytes < 128 or telemetry.maxDetailsBytes > 4096 then
    return fail('telemetry.maxDetailsBytes must be an integer between 128 and 4096')
  end
  return true
end

local function validateProtection(protection)
  if not isTable(protection) then
    return fail('protection must be a table')
  end
  for _, key in ipairs({ 'enabled', 'antiHttpSpy', 'antiDump', 'failClosed', 'strictTransport' }) do
    if type(protection[key]) ~= 'boolean' then
      return fail('protection.' .. key .. ' must be a boolean')
    end
  end
  if type(protection.maxViolations) ~= 'number'
    or protection.maxViolations % 1 ~= 0
    or protection.maxViolations < 1
    or protection.maxViolations > 100
  then
    return fail('protection.maxViolations must be an integer between 1 and 100')
  end
  return true
end

function Config.resolve(options)
  if options ~= nil and not isTable(options) then
    return fail('options must be a table')
  end
  local config = deepMerge(defaults, options or {})

  local ok, err = validateString(config.baseUrl, 'baseUrl', 1, 2048)
  if not ok then
    return nil, err
  end
  ok, err = validateString(config.apiPrefix, 'apiPrefix', 1, 100)
  if not ok then
    return nil, err
  end
  config.apiPrefix = trim(config.apiPrefix)
  if config.apiPrefix:sub(1, 1) ~= '/' or config.apiPrefix:sub(-1) == '/' then
    return fail('apiPrefix must start with "/" and must not end with "/"')
  end
  if config.apiPrefix:find('[^%w%._%-/]') then
    return fail('apiPrefix contains unsupported characters')
  end
  if type(config.allowInsecureHttp) ~= 'boolean' then
    return fail('allowInsecureHttp must be a boolean')
  end

  local parsed
  parsed, err = parseBaseUrl(config.baseUrl, config.allowInsecureHttp, config.apiPrefix)
  if not parsed then
    return nil, err
  end
  config.baseUrl = trim(config.baseUrl):gsub('/+$', '')
  config.apiBaseUrl = parsed.apiBaseUrl
  config.origin = parsed.origin
  config.secure = parsed.secure

  if config.licenseKey ~= nil then
    if type(config.licenseKey) ~= 'string' then
      return fail('licenseKey must be a string')
    end
    config.licenseKey = trim(config.licenseKey)
    if #config.licenseKey < 20 or #config.licenseKey > 200 then
      return fail('licenseKey must be between 20 and 200 characters')
    end
    if hasControlCharacters(config.licenseKey) then
      return fail('licenseKey contains control characters')
    end
  end

  if type(config.protocolVersion) ~= 'number' or config.protocolVersion % 1 ~= 0 or config.protocolVersion < 1 then
    return fail('protocolVersion must be a positive integer')
  end
  ok, err = validateString(config.audience, 'audience', 1, 100)
  if not ok then
    return nil, err
  end

  if type(config.requestTimeoutSeconds) ~= 'number' or config.requestTimeoutSeconds <= 0 or config.requestTimeoutSeconds > 120 then
    return fail('requestTimeoutSeconds must be between 1 and 120')
  end
  if type(config.maxResponseBytes) ~= 'number' or config.maxResponseBytes % 1 ~= 0 or config.maxResponseBytes < 1024 or config.maxResponseBytes > 16 * 1024 * 1024 then
    return fail('maxResponseBytes must be between 1024 and 16777216')
  end
  if type(config.refreshLeewaySeconds) ~= 'number' or config.refreshLeewaySeconds < 0 or config.refreshLeewaySeconds > 600 then
    return fail('refreshLeewaySeconds must be between 0 and 600')
  end
  if type(config.maxClockSkewSeconds) ~= 'number' or config.maxClockSkewSeconds < 0 or config.maxClockSkewSeconds > 3600 then
    return fail('maxClockSkewSeconds must be between 0 and 3600')
  end
  if type(config.challengeMaxTtlSeconds) ~= 'number' or config.challengeMaxTtlSeconds < 1 or config.challengeMaxTtlSeconds > 600 then
    return fail('challengeMaxTtlSeconds must be between 1 and 600')
  end
  if type(config.keyRegistrationMaxTtlSeconds) ~= 'number' or config.keyRegistrationMaxTtlSeconds < 1 or config.keyRegistrationMaxTtlSeconds > 600 then
    return fail('keyRegistrationMaxTtlSeconds must be between 1 and 600')
  end

  if config.serverPublicKey ~= nil then
    if type(config.serverPublicKey) ~= 'string' or decodeBase64UrlLength(config.serverPublicKey) ~= 32 then
      return fail('serverPublicKey must be a raw 32-byte Ed25519 key encoded as base64url')
    end
  end
  if config.serverKeyId ~= nil then
    if config.serverPublicKey == nil then
      return fail('serverKeyId requires serverPublicKey to be configured')
    end
    if type(config.serverKeyId) ~= 'string' or decodeBase64UrlLength(config.serverKeyId) ~= 32 then
      return fail('serverKeyId must be a SHA-256 key identifier encoded as base64url')
    end
  end
  if config.serverEncryptionPublicKey ~= nil then
    if type(config.serverEncryptionPublicKey) ~= 'string' or decodeBase64UrlLength(config.serverEncryptionPublicKey) ~= 32 then
      return fail('serverEncryptionPublicKey must be a raw 32-byte X25519 key encoded as base64url')
    end
  end
  if config.serverEncryptionKeyId ~= nil then
    if config.serverEncryptionPublicKey == nil then
      return fail('serverEncryptionKeyId requires serverEncryptionPublicKey to be configured')
    end
    if type(config.serverEncryptionKeyId) ~= 'string' or decodeBase64UrlLength(config.serverEncryptionKeyId) ~= 32 then
      return fail('serverEncryptionKeyId must be a SHA-256 key identifier encoded as base64url')
    end
  end

  ok, err = validateString(config.deviceName, 'deviceName', 1, 120, true)
  if not ok then
    return nil, err
  end
  ok, err = validateString(config.executor, 'executor', 1, 120, true)
  if not ok then
    return nil, err
  end
  ok, err = validateString(config.platform, 'platform', 1, 80, true)
  if not ok then
    return nil, err
  end
  ok, err = validateString(config.keyName, 'keyName', 1, 120, true)
  if not ok then
    return nil, err
  end

  ok, err = validateStorage(config.storage)
  if not ok then
    return nil, err
  end
  ok, err = validateTelemetry(config.telemetry)
  if not ok then
    return nil, err
  end
  ok, err = validateProtection(config.protection)
  if not ok then
    return nil, err
  end

  if config.sessionStore ~= nil then
    if not isTable(config.sessionStore) then
      return fail('sessionStore must be a table')
    end
    for _, method in ipairs({ 'load', 'save', 'clear' }) do
      if type(config.sessionStore[method]) ~= 'function' then
        return fail('sessionStore.' .. method .. ' must be a function')
      end
    end
  end

  if config.crypto ~= nil and config.crypto ~= 'pure' and not isTable(config.crypto) then
    return fail('crypto must be "pure", a table, or nil')
  end
  if config.http ~= nil then
    if not isTable(config.http) then
      return fail('http must be a table')
    end
    if config.http.adapter ~= nil and type(config.http.adapter) ~= 'function' and type(config.http.adapter) ~= 'table' then
      return fail('http.adapter must be a function or table')
    end
    if config.http.requestStyle ~= nil and config.http.requestStyle ~= 'pascal' and config.http.requestStyle ~= 'lower' then
      return fail('http.requestStyle must be "pascal" or "lower"')
    end
  end
  if config.logger ~= nil and type(config.logger) ~= 'function' then
    return fail('logger must be a function')
  end

  config.version = Config.VERSION
  return config
end

function Config.deepCopy(value)
  return copyTable(value)
end

return Config
end

__wl_modules["protection"] = function()
-- Client-side transport and runtime protection.
--
-- This module provides two best-effort hardening layers for the Lua client:
--
-- 1. Anti-HTTP-spy: pin the executor HTTP transport functions and detect when
--    they are replaced or wrapped after the client starts. All protocol
--    requests fail closed when the transport changes, so a script that installs
--    an HTTP logger after the whitelist cannot silently observe new requests.
--
-- 2. Anti-dump: seal the security-critical methods and install tripwires on the
--    executor's debug/introspection helpers. A dumper that probes a protected
--    function, hooks one of our methods, or scans the Lua heap through getgc is
--    detected and (by default) stops the client.
--
-- These checks are deterrents, not a sandbox. A privileged executor can always
-- read process memory or remove the tripwires before the whitelist loads. The
-- server remains the authorization authority; see docs/SECURITY.md.

local Protection = {}
Protection.__index = Protection

local states = setmetatable({}, { __mode = 'k' })
local protectedFunctions = setmetatable({}, { __mode = 'k' })
local protectedTables = setmetatable({}, { __mode = 'k' })
local protectedFunctionCount = 0
local protectedTableCount = 0

local tripwires = {
  installed = false,
  wrappers = {},
  errors = {},
}

local debugTable = type(debug) == 'table' and debug or nil
local originals = {
  getinfo = debugTable and type(debugTable.getinfo) == 'function' and debugTable.getinfo or nil,
  info = debugTable and type(debugTable.info) == 'function' and debugTable.info or nil,
  getupvalue = debugTable and type(debugTable.getupvalue) == 'function' and debugTable.getupvalue or nil,
  getconstants = debugTable and type(debugTable.getconstants) == 'function' and debugTable.getconstants or nil,
  getprotos = debugTable and type(debugTable.getprotos) == 'function' and debugTable.getprotos or nil,
  setupvalue = debugTable and type(debugTable.setupvalue) == 'function' and debugTable.setupvalue or nil,
}

local function isTable(value)
  return type(value) == 'table'
end

local function safeToString(value)
  local ok, text = pcall(tostring, value)
  if ok then
    return text
  end
  return nil
end

local function getExecutorEnv()
  if type(getgenv) == 'function' then
    local ok, env = pcall(getgenv)
    if ok and isTable(env) then
      return env
    end
  end
  return _G
end

local function getFunctionInfo(fn)
  if type(fn) ~= 'function' then
    return nil
  end
  if originals.getinfo then
    local ok, info = pcall(originals.getinfo, fn, 'S')
    if ok and isTable(info) then
      return info
    end
  end
  if originals.info then
    local ok, source = pcall(originals.info, fn, 's')
    if ok and type(source) == 'string' then
      local line
      local lineOk, lineValue = pcall(originals.info, fn, 'l')
      if lineOk then
        line = lineValue
      end
      return {
        source = source,
        what = source == '[C]' and 'C' or nil,
        linedefined = line,
      }
    end
  end
  return nil
end

local function fingerprint(fn)
  if type(fn) ~= 'function' then
    return nil
  end
  local info = getFunctionInfo(fn)
  return {
    address = safeToString(fn),
    source = info and info.source or nil,
    what = info and info.what or nil,
    line = info and info.linedefined or nil,
  }
end

local function fingerprintMatches(left, right)
  if left == nil or right == nil then
    return left == right
  end
  return left.address == right.address
    and left.source == right.source
    and left.what == right.what
    and left.line == right.line
end

local function isProtectedFunction(value)
  return type(value) == 'function' and protectedFunctions[value] ~= nil
end

local function recordStateViolation(state, kind, message)
  if not state.enabled then
    return
  end
  if kind:sub(1, 6) == 'DEBUG_' and not state.antiDump then
    return
  end
  state.violationCount = state.violationCount + 1
  local violation = {
    kind = kind,
    message = message,
    at = os.time(),
  }
  state.lastViolation = violation
  state.violations[#state.violations + 1] = violation
  if #state.violations > state.maxViolations then
    table.remove(state.violations, 1)
  end
end

local function flagViolation(kind, message)
  for _, state in pairs(states) do
    recordStateViolation(state, kind, message)
  end
end

local function resolvePath(root, path)
  local value = root
  for index = 1, #path do
    if type(value) ~= 'table' then
      return nil
    end
    local ok, nextValue = pcall(function()
      return value[path[index]]
    end)
    if not ok then
      return nil
    end
    value = nextValue
  end
  return value
end

--- Registers a function as protected. Tripwires refuse to inspect or hook it,
--- and getgc() filters it out of heap scans.
function Protection.protectFunction(fn, label)
  if type(fn) ~= 'function' then
    return false
  end
  if protectedFunctions[fn] == nil then
    protectedFunctionCount = protectedFunctionCount + 1
  end
  protectedFunctions[fn] = label or 'protected'
  return true
end

--- Registers a table (and optionally its nested tables) as protected.
function Protection.protectTable(tbl, label, depth)
  if type(tbl) ~= 'table' then
    return false
  end
  depth = depth or 1
  if depth < 0 then
    depth = 0
  elseif depth > 4 then
    depth = 4
  end
  local seen = {}
  local function walk(value, currentDepth, name)
    if type(value) ~= 'table' or seen[value] then
      return
    end
    seen[value] = true
    if protectedTables[value] == nil then
      protectedTableCount = protectedTableCount + 1
    end
    protectedTables[value] = name
    if currentDepth >= depth then
      return
    end
    local key, item = next(value)
    while key ~= nil do
      if type(item) == 'table' then
        walk(item, currentDepth + 1, name .. '.' .. tostring(key))
      end
      key, item = next(value, key)
    end
  end
  walk(tbl, 0, label or 'protected')
  return true
end

--- Registers every function in a public module table and hides the table from
--- getgc() heap scans.
function Protection.registerModule(name, value)
  if type(value) ~= 'table' then
    return false
  end
  Protection.protectTable(value, 'module.' .. name, 1)
  local key, item = next(value)
  while key ~= nil do
    if type(item) == 'function' then
      Protection.protectFunction(item, 'module.' .. name .. '.' .. tostring(key))
    end
    key, item = next(value, key)
  end
  return true
end

function Protection.registerModules(modules)
  if type(modules) ~= 'table' then
    return false
  end
  for name, value in pairs(modules) do
    Protection.registerModule(name, value)
  end
  return true
end

local function makeGetInfoWrapper(getinfo)
  return function(a, b, c)
    local thread, target, what
    if type(a) == 'thread' then
      thread, target, what = a, b, c
    else
      target, what = a, b
    end

    if type(target) == 'function' then
      if isProtectedFunction(target) then
        flagViolation('DEBUG_GETINFO', 'debug.getinfo targeted a protected function')
        return nil
      end
      if thread ~= nil then
        return getinfo(thread, target, what)
      end
      return getinfo(target, what)
    end

    if type(target) == 'number' then
      local requested = what
      local includeFunction = true
      if type(requested) == 'string' then
        includeFunction = requested:find('f', 1, true) ~= nil
      end
      local effective = requested
      if type(requested) == 'string' and not includeFunction then
        effective = requested .. 'f'
      end
      local info
      if thread ~= nil then
        info = getinfo(thread, target + 1, effective)
      else
        info = getinfo(target + 1, effective)
      end
      if isTable(info) and isProtectedFunction(info.func) then
        flagViolation('DEBUG_GETINFO', 'debug.getinfo inspected a protected stack frame')
        return nil
      end
      if isTable(info) and type(requested) == 'string' and not includeFunction then
        info.func = nil
      end
      return info
    end

    if thread ~= nil then
      return getinfo(thread, target, what)
    end
    return getinfo(target, what)
  end
end

local function makeLuauInfoWrapper(info)
  return function(target, options)
    if type(target) == 'function' then
      if isProtectedFunction(target) then
        flagViolation('DEBUG_GETINFO', 'debug.info targeted a protected function')
        return nil
      end
      return info(target, options)
    end
    if type(target) == 'number' then
      local ok, fn = pcall(info, target + 1, 'f')
      if ok and isProtectedFunction(fn) then
        flagViolation('DEBUG_GETINFO', 'debug.info inspected a protected stack frame')
        return nil
      end
      return info(target + 1, options)
    end
    return info(target, options)
  end
end

local function makeGetUpvalueWrapper(getupvalue)
  return function(fn, index)
    if isProtectedFunction(fn) then
      flagViolation('DEBUG_UPVALUE', 'debug.getupvalue targeted a protected function')
      return nil
    end
    return getupvalue(fn, index)
  end
end

local function makeFunctionInspectorWrapper(originalFn, kind)
  return function(fn, ...)
    if isProtectedFunction(fn) then
      flagViolation(kind, 'debug inspection targeted a protected function')
      return nil
    end
    return originalFn(fn, ...)
  end
end

local function makeSetupvalueWrapper(setupvalue)
  return function(fn, index, value)
    if isProtectedFunction(fn) then
      flagViolation('DEBUG_SETUPVALUE', 'debug.setupvalue targeted a protected function')
      return nil
    end
    return setupvalue(fn, index, value)
  end
end

local function makeHookWrapper(originalFn, kind)
  return function(target, hook, ...)
    if isProtectedFunction(target) then
      flagViolation(kind, 'hookfunction targeted a protected function')
      return nil
    end
    return originalFn(target, hook, ...)
  end
end

local function makeGetGcWrapper(getgc)
  return function(includeTables)
    local objects = getgc(includeTables)
    if type(objects) ~= 'table' then
      return objects
    end
    local filtered = {}
    for index = 1, #objects do
      local value = objects[index]
      if not isProtectedFunction(value) and not protectedTables[value] then
        filtered[#filtered + 1] = value
      end
    end
    return filtered
  end
end

local function installWrapper(target, key, label, factory)
  if type(target) ~= 'table' then
    return false
  end
  local originalFn = target[key]
  if type(originalFn) ~= 'function' then
    return false
  end
  local wrapper = factory(originalFn)
  local ok = pcall(function()
    target[key] = wrapper
  end)
  if not ok then
    tripwires.errors[#tripwires.errors + 1] = label
    return false
  end
  tripwires.wrappers[#tripwires.wrappers + 1] = {
    table = target,
    key = key,
    wrapper = wrapper,
    label = label,
  }
  Protection.protectFunction(wrapper, 'protection.tripwire.' .. label)
  return true
end

--- Installs anti-dump tripwires. Safe to call more than once.
function Protection.installTripwires()
  if tripwires.installed then
    return true
  end
  tripwires.installed = true

  if debugTable ~= nil then
    if originals.getinfo ~= nil then
      installWrapper(debugTable, 'getinfo', 'debug.getinfo', makeGetInfoWrapper)
    end
    if originals.info ~= nil then
      installWrapper(debugTable, 'info', 'debug.info', makeLuauInfoWrapper)
    end
    if originals.getupvalue ~= nil then
      installWrapper(debugTable, 'getupvalue', 'debug.getupvalue', makeGetUpvalueWrapper)
    end
    if originals.getconstants ~= nil then
      installWrapper(debugTable, 'getconstants', 'debug.getconstants', function(originalFn)
        return makeFunctionInspectorWrapper(originalFn, 'DEBUG_CONSTANTS')
      end)
    end
    if originals.getprotos ~= nil then
      installWrapper(debugTable, 'getprotos', 'debug.getprotos', function(originalFn)
        return makeFunctionInspectorWrapper(originalFn, 'DEBUG_PROTOS')
      end)
    end
    if originals.setupvalue ~= nil then
      installWrapper(debugTable, 'setupvalue', 'debug.setupvalue', makeSetupvalueWrapper)
    end
  end

  local env = getExecutorEnv()
  local roots = { env }
  if _G ~= env then
    roots[#roots + 1] = _G
  end
  for _, root in ipairs(roots) do
    if type(root) == 'table' then
      installWrapper(root, 'getscriptbytecode', 'getscriptbytecode', function(originalFn)
        return makeFunctionInspectorWrapper(originalFn, 'DEBUG_BYTECODE')
      end)
      installWrapper(root, 'hookfunction', 'hookfunction', function(originalFn)
        return makeHookWrapper(originalFn, 'DEBUG_HOOK')
      end)
      installWrapper(root, 'replaceclosure', 'replaceclosure', function(originalFn)
        return makeHookWrapper(originalFn, 'DEBUG_HOOK')
      end)
      installWrapper(root, 'getgc', 'getgc', makeGetGcWrapper)
    end
  end

  return true
end

function Protection.new(config)
  local settings = type(config) == 'table' and config.protection or nil
  if type(settings) ~= 'table' then
    settings = {}
  end

  local self = setmetatable({}, Protection)
  local state = {
    enabled = settings.enabled ~= false,
    antiHttpSpy = settings.antiHttpSpy ~= false,
    antiDump = settings.antiDump ~= false,
    failClosed = settings.failClosed ~= false,
    strictTransport = settings.strictTransport == true,
    maxViolations = settings.maxViolations or 20,
    violations = {},
    violationCount = 0,
    lastViolation = nil,
    transport = nil,
    transportCandidates = {},
    sealedMethods = {},
    sealedValues = {},
    loader = nil,
    loaderName = nil,
    loaderFingerprint = nil,
    loaderEnv = nil,
    tripwiresInstalled = false,
  }
  states[self] = state

  if state.enabled and state.antiDump then
    Protection.installTripwires()
    state.tripwiresInstalled = tripwires.installed
  end
  return self
end

function Protection:destroy()
  states[self] = nil
end

--- Captures the script loader once so a later hook cannot observe payload
--- source passed to loadstring/load.
function Protection:captureLoader()
  local state = states[self]
  if state == nil then
    return nil, nil
  end
  if state.loader ~= nil then
    return state.loader, state.loaderName
  end
  local env = getExecutorEnv()
  for _, name in ipairs({ 'loadstring', 'load' }) do
    local fn = env[name]
    if type(fn) == 'function' then
      state.loader = fn
      state.loaderName = name
      state.loaderEnv = env
      state.loaderFingerprint = fingerprint(fn)
      Protection.protectFunction(fn, 'loader.' .. name)
      return fn, name
    end
  end
  return nil, nil
end

--- Records the selected HTTP adapter and every executor transport that exists
--- at startup. Any later replacement is treated as an HTTP spy.
function Protection:snapshotTransport(http, adapter, adapterName, rawFn, isCustom)
  local state = states[self]
  if state == nil or not state.enabled or not state.antiHttpSpy then
    return false
  end
  if type(http) ~= 'table' or type(adapter) ~= 'function' then
    return false
  end

  state.transport = {
    target = http,
    key = 'adapter',
    fn = adapter,
    fingerprint = fingerprint(adapter),
    name = adapterName or 'custom',
    rawFn = rawFn,
    isCustom = isCustom == true,
  }
  Protection.protectFunction(adapter, 'http.adapter')
  if type(rawFn) == 'function' and rawFn ~= adapter then
    Protection.protectFunction(rawFn, 'http.adapterFn')
  end

  local env = getExecutorEnv()
  local candidates = {}
  local function add(name, resolver)
    local ok, fn = pcall(resolver)
    if ok and type(fn) == 'function' then
      candidates[#candidates + 1] = {
        name = name,
        resolve = resolver,
        fn = fn,
        fingerprint = fingerprint(fn),
      }
      Protection.protectFunction(fn, 'transport.' .. name)
    end
  end

  add('request', function()
    return env.request
  end)
  add('http_request', function()
    return env.http_request
  end)
  add('syn.request', function()
    return env.syn and env.syn.request
  end)
  add('http.request', function()
    return env.http and env.http.request
  end)
  add('fluxus.request', function()
    return env.fluxus and env.fluxus.request
  end)
  add('krnl.request', function()
    return env.krnl and env.krnl.request
  end)

  if type(game) == 'table' or type(game) == 'userdata' then
    add('game.HttpGet', function()
      return game.HttpGet
    end)
    add('game.HttpGetAsync', function()
      return game.HttpGetAsync
    end)
    add('game.HttpPost', function()
      return game.HttpPost
    end)
    add('game.HttpPostAsync', function()
      return game.HttpPostAsync
    end)
    local httpService = nil
    pcall(function()
      httpService = game:GetService('HttpService')
    end)
    if httpService ~= nil then
      add('HttpService.GetAsync', function()
        return httpService.GetAsync
      end)
      add('HttpService.RequestAsync', function()
        return httpService.RequestAsync
      end)
    end
  end

  state.transportCandidates = candidates

  if state.strictTransport and not state.transport.isCustom then
    local info = state.transport.fingerprint
    if info ~= nil and info.what ~= 'C' and info.source ~= '[C]' then
      recordStateViolation(
        state,
        'TRANSPORT_TAMPERED',
        'executor HTTP transport is a Lua wrapper (strictTransport)'
      )
    end
  end
  return true
end

--- Seals a method so replacing or hooking it is detected. Can be called on an
--- instance (to catch shadow fields) and on the shared module table.
function Protection:sealMethod(target, key, label)
  local state = states[self]
  if state == nil or not state.enabled or type(target) ~= 'table' then
    return false
  end
  local fn = target[key]
  if type(fn) ~= 'function' then
    return false
  end
  for _, seal in ipairs(state.sealedMethods) do
    if seal.target == target and seal.key == key then
      return true
    end
  end
  state.sealedMethods[#state.sealedMethods + 1] = {
    target = target,
    key = key,
    label = label or tostring(key),
    fn = fn,
    fingerprint = fingerprint(fn),
  }
  Protection.protectFunction(fn, label or tostring(key))
  return true
end

--- Seals a non-function field (a table or function reference) against
--- replacement.
function Protection:sealValue(target, key, label)
  local state = states[self]
  if state == nil or not state.enabled or type(target) ~= 'table' then
    return false
  end
  local value = target[key]
  for _, seal in ipairs(state.sealedValues) do
    if seal.target == target and seal.key == key then
      return true
    end
  end
  state.sealedValues[#state.sealedValues + 1] = {
    target = target,
    key = key,
    label = label or tostring(key),
    value = value,
  }
  if type(value) == 'function' then
    Protection.protectFunction(value, label or tostring(key))
  elseif type(value) == 'table' then
    Protection.protectTable(value, label or tostring(key), 1)
  end
  return true
end

--- Registers client-owned tables for getgc() filtering.
function Protection:attachClient(client)
  local state = states[self]
  if state == nil or not state.enabled or type(client) ~= 'table' then
    return false
  end
  Protection.protectTable(client, 'client', 1)
  if type(client.config) == 'table' then
    Protection.protectTable(client.config, 'client.config', 2)
  end
  if type(client.security) == 'table' then
    Protection.protectTable(client.security, 'client.security', 2)
  end
  if type(client.http) == 'table' then
    Protection.protectTable(client.http, 'client.http', 1)
  end
  if type(client.session) == 'table' then
    Protection.protectTable(client.session, 'client.session', 1)
  end
  if type(client.keyring) == 'table' then
    Protection.protectTable(client.keyring, 'client.keyring', 2)
  end
  if type(client.key) == 'table' then
    Protection.protectTable(client.key, 'client.key', 1)
  end
  if type(client.secureChannel) == 'table' then
    Protection.protectTable(client.secureChannel, 'client.secureChannel', 1)
  end
  if type(client.serverKey) == 'table' then
    Protection.protectTable(client.serverKey, 'client.serverKey', 1)
  end
  return true
end

--- Verifies that the HTTP adapter and every startup transport are unchanged.
function Protection.checkTransport(instance)
  local state = states[instance]
  if state == nil then
    return nil, 'protection state is unavailable'
  end
  if not state.enabled or not state.antiHttpSpy then
    return true
  end
  local transport = state.transport
  if transport == nil then
    return nil, 'HTTP transport was not initialized'
  end

  local current = transport.target[transport.key]
  if current ~= transport.fn then
    recordStateViolation(state, 'TRANSPORT_TAMPERED', 'HTTP adapter was replaced')
    if state.failClosed then
      return nil, 'HTTP adapter was replaced'
    end
    return true, 'HTTP adapter was replaced'
  end
  if not fingerprintMatches(fingerprint(current), transport.fingerprint) then
    recordStateViolation(state, 'TRANSPORT_TAMPERED', 'HTTP adapter was modified')
    if state.failClosed then
      return nil, 'HTTP adapter was modified'
    end
    return true, 'HTTP adapter was modified'
  end

  for _, candidate in ipairs(state.transportCandidates) do
    local ok, value = pcall(candidate.resolve)
    if not ok or value ~= candidate.fn then
      local reason = 'HTTP transport ' .. candidate.name .. ' was replaced'
      recordStateViolation(state, 'TRANSPORT_TAMPERED', reason)
      if state.failClosed then
        return nil, reason
      end
      return true, reason
    end
    if not fingerprintMatches(fingerprint(value), candidate.fingerprint) then
      local reason = 'HTTP transport ' .. candidate.name .. ' was modified'
      recordStateViolation(state, 'TRANSPORT_TAMPERED', reason)
      if state.failClosed then
        return nil, reason
      end
      return true, reason
    end
  end
  return true
end

--- Verifies sealed methods, the script loader, and the anti-dump tripwires.
function Protection.checkIntegrity(instance)
  local state = states[instance]
  if state == nil then
    return nil, 'protection state is unavailable'
  end
  if not state.enabled then
    return true
  end

  for _, seal in ipairs(state.sealedValues) do
    local current = seal.target[seal.key]
    if current ~= seal.value then
      local reason = seal.label .. ' was replaced'
      recordStateViolation(state, 'INTEGRITY_VIOLATION', reason)
      if state.failClosed then
        return nil, reason
      end
      return true, reason
    end
  end

  for _, seal in ipairs(state.sealedMethods) do
    local current = seal.target[seal.key]
    if current ~= seal.fn then
      local reason = seal.label .. ' was replaced'
      recordStateViolation(state, 'INTEGRITY_VIOLATION', reason)
      if state.failClosed then
        return nil, reason
      end
      return true, reason
    end
    if not fingerprintMatches(fingerprint(current), seal.fingerprint) then
      local reason = seal.label .. ' was modified'
      recordStateViolation(state, 'INTEGRITY_VIOLATION', reason)
      if state.failClosed then
        return nil, reason
      end
      return true, reason
    end
  end

  if state.loader ~= nil then
    local current = state.loaderEnv and state.loaderEnv[state.loaderName] or nil
    if current ~= state.loader then
      local reason = 'script loader was replaced'
      recordStateViolation(state, 'INTEGRITY_VIOLATION', reason)
      if state.failClosed then
        return nil, reason
      end
      return true, reason
    end
    if not fingerprintMatches(fingerprint(current), state.loaderFingerprint) then
      local reason = 'script loader was modified'
      recordStateViolation(state, 'INTEGRITY_VIOLATION', reason)
      if state.failClosed then
        return nil, reason
      end
      return true, reason
    end
  end

  if state.antiDump then
    for _, wrapper in ipairs(tripwires.wrappers) do
      if wrapper.table[wrapper.key] ~= wrapper.wrapper then
        local reason = 'anti-dump tripwire ' .. wrapper.label .. ' was removed'
        recordStateViolation(state, 'INTEGRITY_VIOLATION', reason)
        if state.failClosed then
          return nil, reason
        end
        return true, reason
      end
    end
  end

  -- A debug/introspection probe is a positive dump signal. When failClosed is
  -- enabled the client stops instead of continuing with a possibly inspected
  -- key or token in memory.
  if state.failClosed and state.violationCount > 0 then
    local violation = state.lastViolation
    local reason = violation and violation.message or 'a client protection violation was recorded'
    return nil, reason
  end

  return true
end

function Protection.getStatus(instance)
  local state = states[instance]
  if state == nil then
    return {
      enabled = false,
      violationCount = 0,
      lastViolation = nil,
    }
  end
  local last = state.lastViolation
  return {
    enabled = state.enabled,
    antiHttpSpy = state.antiHttpSpy,
    antiDump = state.antiDump,
    failClosed = state.failClosed,
    strictTransport = state.strictTransport,
    tripwiresInstalled = state.tripwiresInstalled or tripwires.installed,
    tripwireCount = #tripwires.wrappers,
    tripwireErrors = #tripwires.errors,
    protectedFunctionCount = protectedFunctionCount,
    protectedTableCount = protectedTableCount,
    violationCount = state.violationCount,
    lastViolation = last and {
      kind = last.kind,
      message = last.message,
      at = last.at,
    } or nil,
  }
end

return Protection
end

__wl_modules["pure_crypto"] = function()
-- Pure-Lua SHA-256, SHA-512, and Ed25519.
--
-- This module exists so the client can authenticate on executors that do not
-- expose native Ed25519 (for example Potassium). It is an explicit opt-in
-- fallback: pass `crypto = "pure"` to Whitelist.authenticate.
--
-- The implementation follows FIPS 180-4 (SHA-256/SHA-512) and RFC 8032
-- (Ed25519). It is not constant-time. That is acceptable for this client
-- because the private key already lives in the executor's filesystem, but it
-- should not be used as a general-purpose signing library.
--
-- The only external dependency is a cryptographically secure random source
-- supplied by the caller (normally the executor's crypt.generatebytes).

local PureCrypto = {}

local floor = math.floor
local char = string.char
local byte = string.byte
local concat = table.concat

local MASK32 = 4294967296

----------------------------------------------------------------------
-- 32-bit bit operations
----------------------------------------------------------------------

local band, bor, bxor, bnot, lshift, rshift, rrotate

do
  local ok, b = pcall(function()
    return bit32
  end)
  if ok and type(b) == 'table' and type(b.band) == 'function' then
    band, bor, bxor, bnot = b.band, b.bor, b.bxor, b.bnot
    lshift, rshift, rrotate = b.lshift, b.rshift, b.rrotate
  else
    -- Lua 5.3+ has native bitwise operators, but Luau does not parse them.
    -- Build the operators from a string so the same source runs on both.
    local loader = loadstring or load
    local native = nil
    if type(loader) == 'function' then
      local chunk = loader([[
        local mask = 0xffffffff
        return {
          band = function(a, b) return (a & b) & mask end,
          bor = function(a, b) return (a | b) & mask end,
          bxor = function(a, b) return (a ~ b) & mask end,
          bnot = function(a) return (~a) & mask end,
          lshift = function(a, n)
            if n >= 32 then return 0 end
            return (a << n) & mask
          end,
          rshift = function(a, n)
            if n >= 32 then return 0 end
            return (a >> n) & mask
          end,
          rrotate = function(a, n)
            n = n % 32
            if n == 0 then return a & mask end
            return ((a >> n) | (a << (32 - n))) & mask
          end,
        }
      ]], 'pure_crypto_bitops')
      if chunk then
        local loaded, result = pcall(chunk)
        if loaded and type(result) == 'table' then
          native = result
        end
      end
    end

    if native then
      band, bor, bxor, bnot = native.band, native.bor, native.bxor, native.bnot
      lshift, rshift, rrotate = native.lshift, native.rshift, native.rrotate
    else
      local function to32(value)
        return value % MASK32
      end

      local function bitop(a, b, op)
        a, b = to32(a), to32(b)
        local result, bit = 0, 1
        for _ = 1, 32 do
          local abit = a % 2
          local bbit = b % 2
          if op == 'and' then
            if abit == 1 and bbit == 1 then result = result + bit end
          elseif op == 'or' then
            if abit == 1 or bbit == 1 then result = result + bit end
          else
            if abit ~= bbit then result = result + bit end
          end
          a = floor(a / 2)
          b = floor(b / 2)
          bit = bit * 2
        end
        return result
      end

      band = function(a, b)
        return bitop(a, b, 'and')
      end
      bor = function(a, b)
        return bitop(a, b, 'or')
      end
      bxor = function(a, b)
        return bitop(a, b, 'xor')
      end
      bnot = function(a)
        return 4294967295 - to32(a)
      end
      lshift = function(a, n)
        if n >= 32 then return 0 end
        return (to32(a) * 2 ^ n) % MASK32
      end
      rshift = function(a, n)
        if n >= 32 then return 0 end
        return floor(to32(a) / 2 ^ n)
      end
      rrotate = function(a, n)
        n = n % 32
        if n == 0 then return to32(a) end
        return bor(rshift(a, n), lshift(a, 32 - n))
      end
    end
  end
end

----------------------------------------------------------------------
-- Encoding helpers
----------------------------------------------------------------------

local HEX = '0123456789abcdef'
local HEX_LOOKUP = {}
for index = 0, 15 do
  HEX_LOOKUP[string.format('%x', index)] = index
end

local function hexEncode(value)
  local out = {}
  for index = 1, #value do
    local current = byte(value, index)
    out[#out + 1] = HEX:sub(floor(current / 16) + 1, floor(current / 16) + 1)
    out[#out + 1] = HEX:sub(current % 16 + 1, current % 16 + 1)
  end
  return concat(out)
end

local function hexDecode(value)
  if type(value) ~= 'string' or #value % 2 ~= 0 then
    return nil
  end
  local out = {}
  for index = 1, #value, 2 do
    local high = HEX_LOOKUP[value:sub(index, index):lower()]
    local low = HEX_LOOKUP[value:sub(index + 1, index + 1):lower()]
    if high == nil or low == nil then
      return nil
    end
    out[#out + 1] = char(high * 16 + low)
  end
  return concat(out)
end

local B64URL = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'
local B64URL_LOOKUP = {}
for index = 1, #B64URL do
  B64URL_LOOKUP[B64URL:sub(index, index)] = index - 1
end
local B64STD = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local B64STD_LOOKUP = {}
for index = 1, #B64STD do
  B64STD_LOOKUP[B64STD:sub(index, index)] = index - 1
end

local function base64UrlEncode(value)
  local out = {}
  local index = 1
  while index <= #value do
    local a = byte(value, index) or 0
    local b = byte(value, index + 1)
    local c = byte(value, index + 2)
    local combined = a * 65536 + (b or 0) * 256 + (c or 0)
    out[#out + 1] = B64URL:sub(floor(combined / 262144) % 64 + 1, floor(combined / 262144) % 64 + 1)
    out[#out + 1] = B64URL:sub(floor(combined / 4096) % 64 + 1, floor(combined / 4096) % 64 + 1)
    if b ~= nil then
      out[#out + 1] = B64URL:sub(floor(combined / 64) % 64 + 1, floor(combined / 64) % 64 + 1)
    end
    if c ~= nil then
      out[#out + 1] = B64URL:sub(combined % 64 + 1, combined % 64 + 1)
    end
    index = index + 3
  end
  return concat(out)
end

local function base64Decode(value, expectedLength)
  if type(value) ~= 'string' then
    return nil, 'base64 input must be a string'
  end
  value = value:gsub('%s+', ''):gsub('=', '')
  if value:find('[^A-Za-z0-9%+%-_/]') then
    return nil, 'invalid base64 character'
  end
  if #value % 4 == 1 then
    return nil, 'invalid base64 length'
  end
  local out = {}
  local index = 1
  while index <= #value do
    local c1 = B64URL_LOOKUP[value:sub(index, index)] or B64STD_LOOKUP[value:sub(index, index)]
    local c2 = B64URL_LOOKUP[value:sub(index + 1, index + 1)] or B64STD_LOOKUP[value:sub(index + 1, index + 1)]
    local c3char = value:sub(index + 2, index + 2)
    local c4char = value:sub(index + 3, index + 3)
    local c3 = nil
    local c4 = nil
    if c3char ~= '' then
      c3 = B64URL_LOOKUP[c3char] or B64STD_LOOKUP[c3char]
    end
    if c4char ~= '' then
      c4 = B64URL_LOOKUP[c4char] or B64STD_LOOKUP[c4char]
    end
    if c1 == nil or c2 == nil or (c3char ~= '' and c3 == nil) or (c4char ~= '' and c4 == nil) then
      return nil, 'invalid base64 character'
    end
    local combined = c1 * 262144 + c2 * 4096 + (c3 or 0) * 64 + (c4 or 0)
    out[#out + 1] = char(floor(combined / 65536) % 256)
    if c3 ~= nil then
      out[#out + 1] = char(floor(combined / 256) % 256)
    end
    if c4 ~= nil then
      out[#out + 1] = char(combined % 256)
    end
    index = index + 4
  end
  local result = concat(out)
  if expectedLength ~= nil and #result ~= expectedLength then
    return nil, 'base64 value has the wrong length'
  end
  return result
end

local function bytesToString(values)
  local out = {}
  for index = 1, #values do
    out[index] = char(values[index])
  end
  return concat(out)
