  0x391c0cb3, 0xc5c95a63, 0x4ed8aa4a, 0xe3418acb, 0x5b9cca4f, 0x7763e373, 0x682e6ff3, 0xd6b2b8a3,
  0x748f82ee, 0x5defb2fc, 0x78a5636f, 0x43172f60, 0x84c87814, 0xa1f0ab72, 0x8cc70208, 0x1a6439ec,
  0x90befffa, 0x23631e28, 0xa4506ceb, 0xde82bde9, 0xbef9a3f7, 0xb2c67915, 0xc67178f2, 0xe372532b,
  0xca273ece, 0xea26619c, 0xd186b8c7, 0x21c0c207, 0xeada7dd6, 0xcde0eb1e, 0xf57d4f7f, 0xee6ed178,
  0x06f067aa, 0x72176fba, 0x0a637dc5, 0xa2c898a6, 0x113f9804, 0xbef90dae, 0x1b710b35, 0x131c471b,
  0x28db77f5, 0x23047d84, 0x32caab7b, 0x40c72493, 0x3c9ebe0a, 0x15c9bebc, 0x431d67c4, 0x9c100d4c,
  0x4cc5d4be, 0xcb3e42b6, 0x597f299c, 0xfc657e2a, 0x5fcb6fab, 0x3ad6faec, 0x6c44198c, 0x4a475817,
}

local SHA512_H = {
  0x6a09e667, 0xf3bcc908, 0xbb67ae85, 0x84caa73b, 0x3c6ef372, 0xfe94f82b, 0xa54ff53a, 0x5f1d36f1,
  0x510e527f, 0xade682d1, 0x9b05688c, 0x2b3e6c1f, 0x1f83d9ab, 0xfb41bd6b, 0x5be0cd19, 0x137e2179,
}

local function add64(ah, al, bh, bl)
  local lo = al + bl
  local hi = ah + bh
  if lo >= MASK32 then
    lo = lo - MASK32
    hi = hi + 1
  end
  return hi % MASK32, lo
end

local function rotr64(high, low, count)
  if count == 0 then
    return high, low
  elseif count < 32 then
    return bor(rshift(high, count), lshift(low, 32 - count)),
      bor(rshift(low, count), lshift(high, 32 - count))
  elseif count == 32 then
    return low, high
  else
    local shift = count - 32
    return bor(rshift(low, shift), lshift(high, 32 - shift)),
      bor(rshift(high, shift), lshift(low, 32 - shift))
  end
end

local function rshift64(high, low, count)
  if count == 0 then
    return high, low
  elseif count < 32 then
    return rshift(high, count), bor(rshift(low, count), lshift(high, 32 - count))
  elseif count == 32 then
    return 0, high
  elseif count < 64 then
    return 0, rshift(high, count - 32)
  end
  return 0, 0
end

local function sha512(message)
  local bytes = { byte(message, 1, #message) }
  local bitLength = #message * 8
  bytes[#bytes + 1] = 0x80
  while #bytes % 128 ~= 112 do
    bytes[#bytes + 1] = 0
  end
  -- The client only signs small JSON payloads, so the high 64 bits of the
  -- 128-bit length are always zero.
  for _ = 1, 8 do
    bytes[#bytes + 1] = 0
  end
  for shift = 56, 0, -8 do
    bytes[#bytes + 1] = floor(bitLength / 2 ^ shift) % 256
  end

  local HH = { SHA512_H[1], SHA512_H[3], SHA512_H[5], SHA512_H[7], SHA512_H[9], SHA512_H[11], SHA512_H[13], SHA512_H[15] }
  local HL = { SHA512_H[2], SHA512_H[4], SHA512_H[6], SHA512_H[8], SHA512_H[10], SHA512_H[12], SHA512_H[14], SHA512_H[16] }
  local WH = {}
  local WL = {}

  for blockStart = 1, #bytes, 128 do
    for index = 1, 16 do
      local offset = blockStart + (index - 1) * 8
      WH[index] = bytes[offset] * 16777216 + bytes[offset + 1] * 65536 + bytes[offset + 2] * 256 + bytes[offset + 3]
      WL[index] = bytes[offset + 4] * 16777216 + bytes[offset + 5] * 65536 + bytes[offset + 6] * 256 + bytes[offset + 7]
    end

    for index = 17, 80 do
      local h15, l15 = WH[index - 15], WL[index - 15]
      local s0h, s0l = rotr64(h15, l15, 1)
      local t1h, t1l = rotr64(h15, l15, 8)
      local t2h, t2l = rshift64(h15, l15, 7)
      s0h = bxor(bxor(s0h, t1h), t2h)
      s0l = bxor(bxor(s0l, t1l), t2l)

      local h2, l2 = WH[index - 2], WL[index - 2]
      local s1h, s1l = rotr64(h2, l2, 19)
      t1h, t1l = rotr64(h2, l2, 61)
      t2h, t2l = rshift64(h2, l2, 6)
      s1h = bxor(bxor(s1h, t1h), t2h)
      s1l = bxor(bxor(s1l, t1l), t2l)

      local sumH, sumL = add64(WH[index - 16], WL[index - 16], s0h, s0l)
      sumH, sumL = add64(sumH, sumL, WH[index - 7], WL[index - 7])
      WH[index], WL[index] = add64(sumH, sumL, s1h, s1l)
    end

    local ah, al = HH[1], HL[1]
    local bh, bl = HH[2], HL[2]
    local ch, cl = HH[3], HL[3]
    local dh, dl = HH[4], HL[4]
    local eh, el = HH[5], HL[5]
    local fh, fl = HH[6], HL[6]
    local gh, gl = HH[7], HL[7]
    local hh, hl = HH[8], HL[8]

    for index = 1, 80 do
      local S1h, S1l = rotr64(eh, el, 14)
      local t1h, t1l = rotr64(eh, el, 18)
      S1h = bxor(S1h, t1h)
      S1l = bxor(S1l, t1l)
      t1h, t1l = rotr64(eh, el, 41)
      S1h = bxor(S1h, t1h)
      S1l = bxor(S1l, t1l)

      local chh = bxor(band(eh, fh), band(bnot(eh), gh))
      local chl = bxor(band(el, fl), band(bnot(el), gl))

      local temp1h, temp1l = add64(hh, hl, S1h, S1l)
      temp1h, temp1l = add64(temp1h, temp1l, chh, chl)
      temp1h, temp1l = add64(temp1h, temp1l, SHA512_K[2 * index - 1], SHA512_K[2 * index])
      temp1h, temp1l = add64(temp1h, temp1l, WH[index], WL[index])

      local S0h, S0l = rotr64(ah, al, 28)
      t1h, t1l = rotr64(ah, al, 34)
      S0h = bxor(S0h, t1h)
      S0l = bxor(S0l, t1l)
      t1h, t1l = rotr64(ah, al, 39)
      S0h = bxor(S0h, t1h)
      S0l = bxor(S0l, t1l)

      local majh = bxor(bxor(band(ah, bh), band(ah, ch)), band(bh, ch))
      local majl = bxor(bxor(band(al, bl), band(al, cl)), band(bl, cl))

      local temp2h, temp2l = add64(S0h, S0l, majh, majl)

      hh, hl = gh, gl
      gh, gl = fh, fl
      fh, fl = eh, el
      eh, el = add64(dh, dl, temp1h, temp1l)
      dh, dl = ch, cl
      ch, cl = bh, bl
      bh, bl = ah, al
      ah, al = add64(temp1h, temp1l, temp2h, temp2l)
    end

    HH[1], HL[1] = add64(HH[1], HL[1], ah, al)
    HH[2], HL[2] = add64(HH[2], HL[2], bh, bl)
    HH[3], HL[3] = add64(HH[3], HL[3], ch, cl)
    HH[4], HL[4] = add64(HH[4], HL[4], dh, dl)
    HH[5], HL[5] = add64(HH[5], HL[5], eh, el)
    HH[6], HL[6] = add64(HH[6], HL[6], fh, fl)
    HH[7], HL[7] = add64(HH[7], HL[7], gh, gl)
    HH[8], HL[8] = add64(HH[8], HL[8], hh, hl)
  end

  local out = {}
  for index = 1, 8 do
    local high, low = HH[index], HL[index]
    out[#out + 1] = char(floor(high / 16777216) % 256)
    out[#out + 1] = char(floor(high / 65536) % 256)
    out[#out + 1] = char(floor(high / 256) % 256)
    out[#out + 1] = char(high % 256)
    out[#out + 1] = char(floor(low / 16777216) % 256)
    out[#out + 1] = char(floor(low / 65536) % 256)
    out[#out + 1] = char(floor(low / 256) % 256)
    out[#out + 1] = char(low % 256)
  end
  return concat(out)
end

----------------------------------------------------------------------
-- Ed25519 field arithmetic (16 x 16-bit limbs)
----------------------------------------------------------------------

local FE_LIMBS = 16
local FE_BASE = 65536

local FE_ZERO = {}
local FE_ONE = {}
local FE_P = {}
local FE_P2 = {}
for index = 1, FE_LIMBS do
  FE_ZERO[index] = 0
  FE_ONE[index] = index == 1 and 1 or 0
  FE_P[index] = index == 1 and 0xffed or (index == 16 and 0x7fff or 0xffff)
  FE_P2[index] = index == 1 and 0xffda or 0xffff
end

local function fe_copy(value)
  local copy = {}
  for index = 1, FE_LIMBS do
    copy[index] = value[index]
  end
  return copy
end

local function fe_compare(a, b)
  for index = FE_LIMBS, 1, -1 do
    if a[index] > b[index] then
      return 1
    elseif a[index] < b[index] then
      return -1
    end
  end
  return 0
end

local function fe_normalize(value)
  local carry = 0
  for index = 1, FE_LIMBS do
    local current = value[index] + carry
    carry = floor(current / FE_BASE)
    value[index] = current - carry * FE_BASE
  end
  while carry > 0 do
    local current = value[1] + carry * 38
    carry = floor(current / FE_BASE)
    value[1] = current - carry * FE_BASE
    local index = 2
    while carry > 0 and index <= FE_LIMBS do
      current = value[index] + carry
      carry = floor(current / FE_BASE)
      value[index] = current - carry * FE_BASE
      index = index + 1
    end
  end
  while fe_compare(value, FE_P) >= 0 do
    local borrow = 0
    for index = 1, FE_LIMBS do
      local current = value[index] - FE_P[index] - borrow
      if current < 0 then
        current = current + FE_BASE
        borrow = 1
      else
        borrow = 0
      end
      value[index] = current
    end
  end
  return value
end

local function fe_add(a, b)
  local result = {}
  local carry = 0
  for index = 1, FE_LIMBS do
    local current = a[index] + b[index] + carry
    carry = floor(current / FE_BASE)
    result[index] = current - carry * FE_BASE
  end
  if carry > 0 then
    result[1] = result[1] + carry * 38
  end
  return fe_normalize(result)
end

local function fe_sub(a, b)
  local result = {}
  local borrow = 0
  for index = 1, FE_LIMBS do
    local current = a[index] - b[index] - borrow
    if current < 0 then
      current = current + FE_BASE
      borrow = 1
    else
      borrow = 0
    end
    result[index] = current
  end
  if borrow == 1 then
    local carry = 0
    for index = 1, FE_LIMBS do
      local current = result[index] + FE_P[index] + carry
      carry = floor(current / FE_BASE)
      result[index] = current - carry * FE_BASE
    end
  end
  return result
end

local function fe_mul(a, b)
  local product = {}
  for index = 1, FE_LIMBS * 2 do
    product[index] = 0
  end
  for i = 1, FE_LIMBS do
    local ai = a[i]
    if ai ~= 0 then
      for j = 1, FE_LIMBS do
        product[i + j - 1] = product[i + j - 1] + ai * b[j]
      end
    end
  end
  -- 2^256 = 38 mod p
  for index = FE_LIMBS + 1, FE_LIMBS * 2 do
    product[index - FE_LIMBS] = product[index - FE_LIMBS] + product[index] * 38
  end
  local result = {}
  for index = 1, FE_LIMBS do
    result[index] = product[index]
  end
  return fe_normalize(result)
end

local function fe_sq(value)
  return fe_mul(value, value)
end

local function fe_neg(value)
  return fe_sub(FE_ZERO, value)
end

local function fe_is_zero(value)
  local normalized = fe_normalize(fe_copy(value))
  for index = 1, FE_LIMBS do
    if normalized[index] ~= 0 then
      return false
    end
  end
  return true
end

local function fe_is_negative(value)
  local normalized = fe_normalize(fe_copy(value))
  return normalized[1] % 2 == 1
end

local function fe_equal(a, b)
  local left = fe_normalize(fe_copy(a))
  local right = fe_normalize(fe_copy(b))
  for index = 1, FE_LIMBS do
    if left[index] ~= right[index] then
      return false
    end
  end
  return true
end

local function fe_lt(a, b)
  for index = FE_LIMBS, 1, -1 do
    if a[index] < b[index] then
      return true
    elseif a[index] > b[index] then
      return false
    end
  end
  return false
end

local function fe_from_bytes(value, strict)
  if type(value) ~= 'string' or #value ~= 32 then
    return nil, 'field element must be 32 bytes'
  end
  local result = {}
  for index = 1, FE_LIMBS do
    local low = byte(value, index * 2 - 1)
    local high = byte(value, index * 2)
    result[index] = low + high * 256
  end
  result[FE_LIMBS] = result[FE_LIMBS] % 32768
  if strict and not fe_lt(result, FE_P) then
    return nil, 'field element is not canonical'
  end
  return result
end

local function fe_to_bytes(value)
  local normalized = fe_normalize(fe_copy(value))
  local out = {}
  for index = 1, FE_LIMBS do
    out[#out + 1] = char(normalized[index] % 256)
    out[#out + 1] = char(floor(normalized[index] / 256))
  end
  return concat(out)
end

local function fe_pow22523(value)
  local t0 = fe_sq(value)
  local t1 = fe_sq(fe_sq(t0))
  t1 = fe_mul(value, t1)
  t0 = fe_mul(t0, t1)
  t0 = fe_sq(t0)
  t0 = fe_mul(t1, t0)
  t1 = fe_sq(t0)
  for _ = 2, 5 do t1 = fe_sq(t1) end
  t0 = fe_mul(t1, t0)
  t1 = fe_sq(t0)
  for _ = 2, 10 do t1 = fe_sq(t1) end
  t1 = fe_mul(t1, t0)
  local t2 = fe_sq(t1)
  for _ = 2, 20 do t2 = fe_sq(t2) end
  t1 = fe_mul(t2, t1)
  t1 = fe_sq(t1)
  for _ = 2, 10 do t1 = fe_sq(t1) end
  t0 = fe_mul(t1, t0)
  t1 = fe_sq(t0)
  for _ = 2, 50 do t1 = fe_sq(t1) end
  t1 = fe_mul(t1, t0)
  t2 = fe_sq(t1)
  for _ = 2, 100 do t2 = fe_sq(t2) end
  t1 = fe_mul(t2, t1)
  t1 = fe_sq(t1)
  for _ = 2, 50 do t1 = fe_sq(t1) end
  t0 = fe_mul(t1, t0)
  t0 = fe_sq(t0)
  t0 = fe_sq(t0)
  return fe_mul(t0, value)
end

local function fe_invert(value)
  local t0 = fe_sq(value)
  local t1 = fe_sq(fe_sq(t0))
  t1 = fe_mul(value, t1)
  t0 = fe_mul(t0, t1)
  local t2 = fe_sq(t0)
  t1 = fe_mul(t1, t2)
  t2 = fe_sq(t1)
  for _ = 2, 5 do t2 = fe_sq(t2) end
  t1 = fe_mul(t2, t1)
  t2 = fe_sq(t1)
  for _ = 2, 10 do t2 = fe_sq(t2) end
  t2 = fe_mul(t2, t1)
  local t3 = fe_sq(t2)
  for _ = 2, 20 do t3 = fe_sq(t3) end
  t2 = fe_mul(t3, t2)
  t2 = fe_sq(t2)
  for _ = 2, 10 do t2 = fe_sq(t2) end
  t1 = fe_mul(t2, t1)
  t2 = fe_sq(t1)
  for _ = 2, 50 do t2 = fe_sq(t2) end
  t2 = fe_mul(t2, t1)
  t3 = fe_sq(t2)
  for _ = 2, 100 do t3 = fe_sq(t3) end
  t2 = fe_mul(t3, t2)
  t2 = fe_sq(t2)
  for _ = 2, 50 do t2 = fe_sq(t2) end
  t1 = fe_mul(t2, t1)
  t1 = fe_sq(t1)
  for _ = 2, 5 do t1 = fe_sq(t1) end
  return fe_mul(t1, t0)
end

----------------------------------------------------------------------
-- Ed25519 curve constants
----------------------------------------------------------------------

local D_BYTES = hexDecode('a3785913ca4deb75abd841414d0a700098e879777940c78c73fe6f2bee6c0352')
local SQRTM1_BYTES = hexDecode('b0a00e4a271beec478e42fad0618432fa7d7fb3d99004d2b0bdfc14f8024832b')
local BASE_X_BYTES = hexDecode('1ad5258f602d56c9b2a7259560c72c695cdcd6fd31e2a4c0fe536ecdd3366921')
local BASE_Y_BYTES = hexDecode('5866666666666666666666666666666666666666666666666666666666666666')

local FE_D = fe_from_bytes(D_BYTES, true)
local FE_SQRTM1 = fe_from_bytes(SQRTM1_BYTES, true)
local FE_BASE_X = fe_from_bytes(BASE_X_BYTES, true)
local FE_BASE_Y = fe_from_bytes(BASE_Y_BYTES, true)
local TWO_D = fe_add(FE_D, FE_D)

local BASE_POINT = {
  X = FE_BASE_X,
  Y = FE_BASE_Y,
  Z = FE_ONE,
  T = fe_mul(FE_BASE_X, FE_BASE_Y),
}

----------------------------------------------------------------------
-- Ed25519 point arithmetic (extended coordinates)
----------------------------------------------------------------------

local function ge_identity()
  return { X = FE_ZERO, Y = FE_ONE, Z = FE_ONE, T = FE_ZERO }
end

local function ge_add(left, right)
  local a = fe_mul(fe_sub(left.Y, left.X), fe_sub(right.Y, right.X))
  local b = fe_mul(fe_add(left.Y, left.X), fe_add(right.Y, right.X))
  local c = fe_mul(fe_mul(left.T, TWO_D), right.T)
  local d = fe_mul(fe_add(left.Z, left.Z), right.Z)
  local e = fe_sub(b, a)
  local f = fe_sub(d, c)
  local g = fe_add(d, c)
  local h = fe_add(b, a)
  return {
    X = fe_mul(e, f),
    Y = fe_mul(g, h),
    T = fe_mul(e, h),
    Z = fe_mul(f, g),
  }
end

local function ge_double(point)
  local a = fe_sq(point.X)
  local b = fe_sq(point.Y)
  local c = fe_add(fe_sq(point.Z), fe_sq(point.Z))
  local d = fe_neg(a)
  local e = fe_sub(fe_sub(fe_sq(fe_add(point.X, point.Y)), a), b)
  local g = fe_add(d, b)
  local f = fe_sub(g, c)
  local h = fe_sub(d, b)
  return {
    X = fe_mul(e, f),
    Y = fe_mul(g, h),
    T = fe_mul(e, h),
    Z = fe_mul(f, g),
  }
end

local function ge_neg(point)
  return {
    X = fe_neg(point.X),
    Y = point.Y,
    Z = point.Z,
    T = fe_neg(point.T),
  }
end

local function ge_is_identity(point)
  return fe_is_zero(point.X) and fe_equal(point.Y, point.Z)
end

local function ge_equal(left, right)
  return fe_equal(fe_mul(left.X, right.Z), fe_mul(right.X, left.Z))
    and fe_equal(fe_mul(left.Y, right.Z), fe_mul(right.Y, left.Z))
end

local function ge_is_small_order(point)
  local doubled = ge_double(ge_double(ge_double(point)))
  return ge_is_identity(doubled)
end

local function ge_precompute(point)
  local tableValue = { ge_identity(), point }
  for index = 3, 16 do
    tableValue[index] = ge_add(tableValue[index - 1], point)
  end
  return tableValue
end

local function ge_scalarmult(point, scalar)
  local tableValue = ge_precompute(point)
  local result = ge_identity()
  for byteIndex = 32, 1, -1 do
    local current = byte(scalar, byteIndex)
    for _ = 1, 4 do result = ge_double(result) end
    local high = floor(current / 16)
    if high ~= 0 then
      result = ge_add(result, tableValue[high + 1])
    end
    for _ = 1, 4 do result = ge_double(result) end
    local low = current % 16
    if low ~= 0 then
      result = ge_add(result, tableValue[low + 1])
    end
  end
  return result
end

local function ge_scalarmult_double(firstPoint, firstScalar, secondPoint, secondScalar)
  local firstTable = ge_precompute(firstPoint)
  local secondTable = ge_precompute(secondPoint)
  local result = ge_identity()
  for byteIndex = 32, 1, -1 do
    local firstByte = byte(firstScalar, byteIndex)
    local secondByte = byte(secondScalar, byteIndex)
    for _ = 1, 4 do result = ge_double(result) end
    local high = floor(firstByte / 16)
    if high ~= 0 then
      result = ge_add(result, firstTable[high + 1])
    end
    high = floor(secondByte / 16)
    if high ~= 0 then
      result = ge_add(result, secondTable[high + 1])
    end
    for _ = 1, 4 do result = ge_double(result) end
    local low = firstByte % 16
    if low ~= 0 then
      result = ge_add(result, firstTable[low + 1])
    end
    low = secondByte % 16
    if low ~= 0 then
      result = ge_add(result, secondTable[low + 1])
    end
  end
  return result
end

local function ge_encode(point)
  local inverse = fe_invert(point.Z)
  local x = fe_mul(point.X, inverse)
  local y = fe_mul(point.Y, inverse)
  local encoded = fe_to_bytes(y)
  local out = {}
  for index = 1, 32 do
    out[index] = byte(encoded, index)
  end
  if fe_is_negative(x) then
    out[32] = out[32] + 128
  end
  return bytesToString(out)
end

local function ge_decode(value)
  if type(value) ~= 'string' or #value ~= 32 then
    return nil, 'point must be 32 bytes'
  end
  local sign = byte(value, 32) >= 128
  local y, yError = fe_from_bytes(value, true)
  if not y then
    return nil, yError
  end
  local y2 = fe_sq(y)
  local u = fe_sub(y2, FE_ONE)
  local v = fe_add(fe_mul(FE_D, y2), FE_ONE)
  local v3 = fe_mul(fe_sq(v), v)
  local v7 = fe_mul(fe_sq(v3), v)
  local x = fe_mul(u, v7)
  x = fe_pow22523(x)
  x = fe_mul(fe_mul(x, v3), u)
  local vx2 = fe_mul(v, fe_sq(x))
  if not fe_equal(vx2, u) then
    if fe_equal(vx2, fe_neg(u)) then
      x = fe_mul(x, FE_SQRTM1)
    else
      return nil, 'point is not on the curve'
    end
  end
  if fe_is_negative(x) ~= sign then
    x = fe_neg(x)
  end
  return {
    X = x,
    Y = y,
    Z = FE_ONE,
    T = fe_mul(x, y),
  }
end

----------------------------------------------------------------------
-- Ed25519 scalar arithmetic (mod L, 16-bit limbs)
----------------------------------------------------------------------

local SC_L = {
  0xd3ed, 0x5cf5, 0x631a, 0x5812, 0x9cd6, 0xa2f7, 0xf9de, 0x14de,
  0x0000, 0x0000, 0x0000, 0x0000, 0x0000, 0x0000, 0x0000, 0x1000,
}
local SC_L_INV = 0x7e1b
local SC_R2 = {
  0x0f01, 0x449c, 0x11e3, 0xa406, 0x9347, 0x6885, 0x1ba7, 0xd00e,
  0xbe65, 0x17f5, 0x73d2, 0xceec, 0x9a3d, 0x7c30, 0x411b, 0x0399,
}
local SC_ONE = {}
for index = 1, 16 do
  SC_ONE[index] = index == 1 and 1 or 0
end

local function sc_from_bytes(value, limbCount)
  local result = {}
  for index = 1, limbCount do
    local low = byte(value, index * 2 - 1) or 0
    local high = byte(value, index * 2) or 0
    result[index] = low + high * 256
  end
  return result
end

local function sc_to_bytes(value, limbCount)
  local out = {}
  for index = 1, limbCount do
    out[#out + 1] = char(value[index] % 256)
    out[#out + 1] = char(floor(value[index] / 256))
  end
  return concat(out)
end

local function sc_compare(a, b)
  for index = 16, 1, -1 do
    if a[index] > b[index] then
      return 1
    elseif a[index] < b[index] then
      return -1
    end
  end
  return 0
end

local function sc_add(a, b)
  local result = {}
  local carry = 0
  for index = 1, 16 do
    local current = a[index] + b[index] + carry
    carry = floor(current / 65536)
    result[index] = current - carry * 65536
  end
  return result, carry
end

local function sc_sub(a, b)
  local result = {}
  local borrow = 0
  for index = 1, 16 do
    local current = a[index] - b[index] - borrow
    if current < 0 then
      current = current + 65536
      borrow = 1
    else
      borrow = 0
    end
    result[index] = current
  end
  return result, borrow
end

local function sc_add_mod(a, b)
  local result, carry = sc_add(a, b)
  if carry > 0 or sc_compare(result, SC_L) >= 0 then
    result = sc_sub(result, SC_L)
  end
  return result
end

local function sc_sub_mod(a, b)
  if sc_compare(a, b) >= 0 then
    return (sc_sub(a, b))
  end
  local result = sc_sub(SC_L, b)
  return sc_add_mod(result, a)
end

local function sc_mul_raw(a, b)
  local product = {}
  for index = 1, 32 do
    product[index] = 0
  end
  for i = 1, 16 do
    local ai = a[i]
    if ai ~= 0 then
      for j = 1, 16 do
        product[i + j - 1] = product[i + j - 1] + ai * b[j]
      end
    end
  end
  local carry = 0
  for index = 1, 32 do
    local current = product[index] + carry
    carry = floor(current / 65536)
    product[index] = current - carry * 65536
  end
  return product
end

local function mont_reduce(product)
  product[33] = product[33] or 0
  for i = 1, 16 do
    local factor = (product[i] * SC_L_INV) % 65536
    local carry = 0
    for j = 1, 16 do
      local current = product[i + j - 1] + factor * SC_L[j] + carry
      product[i + j - 1] = current % 65536
      carry = floor(current / 65536)
    end
    local index = i + 16
    while carry > 0 do
      local current = (product[index] or 0) + carry
      product[index] = current % 65536
      carry = floor(current / 65536)
      index = index + 1
    end
  end
  local result = {}
  for index = 1, 16 do
    result[index] = product[index + 16]
  end
  while sc_compare(result, SC_L) >= 0 do
    result = sc_sub(result, SC_L)
  end
  return result
end

local function mont_mul(a, b)
  return mont_reduce(sc_mul_raw(a, b))
end

local function to_montgomery(value)
  return mont_mul(value, SC_R2)
end

local function from_montgomery(value)
  return mont_mul(value, SC_ONE)
end

local function sc_reduce_512(value)
  if type(value) ~= 'string' or #value ~= 64 then
    return nil, 'scalar hash must be 64 bytes'
  end
  local low = sc_from_bytes(value:sub(1, 32), 16)
  local high = sc_from_bytes(value:sub(33, 64), 16)
  local highR = mont_mul(high, SC_R2)
  return sc_add_mod(low, highR)
end

local function sc_muladd(multiplier, scalar, addend)
  local multiplierMont = to_montgomery(multiplier)
  local scalarMont = to_montgomery(scalar)
  local productMont = mont_mul(multiplierMont, scalarMont)
  local addendMont = to_montgomery(addend)
  local sumMont = sc_add_mod(productMont, addendMont)
  return from_montgomery(sumMont)
end

local function sc_is_canonical(value)
  return sc_compare(value, SC_L) < 0
end

----------------------------------------------------------------------
-- Ed25519 key generation, signing, and verification
----------------------------------------------------------------------

local function clamp_scalar(value)
  local bytes = {}
  for index = 1, 32 do
    bytes[index] = byte(value, index)
  end
  bytes[1] = band(bytes[1], 248)
  bytes[32] = bor(band(bytes[32], 127), 64)
  return bytesToString(bytes)
end

local function ed25519_keypair(seed)
  if type(seed) ~= 'string' or #seed ~= 32 then
    return nil, 'seed must be 32 bytes'
  end
  local hash = sha512(seed)
  local scalar = clamp_scalar(hash:sub(1, 32))
  local point = ge_scalarmult(BASE_POINT, scalar)
  local public = ge_encode(point)
  return public, seed .. public
end

local function ed25519_sign(seed, public, message)
  if type(seed) ~= 'string' or #seed ~= 32 then
    return nil, 'seed must be 32 bytes'
  end
  if type(public) ~= 'string' or #public ~= 32 then
    return nil, 'public key must be 32 bytes'
  end
  local hash = sha512(seed)
  local scalar = clamp_scalar(hash:sub(1, 32))
  local prefix = hash:sub(33, 64)
  local nonceHash = sha512(prefix .. message)
  local nonce = sc_reduce_512(nonceHash)
  if not nonce then
    return nil, 'could not reduce nonce'
  end
  local noncePoint = ge_scalarmult(BASE_POINT, sc_to_bytes(nonce, 16))
  local nonceBytes = ge_encode(noncePoint)
  local challengeHash = sha512(nonceBytes .. public .. message)
  local challenge = sc_reduce_512(challengeHash)
  if not challenge then
    return nil, 'could not reduce challenge'
  end
  local signatureScalar = sc_muladd(challenge, sc_from_bytes(scalar, 16), nonce)
  return nonceBytes .. sc_to_bytes(signatureScalar, 16)
end

local function ed25519_verify(public, message, signature)
  if type(public) ~= 'string' or #public ~= 32 then
    return false, 'public key must be 32 bytes'
  end
  if type(signature) ~= 'string' or #signature ~= 64 then
    return false, 'signature must be 64 bytes'
  end
  local nonceBytes = signature:sub(1, 32)
  local signatureScalarBytes = signature:sub(33, 64)
  local signatureScalar = sc_from_bytes(signatureScalarBytes, 16)
  if not sc_is_canonical(signatureScalar) then
    return false, 'signature scalar is not canonical'
  end
  local publicPoint, publicError = ge_decode(public)
  if not publicPoint then
    return false, publicError
  end
  if ge_is_small_order(publicPoint) then
    return false, 'public key has small order'
  end
  local noncePoint, nonceError = ge_decode(nonceBytes)
  if not noncePoint then
    return false, nonceError
  end
  if ge_is_small_order(noncePoint) then
    return false, 'nonce point has small order'
  end
  local challengeHash = sha512(nonceBytes .. public .. message)
  local challenge = sc_reduce_512(challengeHash)
  if not challenge then
    return false, 'could not reduce challenge'
  end
  local negatedPublic = ge_neg(publicPoint)
  local check = ge_scalarmult_double(
    BASE_POINT,
    signatureScalarBytes,
    negatedPublic,
    sc_to_bytes(challenge, 16)
  )
  if not ge_equal(check, noncePoint) then
    return false, 'signature does not verify'
  end
  return true
end

----------------------------------------------------------------------
-- X25519 (RFC 7748)
----------------------------------------------------------------------

local X25519_BASE_POINT = char(9) .. string.rep('\0', 31)

local function fe_from_small(value)
  local result = {}
  for index = 1, FE_LIMBS do
    result[index] = value % FE_BASE
    value = floor(value / FE_BASE)
  end
  return result
end

local FE_A24 = fe_from_small(121665)

--- Montgomery ladder over Curve25519. Returns the raw 32-byte shared point.
local function x25519_scalarmult(scalar, point)
  if type(scalar) ~= 'string' or #scalar ~= 32 then
    return nil, 'X25519 scalar must be 32 bytes'
  end
  if type(point) ~= 'string' or #point ~= 32 then
    return nil, 'X25519 point must be 32 bytes'
  end
  local clamped = {}
  for index = 1, 32 do
    clamped[index] = byte(scalar, index)
  end
  clamped[1] = clamped[1] - (clamped[1] % 8)
  clamped[32] = bor(clamped[32] % 128, 64)

  local x1 = fe_from_bytes(point, false)
  local x2 = fe_copy(FE_ONE)
  local z2 = fe_copy(FE_ZERO)
  local x3 = fe_copy(x1)
  local z3 = fe_copy(FE_ONE)
  local swap = 0

  for bitIndex = 254, 0, -1 do
    local byteIndex = floor(bitIndex / 8) + 1
    local bit = floor(clamped[byteIndex] / 2 ^ (bitIndex % 8)) % 2
    swap = bxor(swap, bit)
    if swap == 1 then
      x2, x3 = x3, x2
      z2, z3 = z3, z2
    end
    swap = bit

    local a = fe_add(x2, z2)
    local aa = fe_sq(a)
    local b = fe_sub(x2, z2)
    local bb = fe_sq(b)
    local e = fe_sub(aa, bb)
    local c = fe_add(x3, z3)
    local d = fe_sub(x3, z3)
    local da = fe_mul(d, a)
    local cb = fe_mul(c, b)
    x3 = fe_sq(fe_add(da, cb))
    z3 = fe_mul(x1, fe_sq(fe_sub(da, cb)))
    x2 = fe_mul(aa, bb)
    z2 = fe_mul(e, fe_add(aa, fe_mul(FE_A24, e)))
  end

  if swap == 1 then
    x2, x3 = x3, x2
    z2, z3 = z3, z2
  end
  return fe_to_bytes(fe_mul(x2, fe_invert(z2)))
end

local function x25519_base(scalar)
  return x25519_scalarmult(scalar, X25519_BASE_POINT)
end

----------------------------------------------------------------------
-- HMAC-SHA256 and HKDF-SHA256 (RFC 5869)
----------------------------------------------------------------------

local function hmacSha256(key, message)
  if type(key) ~= 'string' or type(message) ~= 'string' then
    return nil, 'HMAC inputs must be strings'
  end
  if #key > 64 then
    key = sha256(key)
  end
  key = key .. string.rep('\0', 64 - #key)
  local inner = {}
  local outer = {}
  for index = 1, 64 do
    local current = byte(key, index)
    inner[index] = char(bxor(current, 0x36))
    outer[index] = char(bxor(current, 0x5c))
  end
  return sha256(concat(outer) .. sha256(concat(inner) .. message))
end

local function hkdfSha256(ikm, salt, info, length)
  if type(ikm) ~= 'string' then
    return nil, 'HKDF input keying material must be a string'
  end
  if type(salt) ~= 'string' then
    return nil, 'HKDF salt must be a string'
  end
  info = info or ''
  if type(info) ~= 'string' then
    return nil, 'HKDF info must be a string'
  end
  if type(length) ~= 'number' or length % 1 ~= 0 or length < 1 or length > 255 * 32 then
    return nil, 'HKDF length must be between 1 and 8160 bytes'
  end
  if #salt == 0 then
    salt = string.rep('\0', 32)
  end
  local prk = hmacSha256(salt, ikm)
  if not prk then
    return nil, 'HKDF extract failed'
  end
  local blocks = {}
  local produced = 0
  local previous = ''
  local counter = 1
  while produced < length do
    previous = hmacSha256(prk, previous .. info .. char(counter))
    if not previous then
      return nil, 'HKDF expand failed'
    end
    blocks[#blocks + 1] = previous
    produced = produced + #previous
    counter = counter + 1
  end
  return concat(blocks):sub(1, length)
end

----------------------------------------------------------------------
-- ChaCha20 (RFC 8439)
----------------------------------------------------------------------

local CHACHA_CONSTANTS = { 0x61707865, 0x3320646e, 0x79622d32, 0x6b206574 }

local function add32(a, b)
  return (a + b) % MASK32
end

local function rotl32(value, count)
  return bor(lshift(value, count), rshift(value, 32 - count))
end

local function quarter_round(state, a, b, c, d)
  state[a] = add32(state[a], state[b])
  state[d] = rotl32(bxor(state[d], state[a]), 16)
  state[c] = add32(state[c], state[d])
  state[b] = rotl32(bxor(state[b], state[c]), 12)
  state[a] = add32(state[a], state[b])
  state[d] = rotl32(bxor(state[d], state[a]), 8)
  state[c] = add32(state[c], state[d])
  state[b] = rotl32(bxor(state[b], state[c]), 7)
end

local function chacha20_block(key, counter, nonce)
  if type(key) ~= 'string' or #key ~= 32 then
    return nil, 'ChaCha20 key must be 32 bytes'
  end
  if type(nonce) ~= 'string' or #nonce ~= 12 then
    return nil, 'ChaCha20 nonce must be 12 bytes'
  end
  local state = {
    CHACHA_CONSTANTS[1],
    CHACHA_CONSTANTS[2],
    CHACHA_CONSTANTS[3],
    CHACHA_CONSTANTS[4],
  }
  for index = 0, 7 do
    local offset = index * 4 + 1
    state[#state + 1] = byte(key, offset)
      + byte(key, offset + 1) * 256
      + byte(key, offset + 2) * 65536
      + byte(key, offset + 3) * 16777216
  end
  state[#state + 1] = counter % MASK32
  for index = 0, 2 do
    local offset = index * 4 + 1
    state[#state + 1] = byte(nonce, offset)
      + byte(nonce, offset + 1) * 256
      + byte(nonce, offset + 2) * 65536
      + byte(nonce, offset + 3) * 16777216
  end

  local working = {}
  for index = 1, 16 do
    working[index] = state[index]
  end
  for _ = 1, 10 do
    quarter_round(working, 1, 5, 9, 13)
    quarter_round(working, 2, 6, 10, 14)
    quarter_round(working, 3, 7, 11, 15)
    quarter_round(working, 4, 8, 12, 16)
    quarter_round(working, 1, 6, 11, 16)
    quarter_round(working, 2, 7, 12, 13)
    quarter_round(working, 3, 8, 9, 14)
    quarter_round(working, 4, 5, 10, 15)
  end

  local out = {}
  for index = 1, 16 do
    local value = add32(working[index], state[index])
    out[#out + 1] = char(value % 256)
    out[#out + 1] = char(floor(value / 256) % 256)
    out[#out + 1] = char(floor(value / 65536) % 256)
    out[#out + 1] = char(floor(value / 16777216) % 256)
  end
  return concat(out)
end

local function chacha20_xor(key, counter, nonce, data)
  local out = {}
  local index = 1
  while index <= #data do
    local block, blockError = chacha20_block(key, counter, nonce)
    if not block then
      return nil, blockError
    end
    local chunkLength = math.min(64, #data - index + 1)
    local chunk = {}
    for offset = 1, chunkLength do
      chunk[offset] = char(bxor(byte(data, index + offset - 1), byte(block, offset)))
    end
    out[#out + 1] = concat(chunk)
    index = index + chunkLength
    counter = (counter + 1) % MASK32
  end
  return concat(out)
end

----------------------------------------------------------------------
-- Poly1305 (10-bit limbs, base 2^10 so 2^130 = 1024^13)
----------------------------------------------------------------------

local POLY_BITS = 10
local POLY_LIMBS = 13
local POLY_MASK = 1023

local function poly_bytes_to_limbs(bytes, count)
  local limbs = {}
  for index = 1, POLY_LIMBS do
    limbs[index] = 0
  end
  local accumulator = 0
  local bits = 0
  local limb = 1
  for index = 1, count do
    accumulator = accumulator + bytes[index] * 2 ^ bits
    bits = bits + 8
    while bits >= POLY_BITS do
      if limb <= POLY_LIMBS then
        limbs[limb] = accumulator % 1024
      end
      accumulator = floor(accumulator / 1024)
      bits = bits - POLY_BITS
      limb = limb + 1
    end
  end
  if bits > 0 and limb <= POLY_LIMBS then
    limbs[limb] = limbs[limb] + accumulator
  end
  return limbs
end

local function poly1305(message, key)
  if type(key) ~= 'string' or #key ~= 32 then
    return nil, 'Poly1305 key must be 32 bytes'
  end
  local rBytes = {}
  for index = 1, 16 do
    rBytes[index] = byte(key, index)
  end
  -- r &= 0x0ffffffc0ffffffc0ffffffc0fffffff
  rBytes[4] = rBytes[4] % 16
  rBytes[8] = rBytes[8] % 16
  rBytes[12] = rBytes[12] % 16
  rBytes[16] = rBytes[16] % 16
  rBytes[5] = rBytes[5] - rBytes[5] % 4
  rBytes[9] = rBytes[9] - rBytes[9] % 4
  rBytes[13] = rBytes[13] - rBytes[13] % 4
  local r = poly_bytes_to_limbs(rBytes, 16)

  local h = {}
  for index = 1, POLY_LIMBS do
    h[index] = 0
  end

  local offset = 1
  while offset <= #message do
    local length = math.min(16, #message - offset + 1)
    local block = {}
    for index = 1, length do
      block[index] = byte(message, offset + index - 1)
    end
    block[length + 1] = 1
    local add = poly_bytes_to_limbs(block, length + 1)
    for index = 1, POLY_LIMBS do
      h[index] = h[index] + add[index]
    end

    local product = {}
    for index = 1, POLY_LIMBS * 2 do
      product[index] = 0
    end
    for i = 1, POLY_LIMBS do
      local hi = h[i]
      if hi ~= 0 then
        for j = 1, POLY_LIMBS do
          product[i + j - 1] = product[i + j - 1] + hi * r[j]
        end
      end
    end
    for index = POLY_LIMBS * 2, POLY_LIMBS + 1, -1 do
      local carry = product[index]
      product[index] = 0
      product[index - POLY_LIMBS] = product[index - POLY_LIMBS] + carry * 5
    end
    local carry = 0
    for index = 1, POLY_LIMBS do
      local value = product[index] + carry
      carry = floor(value / 1024)
      h[index] = value % 1024
    end
    while carry > 0 do
      h[1] = h[1] + carry * 5
      carry = 0
      for index = 1, POLY_LIMBS do
        local value = h[index] + carry
        carry = floor(value / 1024)
        h[index] = value % 1024
      end
    end

    offset = offset + length
  end

  -- Final conditional subtraction: if h + 5 >= 2^130 then h -= (2^130 - 5).
  local candidate = {}
  for index = 1, POLY_LIMBS do
    candidate[index] = h[index]
  end
  candidate[1] = candidate[1] + 5
  local carry = 0
  for index = 1, POLY_LIMBS do
    local value = candidate[index] + carry
    carry = floor(value / 1024)
    candidate[index] = value % 1024
  end
  local selected = h
  if carry > 0 then
    selected = candidate
  end

  local bytes = {}
  local accumulator = 0
  local bits = 0
  for index = 1, POLY_LIMBS do
    accumulator = accumulator + selected[index] * 2 ^ bits
    bits = bits + POLY_BITS
    while bits >= 8 do
      bytes[#bytes + 1] = accumulator % 256
      accumulator = floor(accumulator / 256)
      bits = bits - 8
    end
  end

  local tag = {}
  local tagCarry = 0
  for index = 1, 16 do
    local value = (bytes[index] or 0) + byte(key, 16 + index) + tagCarry
    tag[index] = value % 256
    tagCarry = floor(value / 256)
  end
  local out = {}
  for index = 1, 16 do
    out[index] = char(tag[index])
  end
  return concat(out)
end

----------------------------------------------------------------------
-- ChaCha20-Poly1305 AEAD (RFC 8439)
----------------------------------------------------------------------

local function pad16(value)
  local remainder = #value % 16
  if remainder == 0 then
    return value
  end
  return value .. string.rep('\0', 16 - remainder)
end

local function le64(value)
  local out = {}
  for _ = 1, 8 do
    out[#out + 1] = char(value % 256)
    value = floor(value / 256)
  end
  return concat(out)
end

local function aead_mac_data(aad, ciphertext)
  return pad16(aad)
    .. pad16(ciphertext)
    .. le64(#aad)
    .. le64(#ciphertext)
end

local function chacha20_poly1305_encrypt(key, nonce, plaintext, aad)
  if type(key) ~= 'string' or #key ~= 32 then
    return nil, 'ChaCha20-Poly1305 key must be 32 bytes'
  end
  if type(nonce) ~= 'string' or #nonce ~= 12 then
    return nil, 'ChaCha20-Poly1305 nonce must be 12 bytes'
  end
  if type(plaintext) ~= 'string' then
    return nil, 'ChaCha20-Poly1305 plaintext must be a string'
  end
  aad = aad or ''
  local block, blockError = chacha20_block(key, 0, nonce)
  if not block then
    return nil, blockError
  end
  local ciphertext, cipherError = chacha20_xor(key, 1, nonce, plaintext)
  if not ciphertext then
    return nil, cipherError
  end
  local tag, tagError = poly1305(aead_mac_data(aad, ciphertext), block:sub(1, 32))
  if not tag then
    return nil, tagError
  end
  return ciphertext .. tag
end

local function chacha20_poly1305_decrypt(key, nonce, data, aad)
  if type(key) ~= 'string' or #key ~= 32 then
    return nil, 'ChaCha20-Poly1305 key must be 32 bytes'
  end
  if type(nonce) ~= 'string' or #nonce ~= 12 then
    return nil, 'ChaCha20-Poly1305 nonce must be 12 bytes'
  end
  if type(data) ~= 'string' or #data < 16 then
    return nil, 'ChaCha20-Poly1305 ciphertext is truncated'
  end
  aad = aad or ''
  local ciphertext = data:sub(1, #data - 16)
  local tag = data:sub(#data - 15)
  local block, blockError = chacha20_block(key, 0, nonce)
  if not block then
    return nil, blockError
  end
  local expected, tagError = poly1305(aead_mac_data(aad, ciphertext), block:sub(1, 32))
  if not expected then
    return nil, tagError
  end
  local difference = 0
  for index = 1, 16 do
    difference = bor(difference, bxor(byte(tag, index), byte(expected, index)))
  end
  if difference ~= 0 then
    return nil, 'ChaCha20-Poly1305 authentication tag mismatch'
  end
  return chacha20_xor(key, 1, nonce, ciphertext)
end

----------------------------------------------------------------------
-- Backend factory
----------------------------------------------------------------------

function PureCrypto.new(options)
  options = options or {}
  local randomBytes = options.randomBytes
  if type(randomBytes) ~= 'function' then
    return nil, 'pure crypto requires a randomBytes function'
  end

  local crypto = {}

  function crypto.generateKeyPair()
    local seed, randomError = randomBytes(32)
    if type(seed) ~= 'string' or #seed ~= 32 then
      error(randomError or 'CSPRNG did not return 32 bytes', 2)
    end
    local public, secret = ed25519_keypair(seed)
    if not public then
      error(secret, 2)
    end
    return {
      publicKey = base64UrlEncode(public),
      secretKey = base64UrlEncode(secret),
    }
  end

  function crypto.sign(message, secretKey)
    local raw = base64Decode(secretKey, 64)
    if not raw then
      error('secret key must be base64url-encoded 64 bytes', 2)
    end
    local signature, signError = ed25519_sign(raw:sub(1, 32), raw:sub(33, 64), message)
    if not signature then
      error(signError, 2)
    end
    return base64UrlEncode(signature)
  end

  function crypto.verify(message, signature, publicKey)
    local rawSignature = base64Decode(signature, 64)
    local rawPublic = base64Decode(publicKey, 32)
    if not rawSignature or not rawPublic then
      return false
    end
    local valid = ed25519_verify(rawPublic, message, rawSignature)
    return valid == true
  end

  function crypto.randomHex(byteCount)
    local raw, randomError = randomBytes(byteCount)
    if type(raw) ~= 'string' or #raw ~= byteCount then
      error(randomError or 'CSPRNG returned the wrong number of bytes', 2)
    end
    return hexEncode(raw)
  end

  function crypto.sha256Hex(data)
    return hexEncode(sha256(data))
  end

  function crypto.sha256Base64Url(encoded)
    local raw = base64Decode(encoded, 32)
    if not raw then
      error('public key must be base64url-encoded 32 bytes', 2)
    end
    return base64UrlEncode(sha256(raw))
  end

  return crypto
end

-- Exported for tests and for callers that need the primitives directly.
PureCrypto.sha256 = sha256
PureCrypto.sha512 = sha512
PureCrypto.ed25519_keypair = ed25519_keypair
PureCrypto.ed25519_sign = ed25519_sign
PureCrypto.ed25519_verify = ed25519_verify
PureCrypto.x25519Scalarmult = x25519_scalarmult
PureCrypto.x25519Base = x25519_base
PureCrypto.hmacSha256 = hmacSha256
PureCrypto.hkdfSha256 = hkdfSha256
PureCrypto.chacha20Block = chacha20_block
PureCrypto.chacha20Xor = chacha20_xor
PureCrypto.poly1305 = poly1305
PureCrypto.chacha20Poly1305Encrypt = chacha20_poly1305_encrypt
PureCrypto.chacha20Poly1305Decrypt = chacha20_poly1305_decrypt
PureCrypto.base64UrlEncode = base64UrlEncode
PureCrypto.base64Decode = base64Decode
PureCrypto.hexEncode = hexEncode
PureCrypto.hexDecode = hexDecode

return PureCrypto
end

__wl_modules["security"] = function()
-- Cryptography, encoding, storage, and response-signature verification for the
-- whitelist Lua client.
--
-- Ed25519 is delegated to the executor's native implementation by default.
-- Executors without native Ed25519 (for example Potassium) can opt into the
-- bundled pure-Lua implementation with `crypto = "pure"`. The rest of this
-- module performs encoding, framing, and validation around whichever backend
-- is selected. The same public interface also accepts an injected encoded
-- backend for tests or for executors that expose a different native API.

local Json = __wl_require('json')

local Security = {}

local BASE64URL_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'
local BASE64URL_LOOKUP = {}
for index = 1, #BASE64URL_ALPHABET do
  BASE64URL_LOOKUP[BASE64URL_ALPHABET:sub(index, index)] = index - 1
end

local HEX_LOOKUP = {}
for index = 0, 15 do
  HEX_LOOKUP[string.format('%x', index)] = index
end

local TELEMETRY_TYPES = {
  UNEXPECTED_RESPONSE_STRUCTURE = true,
  INVALID_RESPONSE_SIGNATURE = true,
  NONCE_REUSE = true,
  REPEATED_REQUEST_ID = true,
  INVALID_SESSION_TRANSITION = true,
  UNEXPECTED_CONTENT_TYPE = true,
  PROTOCOL_SEQUENCE_VIOLATION = true,
  SUSPICIOUS_AUTH_PATTERN = true,
  TRANSPORT_TAMPERED = true,
  INTEGRITY_VIOLATION = true,
}

local SEVERITIES = {
  INFO = true,
  LOW = true,
  MEDIUM = true,
  HIGH = true,
  CRITICAL = true,
}

local SECRET_KEY_PATTERNS = {
  'token',
  'secret',
  'private',
  'password',
  'licensekey',
  'authorization',
  'cookie',
  'signature',
  'seed',
  'apikey',
}

local function isTable(value)
  return type(value) == 'table'
end

local function trim(value)
  return (value:gsub('^%s+', ''):gsub('%s+$', ''))
end

local function isBase64Url(value)
  return type(value) == 'string' and #value > 0 and value:find('^[A-Za-z0-9_-]+$') ~= nil
end

local function isHex(value)
  return type(value) == 'string' and #value > 0 and #value % 2 == 0 and value:find('^[0-9a-fA-F]+$') ~= nil
end

local function encodeBase64Url(raw)
  if type(raw) ~= 'string' then
    error('base64url input must be a string', 2)
  end
  local out = {}
  local index = 1
  while index <= #raw do
    local a = raw:byte(index) or 0
    local b = raw:byte(index + 1)
    local c = raw:byte(index + 2)
    local value = a * 65536 + (b or 0) * 256 + (c or 0)
    local c1 = math.floor(value / 262144) % 64
    local c2 = math.floor(value / 4096) % 64
    local c3 = math.floor(value / 64) % 64
    local c4 = value % 64
    out[#out + 1] = BASE64URL_ALPHABET:sub(c1 + 1, c1 + 1)
    out[#out + 1] = BASE64URL_ALPHABET:sub(c2 + 1, c2 + 1)
    if b ~= nil then
      out[#out + 1] = BASE64URL_ALPHABET:sub(c3 + 1, c3 + 1)
    end
    if c ~= nil then
      out[#out + 1] = BASE64URL_ALPHABET:sub(c4 + 1, c4 + 1)
    end
    index = index + 3
  end
  return table.concat(out)
end

local function decodeBase64Url(value, expectedLength)
  if type(value) ~= 'string' then
    return nil, 'base64url input must be a string'
  end
  local padding = 0
  if value:sub(-1) == '=' then
    padding = padding + 1
    value = value:sub(1, -2)
  end
  if value:sub(-1) == '=' then
    padding = padding + 1
    value = value:sub(1, -2)
  end
  if value:find('=', 1, true) then
    return nil, 'base64url padding is only allowed at the end'
  end
  if padding > 0 and #value % 4 ~= 2 and #value % 4 ~= 3 then
    return nil, 'invalid base64url padding'
  end
  if #value % 4 == 1 then
    return nil, 'invalid base64url length'
  end
  local out = {}
  local index = 1
  while index <= #value do
    local c1 = BASE64URL_LOOKUP[value:sub(index, index)]
    local c2 = BASE64URL_LOOKUP[value:sub(index + 1, index + 1)]
    local c3 = BASE64URL_LOOKUP[value:sub(index + 2, index + 2)]
    local c4 = BASE64URL_LOOKUP[value:sub(index + 3, index + 3)]
    if c1 == nil or c2 == nil then
      return nil, 'invalid base64url character'
    end
    if c3 == nil and c4 ~= nil then
      return nil, 'invalid base64url character'
    end
    local combined = c1 * 262144 + c2 * 4096 + (c3 or 0) * 64 + (c4 or 0)
    out[#out + 1] = string.char(math.floor(combined / 65536) % 256)
    if c3 ~= nil then
      out[#out + 1] = string.char(math.floor(combined / 256) % 256)
    end
    if c4 ~= nil then
      out[#out + 1] = string.char(combined % 256)
    end
    index = index + 4
  end
  local raw = table.concat(out)
  if expectedLength ~= nil and #raw ~= expectedLength then
    return nil, string.format('decoded length must be %d bytes, got %d', expectedLength, #raw)
  end
  return raw
end

local function encodeHex(raw)
  if type(raw) ~= 'string' then
    error('hex input must be a string', 2)
  end
  local out = {}
  for index = 1, #raw do
    out[#out + 1] = string.format('%02x', raw:byte(index))
  end
  return table.concat(out)
end

local function decodeHex(value)
  if not isHex(value) then
    return nil, 'invalid hexadecimal encoding'
  end
  local out = {}
  for index = 1, #value, 2 do
    local high = HEX_LOOKUP[value:sub(index, index):lower()]
    local low = HEX_LOOKUP[value:sub(index + 1, index + 1):lower()]
    if high == nil or low == nil then
      return nil, 'invalid hexadecimal character'
    end
    out[#out + 1] = string.char(high * 16 + low)
  end
  return table.concat(out)
end

local function toRawString(value)
  if type(value) == 'string' then
    return value
  end
  if type(value) == 'buffer' then
    local ok, result = pcall(function()
      return buffer.tostring(value)
    end)
    if ok and type(result) == 'string' then
      return result
    end
  end
  if type(value) == 'userdata' then
    local ok, result = pcall(tostring, value)
    if ok and type(result) == 'string' and #result > 0 then
      return result
    end
  end
  return nil
end

local function normalizeBinary(value, expectedLength, label)
  local raw = toRawString(value)
  if raw == nil then
    return nil, label .. ' must be a string or buffer'
  end
  if #raw == expectedLength then
    return raw
  end
  if #raw == expectedLength * 2 and isHex(raw) then
    return decodeHex(raw)
  end
  if expectedLength == 32 and (#raw == 43 or #raw == 44) then
    return decodeBase64Url(raw, 32)
  end
  if expectedLength == 64 and (#raw == 86 or #raw == 88) then
    return decodeBase64Url(raw, 64)
  end
  return nil, string.format('%s must encode exactly %d bytes', label, expectedLength)
end

local function getExecutorEnv()
  local env = _G
  if type(getgenv) == 'function' then
    local ok, generated = pcall(getgenv)
    if ok and isTable(generated) then
      env = generated
    end
  end
  return env
end

local function getCryptTable()
  local env = getExecutorEnv()
  local crypt = env.crypt
  if type(crypt) ~= 'table' and type(_G.crypt) == 'table' then
    crypt = _G.crypt
  end
  return crypt, env
end

local function getFunction(container, names)
  if type(container) ~= 'table' then
    return nil, nil
  end
  for _, name in ipairs(names) do
    local value = container[name]
    if type(value) == 'function' then
      return value, name
    end
  end
  return nil, nil
end

local function normalizeBase64(value)
  return (value:gsub('%+', '-'):gsub('/', '_'):gsub('=', ''))
end

-- Returns a function that produces raw CSPRNG bytes. The pure-Lua Ed25519
-- backend needs this for key generation and nonces; the executor still owns
-- the entropy source.
local function getExecutorRandomBytes()
  local crypt = getCryptTable()
  if type(crypt) ~= 'table' then
    return nil, 'Executor CSPRNG is unavailable; pure crypto requires crypt.generatebytes'
  end
  local randomFn = getFunction(crypt, { 'generatebytes', 'generate_bytes', 'random' })
  if not randomFn then
    return nil, 'Executor CSPRNG is unavailable; pure crypto requires crypt.generatebytes'
  end
  return function(byteCount)
    local ok, value = pcall(randomFn, byteCount)
    if not ok then
      return nil, 'CSPRNG failed: ' .. tostring(value)
    end
    local raw = toRawString(value)
    if raw == nil or #raw == 0 then
      return nil, 'CSPRNG returned no entropy'
    end
    if #raw == byteCount then
      return raw
    end
    if #raw == byteCount * 2 and isHex(raw) then
      return decodeHex(raw)
    end
    local decoded = decodeBase64Url(normalizeBase64(raw), byteCount)
    if decoded then
      return decoded
    end
    if #raw >= byteCount then
      return raw:sub(1, byteCount)
    end
    return nil, 'CSPRNG returned insufficient entropy'
  end
end

local function normalizeHashResult(value)
  local raw = toRawString(value)
  if raw == nil then
    return nil
  end
  if #raw == 32 then
    return encodeHex(raw)
  end
  if #raw == 64 and isHex(raw) then
    return raw:lower()
  end
  if #raw == 43 or #raw == 44 then
    local decoded = decodeBase64Url(raw, 32)
    if decoded then
      return encodeHex(decoded)
    end
  end
  if #raw == 88 then
    local decoded = decodeBase64Url(raw, 32)
    if decoded then
      return encodeHex(decoded)
    end
  end
  return nil
end

local function normalizeBase64UrlDigest(value)
  if type(value) ~= 'string' then
    return nil
  end
  if #value == 43 or #value == 44 then
    local raw = decodeBase64Url(value, 32)
    if raw then
      return encodeBase64Url(raw)
    end
  end
  if #value == 64 and isHex(value) then
    local raw = decodeHex(value)
    if raw then
      return encodeBase64Url(raw)
    end
  end
  return nil
end

local function createExecutorBackend(config)
  local crypt = getCryptTable()
  if type(crypt) ~= 'table' then
    return nil, 'Executor crypt library is unavailable; Ed25519 cannot be performed'
  end

  local keypairFn, keypairName = getFunction(crypt, {
    'ed25519_keypair',
    'ed25519_keygen',
    'ed25519_generate_keypair',
    'signkeygen',
    'sign_keygen',
    'signcreate',
    'sign_create',
  })
  local signFn, signName = getFunction(crypt, {
    'ed25519_sign',
    'ed25519sign',
    'sign',
  })
  local verifyFn, verifyName = getFunction(crypt, {
    'ed25519_verify',
    'ed25519verify',
    'signopen',
    'sign_open',
  })
  local randomFn, randomName = getFunction(crypt, {
    'generatebytes',
    'generate_bytes',
    'random',
  })
  local hashFn, hashName = getFunction(crypt, {
    'hash',
    'sha256',
    'sha256hex',
    'sha256_hex',
  })

  if not keypairFn or not signFn or not verifyFn then
    return nil, 'Executor does not expose an Ed25519 keypair, sign, and verify API'
  end

  local verifyReturnsMessage = verifyName == 'signopen' or verifyName == 'sign_open'
  local hashMode = nil

  local backend = {}

  function backend.generateKeyPair()
    local ok, first, second = pcall(keypairFn)
    if not ok then
      return nil, 'Ed25519 key generation failed: ' .. tostring(first)
    end

    local publicValue = first
    local secretValue = second
    if isTable(first) then
      publicValue = first.publicKey or first.public_key or first.public or first.pk
      secretValue = first.secretKey or first.secret_key or first.secret or first.privateKey or first.private_key or first.sk
    end
    if publicValue == nil or secretValue == nil then
      return nil, 'Ed25519 key generation returned an unexpected value'
    end

    -- Executor keypair APIs differ in whether the secret is a 32-byte seed, a
    -- 64-byte libsodium secret, or a hex/base64 representation of either. Some
    -- also return (secret, public) instead of (public, secret). Build every
    -- plausible candidate and keep only the one that actually signs and
    -- verifies against the advertised public key.
    local function tryPair(candidatePublic, candidateSecret)
      local publicRaw, publicError = normalizeBinary(candidatePublic, 32, 'public key')
      if not publicRaw then
        return nil, publicError
      end
      local secretRaw = toRawString(candidateSecret)
      if secretRaw == nil then
        return nil, 'Ed25519 key generation returned an unreadable secret key'
      end
      local candidates = {}
      local function addCandidate(value)
        if value ~= nil and #value > 0 then
          candidates[#candidates + 1] = value
        end
      end
      if #secretRaw == 32 then
        addCandidate(secretRaw .. publicRaw)
        addCandidate(secretRaw)
      elseif #secretRaw == 64 then
        addCandidate(secretRaw)
        if isHex(secretRaw) then
          local decoded = decodeHex(secretRaw)
          if decoded then
            addCandidate(decoded .. publicRaw)
            addCandidate(decoded)
          end
        end
      elseif #secretRaw == 128 and isHex(secretRaw) then
        local decoded = decodeHex(secretRaw)
        if decoded then
          addCandidate(decoded)
        end
      elseif #secretRaw == 43 or #secretRaw == 44 then
        local decoded = decodeBase64Url(secretRaw)
        if decoded then
          addCandidate(decoded .. publicRaw)
          addCandidate(decoded)
        end
      elseif #secretRaw == 86 or #secretRaw == 88 then
        local decoded = decodeBase64Url(secretRaw)
        if decoded then
          addCandidate(decoded)
        end
      else
        addCandidate(secretRaw)
      end

      local testMessage = 'whitelist-keypair-self-test'
      for _, candidate in ipairs(candidates) do
        if #candidate == 64 then
          local signature = backend.sign(testMessage, encodeBase64Url(candidate), encodeBase64Url(publicRaw))
          if signature and backend.verify(testMessage, signature, encodeBase64Url(publicRaw)) then
            return {
              publicKey = encodeBase64Url(publicRaw),
              secretKey = encodeBase64Url(candidate),
              keypairFunction = keypairName,
            }
          end
        end
      end
      return nil, 'Ed25519 key generation returned a secret key that could not sign'
    end

    local pair, pairError = tryPair(publicValue, secretValue)
    if pair then
      return pair
    end
    if second ~= nil and second ~= first then
      local swapped, swappedError = tryPair(second, first)
      if swapped then
        return swapped
      end
      pairError = swappedError or pairError
    end
    return nil, pairError
  end

  function backend.sign(message, secretKey, publicKey)
    local secretRaw, secretError = decodeBase64Url(secretKey, 64)
    if not secretRaw then
      return nil, 'Stored signing key is invalid: ' .. secretError
    end
    local publicRaw = nil
    if publicKey then
      local decoded, publicError = decodeBase64Url(publicKey, 32)
      if not decoded then
        return nil, 'Public key is invalid: ' .. publicError
      end
      publicRaw = decoded
    end

    local seed = secretRaw:sub(1, 32)
    local secretCandidates = {
      secretRaw,
      seed,
      encodeHex(secretRaw),
      encodeHex(seed),
      encodeBase64Url(secretRaw),
      encodeBase64Url(seed),
    }
    local attempts = {}
    for _, secret in ipairs(secretCandidates) do
      attempts[#attempts + 1] = function()
        return signFn(message, secret)
      end
      attempts[#attempts + 1] = function()
        return signFn(secret, message)
      end
    end

    local lastError = nil
    for _, attempt in ipairs(attempts) do
      local ok, value = pcall(attempt)
      if ok and value ~= nil then
        local signatureRaw, signatureError = normalizeBinary(value, 64, 'signature')
        if signatureRaw then
          if publicRaw == nil or backend.verify(message, encodeBase64Url(signatureRaw), publicKey) then
            return encodeBase64Url(signatureRaw)
          end
        else
          lastError = signatureError
        end
      elseif not ok then
        lastError = tostring(value)
      end
    end
    return nil, 'Ed25519 signing failed: ' .. tostring(lastError or 'invalid signature output')
  end

  function backend.verify(message, signature, publicKey)
    local signatureRaw, signatureError = decodeBase64Url(signature, 64)
    if not signatureRaw then
      return false, signatureError
    end
    local publicRaw, publicError = decodeBase64Url(publicKey, 32)
    if not publicRaw then
      return false, publicError
    end

    local publicCandidates = {
      publicRaw,
      encodeHex(publicRaw),
      encodeBase64Url(publicRaw),
    }
    local signatureCandidates = {
      signatureRaw,
      encodeHex(signatureRaw),
      encodeBase64Url(signatureRaw),
    }
    local attempts = {}
    for _, publicValue in ipairs(publicCandidates) do
      for _, signatureValue in ipairs(signatureCandidates) do
        attempts[#attempts + 1] = function()
          return verifyFn(message, signatureValue, publicValue)
        end
        attempts[#attempts + 1] = function()
          return verifyFn(signatureValue, message, publicValue)
        end
        attempts[#attempts + 1] = function()
          return verifyFn(publicValue, signatureValue, message)
        end
      end
    end
    for _, attempt in ipairs(attempts) do
      local ok, result = pcall(attempt)
      if ok then
        if result == true then
          return true
        end
        if verifyReturnsMessage and type(result) == 'string' then
          if result == message then
            return true
          end
        end
      end
    end
    return false
  end

  function backend.randomHex(byteCount)
    local ok, value = pcall(randomFn, byteCount)
    if not ok then
      return nil, 'CSPRNG failed: ' .. tostring(value)
    end
    local raw = toRawString(value)
    if raw == nil or #raw == 0 then
      return nil, 'CSPRNG returned no entropy'
    end
    if #raw == byteCount then
      return encodeHex(raw)
    end
    if #raw == byteCount * 2 and isHex(raw) then
      local decoded = decodeHex(raw)
      if decoded then
        return encodeHex(decoded)
      end
    end
    local decoded = decodeBase64Url(raw, byteCount)
    if decoded then
      return encodeHex(decoded)
    end
    if #raw < byteCount then
      return nil, 'CSPRNG returned insufficient entropy'
    end
    return encodeHex(raw:sub(1, byteCount))
  end

  function backend.sha256Hex(data)
    if not hashFn then
      return nil, 'Executor does not expose a SHA-256 implementation'
    end
    if hashMode == 'data_algorithm' then
      local ok, value = pcall(hashFn, data, 'sha256')
      if ok then
        local normalized = normalizeHashResult(value)
        if normalized then
          return normalized
        end
      end
    elseif hashMode == 'algorithm_data' then
      local ok, value = pcall(hashFn, 'sha256', data)
      if ok then
        local normalized = normalizeHashResult(value)
        if normalized then
          return normalized
        end
      end
    elseif hashMode == 'data_only' then
      local ok, value = pcall(hashFn, data)
      if ok then
        local normalized = normalizeHashResult(value)
        if normalized then
          return normalized
        end
      end
    else
      local attempts = {
        { mode = 'data_algorithm', args = { data, 'sha256' } },
        { mode = 'algorithm_data', args = { 'sha256', data } },
        { mode = 'data_only', args = { data } },
      }
      for _, attempt in ipairs(attempts) do
        local ok, value = pcall(hashFn, table.unpack(attempt.args))
        if ok then
          local normalized = normalizeHashResult(value)
          if normalized then
            hashMode = attempt.mode
            return normalized
          end
        end
      end
    end
    return nil, 'SHA-256 hashing failed'
  end

  function backend.publicKeyId(publicKey)
    local raw, decodeError = decodeBase64Url(publicKey, 32)
    if not raw then
      return nil, decodeError
    end
    local hex, hashError = backend.sha256Hex(raw)
    if not hex then
      return nil, hashError
    end
    local digest, digestError = decodeHex(hex)
    if not digest then
      return nil, digestError
    end
    return encodeBase64Url(digest)
  end

  backend.kind = 'executor'
  backend.names = {
    keypair = keypairName,
    sign = signName,
    verify = verifyName,
    random = randomName,
    hash = hashName,
  }
  return backend
end

local function createEncodedBackend(config)
  local crypto = config.crypto
  if type(crypto) ~= 'table' then
    return nil, 'crypto must be a table'
  end
  local keypairFn = crypto.generateKeyPair or crypto.keypair
  local signFn = crypto.sign
  local verifyFn = crypto.verify
  local randomFn = crypto.randomHex
  local hashFn = crypto.sha256Hex
  local hashBase64UrlFn = crypto.sha256Base64Url

  if type(keypairFn) ~= 'function' or type(signFn) ~= 'function' or type(verifyFn) ~= 'function' or type(randomFn) ~= 'function' then
    return nil, 'crypto must provide generateKeyPair/keypair, sign, verify, and randomHex functions'
  end

  local backend = {}
  function backend.generateKeyPair()
    local ok, result = pcall(keypairFn)
    if not ok or type(result) ~= 'table' then
      return nil, 'Injected Ed25519 key generation failed: ' .. tostring(result)
    end
    local publicKey = result.publicKey or result.public or result.public_key
    local secretKey = result.secretKey or result.secret or result.privateKey or result.private_key
    local publicRaw, publicError = decodeBase64Url(publicKey, 32)
    if not publicRaw then
      return nil, 'Injected public key is invalid: ' .. tostring(publicError)
    end
    local secretRaw, secretError = decodeBase64Url(secretKey, 64)
    if not secretRaw then
      local shortSecret = decodeBase64Url(secretKey, 32)
      if not shortSecret then
        return nil, 'Injected secret key is invalid: ' .. tostring(secretError)
      end
      secretRaw = shortSecret .. publicRaw
    end
    return {
      publicKey = encodeBase64Url(publicRaw),
      secretKey = encodeBase64Url(secretRaw),
      keypairFunction = 'injected',
    }
  end

  function backend.sign(message, secretKey, publicKey)
    local ok, signature = pcall(signFn, message, secretKey)
    if not ok or type(signature) ~= 'string' then
      return nil, 'Injected Ed25519 signing failed: ' .. tostring(signature)
    end
    local signatureRaw, signatureError = decodeBase64Url(signature, 64)
    if not signatureRaw then
      return nil, 'Injected signature is invalid: ' .. tostring(signatureError)
    end
    if publicKey then
      local valid = backend.verify(message, encodeBase64Url(signatureRaw), publicKey)
      if not valid then
        return nil, 'Injected Ed25519 signature failed self-verification'
      end
    end
    return encodeBase64Url(signatureRaw)
  end

  function backend.verify(message, signature, publicKey)
    local ok, result = pcall(verifyFn, message, signature, publicKey)
    if not ok then
      return false, tostring(result)
    end
    return result == true
  end

  function backend.randomHex(byteCount)
    local ok, value = pcall(randomFn, byteCount)
    if not ok or type(value) ~= 'string' then
      return nil, 'Injected CSPRNG failed: ' .. tostring(value)
    end
    if #value ~= byteCount * 2 or not isHex(value) then
      return nil, 'Injected CSPRNG must return a hexadecimal string with 2 characters per byte'
    end
    return value:lower()
  end

  function backend.sha256Hex(data)
    if type(hashFn) ~= 'function' then
      return nil, 'Injected crypto backend does not provide SHA-256'
    end
    local ok, value = pcall(hashFn, data)
    if not ok or type(value) ~= 'string' or #value ~= 64 or not isHex(value) then
      return nil, 'Injected SHA-256 failed'
    end
    return value:lower()
  end

  function backend.publicKeyId(publicKey)
    if type(hashBase64UrlFn) ~= 'function' then
      -- Hashing a raw public key through an arbitrary injected backend is not
      -- portable: some host runtimes expose strings as UTF-8 text rather than
      -- bytes. Skip the local key-id check instead of accepting a wrong hash.
      return nil, 'Injected crypto backend does not provide base64url key hashing'
    end
    local ok, value = pcall(hashBase64UrlFn, publicKey)
    if not ok then
      return nil, 'Injected public key hashing failed: ' .. tostring(value)
    end
    local normalized = normalizeBase64UrlDigest(value)
    if not normalized then
      return nil, 'Injected public key hash is not a SHA-256 digest'
    end
    return normalized
  end

  backend.kind = 'injected'
  return backend
end

local function createMemoryStorage()
  local data = {}
  return {
    read = function(path)
      if data[path] == nil then
        return nil
      end
      return data[path]
    end,
    write = function(path, contents)
      if type(path) ~= 'string' or type(contents) ~= 'string' then
        return nil, 'Storage write requires string path and contents'
      end
      data[path] = contents
      return true
    end,
    exists = function(path)
      return data[path] ~= nil
    end,
    delete = function(path)
      data[path] = nil
      return true
    end,
  }
end

local function createFileStorage(root)
  local env = getExecutorEnv()
  local readfile = env.readfile or _G.readfile
  local writefile = env.writefile or _G.writefile
  local isfile = env.isfile or _G.isfile
  local makefolder = env.makefolder or _G.makefolder
  local delfile = env.delfile or _G.delfile

  if type(readfile) ~= 'function' or type(writefile) ~= 'function' then
    return nil, 'Executor file APIs are unavailable; configure storage.adapter to persist the device identity and signing key'
  end

  local function ensureFolder(path)
    if type(makefolder) ~= 'function' then
      return
    end
    local current = ''
    for segment in path:gmatch('[^/]+') do
      if current == '' then
        current = segment
      else
        current = current .. '/' .. segment
      end
      pcall(makefolder, current)
    end
  end

  local function parentFolder(path)
    return path:match('^(.*)/[^/]+$') or ''
  end

  local storage = {}

  function storage.read(path)
    if type(isfile) == 'function' then
      local ok, exists = pcall(isfile, path)
      if ok and not exists then
        return nil
      end
    end
    local ok, value = pcall(readfile, path)
    if not ok then
      return nil, tostring(value)
    end
    return value
  end

  function storage.write(path, contents)
    if type(path) ~= 'string' or type(contents) ~= 'string' then
      return nil, 'Storage write requires string path and contents'
    end
    local folder = parentFolder(path)
    if folder ~= '' then
      ensureFolder(folder)
    end
    local ok, value = pcall(writefile, path, contents)
    if not ok then
      return nil, tostring(value)
    end
    return true
  end

  function storage.exists(path)
    if type(isfile) == 'function' then
      local ok, value = pcall(isfile, path)
      if ok then
        return value == true
      end
    end
    local value = storage.read(path)
    return value ~= nil
  end

  function storage.delete(path)
    if type(delfile) == 'function' then
      local ok, value = pcall(delfile, path)
      if not ok then
        return nil, tostring(value)
      end
    end
    return true
  end

  return storage
end

local function getStorage(config)
  local storageConfig = config.storage or {}
  if storageConfig.adapter ~= nil then
    local adapter = storageConfig.adapter
    return {
      read = adapter.read,
      write = adapter.write,
      exists = adapter.exists,
      delete = adapter.delete or function()
        return true
      end,
    }
  end
  return createFileStorage(storageConfig.root or 'whitelist')
end

local function normalizeKeyRecord(record, index)
  if type(record) ~= 'table' then
    return nil, string.format('keyring entry %d is not a table', index)
  end
  if type(record.localId) ~= 'string' or not record.localId:find('^[A-Za-z0-9_-]+$') or #record.localId > 64 then
    return nil, string.format('keyring entry %d has an invalid localId', index)
  end
  local publicRaw, publicError = decodeBase64Url(record.publicKey, 32)
  if not publicRaw then
    return nil, string.format('keyring entry %d has an invalid public key: %s', index, tostring(publicError))
  end
  local secretRaw, secretError = decodeBase64Url(record.secretKey, 64)
  if not secretRaw then
    local shortSecret = decodeBase64Url(record.secretKey, 32)
    if not shortSecret then
      return nil, string.format('keyring entry %d has an invalid secret key: %s', index, tostring(secretError))
    end
    secretRaw = shortSecret .. publicRaw
  end
  if record.keyId ~= nil and (type(record.keyId) ~= 'string' or not isBase64Url(record.keyId) or #record.keyId > 64) then
    return nil, string.format('keyring entry %d has an invalid keyId', index)
  end
  if record.status ~= nil and type(record.status) ~= 'string' then
    return nil, string.format('keyring entry %d has an invalid status', index)
  end
  return {
    localId = record.localId,
    keyId = record.keyId,
    publicKey = encodeBase64Url(publicRaw),
    secretKey = encodeBase64Url(secretRaw),
    name = type(record.name) == 'string' and record.name or nil,
    status = record.status or 'PENDING',
    createdAt = type(record.createdAt) == 'number' and record.createdAt or os.time(),
    licenseId = type(record.licenseId) == 'string' and record.licenseId or nil,
  }
end

local function newKeyring()
  return {
    version = 1,
    current = nil,
    keys = Json.array({}),
  }
end

local function sanitizeKeyName(key)
  local normalized = tostring(key):lower():gsub('[^%w]', '')
  for _, pattern in ipairs(SECRET_KEY_PATTERNS) do
    if normalized:find(pattern, 1, true) then
      return true
    end
  end
  return false
end

local function sanitizeDetailsValue(value, depth, seen)
  if depth > 3 then
    return '[depth]'
  end
  local valueType = type(value)
  if valueType == 'string' then
    if #value > 256 then
      return value:sub(1, 256) .. '...'
    end
    return value
  elseif valueType == 'number' or valueType == 'boolean' then
    return value
  elseif valueType == 'table' then
    if seen[value] then
      return '[cycle]'
    end
    seen[value] = true
    local out = {}
    local isArray = Json.isArray(value)
    if isArray then
      local count = 0
      for index = 1, #value do
        if count >= 20 then
          break
        end
        out[index] = sanitizeDetailsValue(value[index], depth + 1, seen)
        count = count + 1
      end
    else
      local count = 0
      for key, item in pairs(value) do
        if count >= 20 then
          break
        end
        local keyString = tostring(key)
        if not sanitizeKeyName(keyString) then
          out[keyString] = sanitizeDetailsValue(item, depth + 1, seen)
          count = count + 1
        end
      end
    end
    seen[value] = nil
    return out
  elseif value == nil then
    return Json.null
  end
  return tostring(value)
end

local function sanitizeDetails(details, maxBytes)
  if details == nil then
    return nil
  end
  if type(details) ~= 'table' then
    details = { value = details }
  end
  local sanitized = sanitizeDetailsValue(details, 0, {})
  local encoded = Json.encode(sanitized)
  if encoded == nil or #encoded > maxBytes then
    return {
      truncated = true,
      note = 'Client telemetry details exceeded the configured size limit',
    }
  end
  return sanitized
end

local function validateIso8601(value)
  if type(value) ~= 'string' then
    return false
  end
  return value:find('^%d%d%d%d%-%d%d%-%d%dT%d%d:%d%d:%d%d') ~= nil
end

local function timegm(tableValue)
  local epoch = os.time(tableValue)
  if not epoch then
    return nil
  end
  local utcAsLocal = os.time(os.date('!*t', epoch))
  if not utcAsLocal then
    return nil
  end
  local offset = epoch - utcAsLocal
  return epoch + offset
end

function Security.new(config)
  if type(config) ~= 'table' then
    return nil, 'config must be resolved before creating the security layer'
  end
  local storage, storageError = getStorage(config)
  if not storage then
    return nil, storageError
  end
  local backend, backendError
  if config.crypto == 'pure' then
    local randomBytes, randomError = getExecutorRandomBytes()
    if not randomBytes then
      return nil, randomError
    end
    local PureCrypto = __wl_require('pure_crypto')
    local cryptoTable, cryptoError = PureCrypto.new({ randomBytes = randomBytes })
    if not cryptoTable then
      return nil, cryptoError
    end
    backend, backendError = createEncodedBackend({ crypto = cryptoTable })
  elseif config.crypto ~= nil then
    backend, backendError = createEncodedBackend(config)
  else
    backend, backendError = createExecutorBackend(config)
  end
  if not backend then
    return nil, backendError
  end

  local root = (config.storage and config.storage.root) or 'whitelist'
  root = root:gsub('/+$', '')
  local self = setmetatable({
    config = config,
    storage = storage,
    backend = backend,
    root = root,
    keyringPath = root .. '/keys.json',
    devicePath = root .. '/device_id',
    requestIds = {},
    requestOrder = {},
  }, { __index = Security })
  return self
end

function Security.memoryStorage()
  return createMemoryStorage()
end

function Security.fileStorage(root)
  return createFileStorage(root)
end

Security.encodeBase64Url = encodeBase64Url
Security.decodeBase64Url = decodeBase64Url
Security.encodeHex = encodeHex
Security.decodeHex = decodeHex
Security.isBase64Url = isBase64Url

function Security:log(level, message, fields)
  if type(self.config.logger) == 'function' then
    pcall(self.config.logger, level, message, fields)
  end
end

function Security:randomHex(byteCount)
  if type(byteCount) ~= 'number' or byteCount % 1 ~= 0 or byteCount < 1 or byteCount > 128 then
    return nil, 'randomHex byte count must be an integer between 1 and 128'
  end
  return self.backend.randomHex(byteCount)
end

--- Returns raw CSPRNG bytes for the application-encryption layer.
function Security:randomBytes(byteCount)
  local hex, hexError = self:randomHex(byteCount)
  if not hex then
    return nil, hexError
  end
  local raw, decodeError = decodeHex(hex)
  if not raw or #raw ~= byteCount then
    return nil, decodeError or 'CSPRNG returned malformed bytes'
  end
  return raw
end

function Security:sha256Hex(data)
  if type(data) ~= 'string' then
    return nil, 'SHA-256 input must be a string'
  end
  return self.backend.sha256Hex(data)
end

function Security:sha256Base64Url(data)
  local hex, err = self:sha256Hex(data)
  if not hex then
    return nil, err
  end
  local raw, decodeError = decodeHex(hex)
  if not raw then
    return nil, decodeError
  end
  return encodeBase64Url(raw)
end

--- Derives the protocol key identifier from a base64url Ed25519 public key.
--- Returns nil when the backend cannot hash raw bytes, in which case callers
--- skip the optional local consistency check.
function Security:publicKeyId(publicKey)
  if type(publicKey) ~= 'string' then
    return nil, 'Public key must be a string'
  end
  if type(self.backend.publicKeyId) ~= 'function' then
    return nil, 'Crypto backend does not support key identifier derivation'
  end
  return self.backend.publicKeyId(publicKey)
end

function Security:generateKeyPair()
  local pair, err = self.backend.generateKeyPair()
  if not pair then
    return nil, err
  end
  local publicRaw, publicError = decodeBase64Url(pair.publicKey, 32)
  if not publicRaw then
    return nil, 'Generated public key is invalid: ' .. tostring(publicError)
  end
  local secretRaw, secretError = decodeBase64Url(pair.secretKey, 64)
  if not secretRaw then
    return nil, 'Generated secret key is invalid: ' .. tostring(secretError)
  end
  local testMessage = 'whitelist-key-self-test'
  local signature, signError = self.backend.sign(testMessage, pair.secretKey, pair.publicKey)
  if not signature then
    return nil, 'Generated signing key failed its self-test: ' .. tostring(signError)
  end
  local valid = self.backend.verify(testMessage, signature, pair.publicKey)
  if not valid then
    return nil, 'Generated signing key failed self-verification'
  end
  return {
    publicKey = encodeBase64Url(publicRaw),
    secretKey = encodeBase64Url(secretRaw),
    createdAt = os.time(),
    status = 'PENDING',
  }
end

function Security:sign(message, secretKey, publicKey)
  if type(message) ~= 'string' then
    return nil, 'Message to sign must be a string'
  end
  return self.backend.sign(message, secretKey, publicKey)
end

function Security:verify(message, signature, publicKey)
  if type(message) ~= 'string' then
    return false
  end
  return self.backend.verify(message, signature, publicKey)
end

function Security:newRequestId(prefix)
  local safePrefix = tostring(prefix or 'req'):gsub('[^%w]', '')
  if safePrefix == '' then
    safePrefix = 'req'
  end
  if #safePrefix > 24 then
    safePrefix = safePrefix:sub(1, 24)
  end
  for _ = 1, 4 do
    local random, err = self:randomHex(16)
    if not random then
      return nil, err
    end
    local requestId = 'wl-' .. safePrefix .. '-' .. random
    if not self.requestIds[requestId] then
      self.requestIds[requestId] = true
      self.requestOrder[#self.requestOrder + 1] = requestId
      if #self.requestOrder > 256 then
        local oldest = table.remove(self.requestOrder, 1)
        self.requestIds[oldest] = nil
      end
      return requestId
    end
  end
  return nil, 'REPEATED_REQUEST_ID'
end

function Security:loadKeyring()
  local raw, readError = self.storage.read(self.keyringPath)
  if readError then
    return nil, 'Unable to read the signing keyring: ' .. tostring(readError)
  end
  if raw == nil or raw == '' then
    return newKeyring()
  end
  local parsed, decodeError = Json.decode(raw)
  if not parsed then
    return nil, 'Signing keyring is not valid JSON: ' .. tostring(decodeError)
  end
  if type(parsed) ~= 'table' or parsed.version ~= 1 then
    return nil, 'Signing keyring has an unsupported format'
  end
  if type(parsed.keys) ~= 'table' then
    return nil, 'Signing keyring is missing the keys array'
  end
  local keyring = newKeyring()
  local seen = {}
  for index, record in ipairs(parsed.keys) do
    local normalized, recordError = normalizeKeyRecord(record, index)
    if not normalized then
      return nil, recordError
    end
    if seen[normalized.localId] then
      return nil, 'Signing keyring contains a duplicate localId'
    end
    seen[normalized.localId] = true
    keyring.keys[#keyring.keys + 1] = normalized
  end
  if parsed.current ~= nil then
    if type(parsed.current) ~= 'string' then
      return nil, 'Signing keyring current entry is invalid'
    end
    local found = nil
    for _, record in ipairs(keyring.keys) do
      if record.localId == parsed.current then
        found = record
        break
      end
    end
    if not found then
      return nil, 'Signing keyring current entry does not exist'
    end
    keyring.current = parsed.current
  end
  return keyring
end

function Security:saveKeyring(keyring)
  if type(keyring) ~= 'table' or type(keyring.keys) ~= 'table' then
    return nil, 'Invalid signing keyring'
  end
  local encoded, encodeError = Json.encode(keyring)
  if not encoded then
    return nil, 'Unable to encode the signing keyring: ' .. tostring(encodeError)
  end
  return self.storage.write(self.keyringPath, encoded)
end

function Security:findKey(keyring, identifier)
  if type(keyring) ~= 'table' or type(identifier) ~= 'string' then
    return nil
  end
  for _, record in ipairs(keyring.keys) do
    if record.localId == identifier or record.keyId == identifier then
      return record
    end
  end
  return nil
end

function Security:currentKey(keyring)
  if type(keyring) ~= 'table' or keyring.current == nil then
    return nil
  end
  return self:findKey(keyring, keyring.current)
end

function Security:addKey(keyring, record)
  if type(keyring) ~= 'table' or type(record) ~= 'table' then
    return nil, 'Invalid keyring or key record'
  end
  for _, existing in ipairs(keyring.keys) do
    if existing.localId == record.localId then
      return nil, 'Key record already exists'
    end
  end
  keyring.keys[#keyring.keys + 1] = record
  return record
end

function Security:removeKey(keyring, identifier)
  if type(keyring) ~= 'table' or type(identifier) ~= 'string' then
    return nil, 'Invalid keyring or key identifier'
  end
  for index, record in ipairs(keyring.keys) do
    if record.localId == identifier or record.keyId == identifier then
      table.remove(keyring.keys, index)
      if keyring.current == record.localId then
        keyring.current = nil
      end
      return record
    end
  end
  return nil, 'Key record not found'
end

function Security:getOrCreateDeviceId()
  local raw, readError = self.storage.read(self.devicePath)
  if readError then
    return nil, 'Unable to read the device identity: ' .. tostring(readError)
  end
  if raw ~= nil and raw ~= '' then
    local deviceId = trim(raw)
    if #deviceId < 8 or #deviceId > 128 or not deviceId:find('^[A-Za-z0-9._:-]+$') then
      return nil, 'Stored device identity is invalid; refusing to replace it automatically'
    end
    return deviceId
  end

  local random, randomError = self:randomHex(16)
  if not random then
    return nil, randomError
  end
  local deviceId = 'wl-' .. random
  local saved, saveError = self.storage.write(self.devicePath, deviceId)
  if not saved then
    return nil, 'Unable to persist the device identity: ' .. tostring(saveError)
  end
  return deviceId
end

function Security:parseIso8601Utc(value)
  if type(value) ~= 'string' then
    return nil
  end
  local year, month, day, hour, minute, second, rest = value:match(
    '^(%d%d%d%d)%-(%d%d)%-(%d%d)T(%d%d):(%d%d):(%d%d)(.*)$'
  )
  if not year then
    return nil
  end
  year, month, day = tonumber(year), tonumber(month), tonumber(day)
  hour, minute, second = tonumber(hour), tonumber(minute), tonumber(second)
  if year < 1970 or year > 9999 or month < 1 or month > 12 or day < 1 or day > 31 then
    return nil
  end
  if hour > 23 or minute > 59 or second > 60 then
    return nil
  end

  local offset = 0
  if rest == '' or rest == 'Z' or rest == 'z' then
    offset = 0
  elseif rest:find('^%.%d+[Zz]?$') then
    offset = 0
  else
    local sign, offsetHour, offsetMinute = rest:match('^([+-])(%d%d):?(%d%d)$')
    if not sign then
      return nil
    end
    offsetHour, offsetMinute = tonumber(offsetHour), tonumber(offsetMinute)
    if offsetHour > 23 or offsetMinute > 59 then
      return nil
    end
    offset = (offsetHour * 3600 + offsetMinute * 60) * (sign == '+' and 1 or -1)
  end

  local epoch = timegm({
    year = year,
    month = month,
    day = day,
    hour = hour,
    min = minute,
    sec = second,
    isdst = false,
  })
  if not epoch then
    return nil
  end
  return epoch - offset
end

function Security:formatIso8601Utc(epoch)
  if type(epoch) ~= 'number' then
    epoch = os.time()
  end
  return os.date('!%Y-%m-%dT%H:%M:%SZ', epoch)
end

function Security:sanitizeTelemetryEvent(event, limits)
  if type(event) ~= 'table' then
    return nil, 'Telemetry event must be a table'
  end
  limits = limits or {}
  local eventType = event.type
  if type(eventType) ~= 'string' or not TELEMETRY_TYPES[eventType] then
    return nil, 'Unknown telemetry event type'
  end
  local severity = event.severity or 'LOW'
  if type(severity) ~= 'string' or not SEVERITIES[severity] then
    return nil, 'Invalid telemetry severity'
  end

  local message = event.message
  if type(message) ~= 'string' then
    message = tostring(message or eventType)
  end
  message = message:gsub('[%z\1-\31\127]', ' ')
  message = trim(message)
  local maxMessageLength = limits.maxMessageLength or 300
  if #message > maxMessageLength then
    message = message:sub(1, maxMessageLength)
  end
  if message == '' then
    message = eventType
  end

  local requestId = event.requestId
  if requestId ~= nil then
    if type(requestId) ~= 'string' or #requestId < 8 or #requestId > 128 or not requestId:find('^[A-Za-z0-9._:-]+$') then
      requestId = nil
    end
  end

  local occurredAt = event.occurredAt
  if not validateIso8601(occurredAt) then
    occurredAt = self:formatIso8601Utc(os.time())
  end

  local sanitized = {
    type = eventType,
    severity = severity,
    message = message,
    details = sanitizeDetails(event.details, limits.maxDetailsBytes or 2048),
    occurredAt = occurredAt,
    requestId = requestId,
  }
  return sanitized
end

function Security:verifyResponseSignature(response, trustedKey, now)
  if type(response) ~= 'table' or type(response.headers) ~= 'table' then
    return nil, 'Response is missing headers'
  end
  if type(trustedKey) ~= 'table' or type(trustedKey.publicKey) ~= 'string' then
    return nil, 'Trusted server key is not configured'
  end
  local timestamp = response.headers['x-response-timestamp']
  local keyId = response.headers['x-response-key-id']
  local signature = response.headers['x-response-signature']
  if timestamp == nil or keyId == nil or signature == nil then
    return nil, 'Response signature headers are missing'
  end
  local timestampNumber = tonumber(timestamp)
  if not timestampNumber or timestampNumber % 1 ~= 0 or timestampNumber < 1 then
    return nil, 'Response timestamp is invalid'
  end
  now = now or os.time()
  if math.abs(now - timestampNumber) > self.config.maxClockSkewSeconds then
    return nil, 'Response signature timestamp is outside the allowed clock skew'
  end
  if trustedKey.keyId ~= nil and keyId ~= trustedKey.keyId then
    return nil, 'Response was signed by an unexpected server key'
  end
  if type(response.body) ~= 'string' then
    return nil, 'Response body is not a raw string and cannot be verified'
  end
  local payload = timestamp .. '.' .. response.body
  local valid, verifyError = self:verify(payload, signature, trustedKey.publicKey)
  if not valid then
    return nil, 'Response signature is invalid' .. (verifyError and (': ' .. tostring(verifyError)) or '')
  end
  if trustedKey.keyId ~= nil then
    local computed = self:publicKeyId(trustedKey.publicKey)
    if computed ~= nil and computed ~= keyId then
      return nil, 'Response key identifier does not match the public key'
    end
  end
  return true
end

return Security
end

__wl_modules["secure_channel"] = function()
-- Application-layer encryption for the whitelist Lua client.
--
-- Every license-facing request is sealed with X25519 ECDH + HKDF-SHA256 +
-- ChaCha20-Poly1305 before it leaves the executor. The server answers with the
-- same construction using an independent response key, so a passive observer
-- that already sees TLS traffic still cannot read the protocol payloads.
--
-- The X25519/AEAD primitives live in pure_crypto.lua. They are bundled rather
-- than delegated to the executor because no common executor exposes X25519 or
-- ChaCha20-Poly1305. Ed25519 signing still uses the configured security
-- backend. This layer is defense-in-depth on top of TLS, not a replacement for
-- it: a hooked executor can always observe plaintext before it is encrypted.

local Json = __wl_require('json')
local PureCrypto = __wl_require('pure_crypto')

local SecureChannel = {}
SecureChannel.__index = SecureChannel

local VERSION = 1
local INFO = 'whitelist-app-encryption-v1'
local REQUEST_AAD = 'whitelist-request-v1'
local RESPONSE_AAD = 'whitelist-response-v1'
local KEY_BYTES = 32
local NONCE_BYTES = 12
local TAG_BYTES = 16
local MIN_RANDOM_BYTES = 24

SecureChannel.ENCRYPTED_CONTENT_TYPE = 'application/vnd.wl.encrypted+json'
SecureChannel.REQUEST_HEADER = 'x-encrypted-request'
SecureChannel.RESPONSE_HEADER = 'x-response-encrypted'

local function allZero(value)
  for index = 1, #value do
    if string.byte(value, index) ~= 0 then
      return false
    end
  end
  return true
end

--- Creates a channel bound to one server X25519 public key.
---
--- The ephemeral keypair lives for the lifetime of this client instance. Each
--- request still uses a fresh random AEAD nonce. `options.security` supplies
--- the CSPRNG and base64url helpers; `options.serverPublicKey` is the raw
--- 32-byte server key encoded as base64url.
function SecureChannel.new(options)
  options = options or {}
  local security = options.security
  if type(security) ~= 'table' or type(security.randomBytes) ~= 'function' then
    return nil, 'security layer is required for application encryption'
  end

  local serverPublicRaw = security.decodeBase64Url(options.serverPublicKey, KEY_BYTES)
  if not serverPublicRaw then
    return nil, 'server encryption public key is not a 32-byte base64url value'
  end

  local ephemeralPrivate, randomError = security:randomBytes(KEY_BYTES)
  if not ephemeralPrivate then
    return nil, randomError
  end

  local ephemeralPublic, publicError = PureCrypto.x25519Base(ephemeralPrivate)
  if not ephemeralPublic then
    return nil, publicError
  end

  local shared, sharedError = PureCrypto.x25519Scalarmult(ephemeralPrivate, serverPublicRaw)
  if not shared then
    return nil, sharedError
  end
  if allZero(shared) then
    return nil, 'X25519 produced an all-zero shared secret'
  end

  local salt = ephemeralPublic .. serverPublicRaw
  local okm, hkdfError = PureCrypto.hkdfSha256(shared, salt, INFO, KEY_BYTES * 2)
  if not okm then
    return nil, hkdfError
  end

  return setmetatable({
    security = security,
    ephemeralPublic = security.encodeBase64Url(ephemeralPublic),
    requestKey = okm:sub(1, KEY_BYTES),
    responseKey = okm:sub(KEY_BYTES + 1, KEY_BYTES * 2),
  }, SecureChannel)
end

--- Returns a fresh base64url nonce suitable for a request signature.
function SecureChannel:signatureNonce()
  local random, randomError = self.security:randomBytes(MIN_RANDOM_BYTES)
  if not random then
    return nil, randomError
  end
  return self.security.encodeBase64Url(random)
end

--- Encrypts a canonical inner request and returns its wire envelope.
function SecureChannel:seal(inner)
  local plaintext, encodeError = Json.encode(inner)
  if not plaintext then
    return nil, encodeError
  end
  return self:sealPlaintext(plaintext)
end

--- Encrypts an already-serialized inner request.
function SecureChannel:sealPlaintext(plaintext)
  if type(plaintext) ~= 'string' then
    return nil, 'request plaintext must be a string'
  end
  local nonce, randomError = self.security:randomBytes(NONCE_BYTES)
  if not nonce then
    return nil, randomError
  end
  local sealed, sealError = PureCrypto.chacha20Poly1305Encrypt(
    self.requestKey,
    nonce,
    plaintext,
    REQUEST_AAD
  )
  if not sealed then
    return nil, sealError
  end
  return {
    v = VERSION,
    epk = self.ephemeralPublic,
    nonce = self.security.encodeBase64Url(nonce),
    data = self.security.encodeBase64Url(sealed),
  }
end

--- Serializes an envelope for the compact request header form.
function SecureChannel.headerValue(envelope)
  if type(envelope) ~= 'table' then
    return nil, 'encryption envelope is required'
  end
  return table.concat({
    'v' .. tostring(envelope.v),
    envelope.epk,
    envelope.nonce,
    envelope.data,
  }, '.')
end

--- Decrypts an encrypted response body.
---
--- The caller must verify the response signature over the raw envelope before
--- calling this function. `response` is the normalized Http response table.
function SecureChannel:open(response)
  if type(response) ~= 'table' then
    return nil, 'response is required'
  end
  if response.headers[SecureChannel.RESPONSE_HEADER] ~= '1' then
    return nil, 'response is not application-encrypted'
  end
  if response.bodyIsTable then
    return nil, 'encrypted response body was parsed before decryption'
  end

  local envelope, decodeError = Json.decode(response.body)
  if type(envelope) ~= 'table' then
    return nil, 'encrypted response envelope is not valid JSON: ' .. tostring(decodeError)
  end
  if envelope.v ~= VERSION then
    return nil, 'encrypted response version is unsupported'
  end
  local nonce = self.security.decodeBase64Url(envelope.nonce, NONCE_BYTES)
  if not nonce then
    return nil, 'encrypted response nonce is invalid'
  end
  local sealed = self.security.decodeBase64Url(envelope.data)
  if not sealed or #sealed < TAG_BYTES then
    return nil, 'encrypted response ciphertext is invalid'
  end
  local plaintext, openError = PureCrypto.chacha20Poly1305Decrypt(
    self.responseKey,
    nonce,
    sealed,
    RESPONSE_AAD
  )
  if not plaintext then
    return nil, openError
  end
  return plaintext
end

return SecureChannel
end

__wl_modules["http"] = function()
-- Transport layer for the whitelist Lua client.
--
-- The client never talks to arbitrary URLs. It only appends protocol paths to
-- the configured API base URL, and it normalizes the response shapes used by
-- common executor HTTP APIs into one predictable structure.

local Json = __wl_require('json')
local Config = __wl_require('config')
local Protection = __wl_require('protection')

local checkTransport = Protection.checkTransport

local Http = {}
Http.__index = Http

local ALLOWED_METHODS = {
  GET = true,
  POST = true,
  PUT = true,
  PATCH = true,
  DELETE = true,
}

local function isTable(value)
  return type(value) == 'table'
end

local function normalizeHeaderValue(value)
  if type(value) == 'table' then
    local parts = {}
    for _, item in ipairs(value) do
      parts[#parts + 1] = tostring(item)
    end
    if #parts > 0 then
      return table.concat(parts, ', ')
    end
    return tostring(value)
  end
  return tostring(value)
end

local function normalizeHeaders(headers)
  local normalized = {}
  if type(headers) ~= 'table' then
    return normalized
  end
  for key, value in pairs(headers) do
    if type(key) == 'string' then
      normalized[key:lower()] = normalizeHeaderValue(value)
    end
  end
  return normalized
end

local function getExecutorEnv()
  local env = _G
  if type(getgenv) == 'function' then
    local ok, generated = pcall(getgenv)
    if ok and isTable(generated) then
      env = generated
    end
  end
  return env
end

local function findExecutorAdapter(config)
  local env = getExecutorEnv()
  local candidates = {
    { fn = env.request, name = 'request', style = 'pascal' },
    { fn = env.http_request, name = 'http_request', style = 'pascal' },
    { fn = env.syn and env.syn.request, name = 'syn.request', style = 'pascal' },
    { fn = env.http and env.http.request, name = 'http.request', style = 'lower' },
    { fn = env.fluxus and env.fluxus.request, name = 'fluxus.request', style = 'pascal' },
    { fn = env.krnl and env.krnl.request, name = 'krnl.request', style = 'pascal' },
  }
  for _, candidate in ipairs(candidates) do
    if type(candidate.fn) == 'function' then
      local style = (config.http and config.http.requestStyle) or candidate.style
      return candidate.fn, candidate.name, style
    end
  end
  return nil
end

local function createExecutorAdapter(config)
  local fn, name, style = findExecutorAdapter(config)
  if not fn then
    return nil, 'No executor HTTP request function is available; configure http.adapter'
  end
  local adapter = function(request)
    local options
    if style == 'lower' then
      options = {
        url = request.url,
        method = request.method,
        headers = request.headers,
        body = request.body,
      }
    else
      options = {
        Url = request.url,
        Method = request.method,
        Headers = request.headers,
        Body = request.body,
      }
    end
    local ok, result = pcall(fn, options)
    if not ok then
      return nil, tostring(result)
    end
    return result
  end
  return adapter, nil, name, fn
end

function Http.new(config, protection)
  if type(config) ~= 'table' then
    return nil, 'config must be resolved before creating the HTTP client'
  end
  local adapter = nil
  local adapterName = 'custom'
  local rawAdapter = nil
  local isCustom = false
  if config.http and config.http.adapter ~= nil then
    isCustom = true
    local configured = config.http.adapter
    if type(configured) == 'function' then
      adapter = configured
      rawAdapter = configured
    elseif type(configured) == 'table' and type(configured.request) == 'function' then
      adapter = function(request)
        return configured.request(configured, request)
      end
      rawAdapter = configured.request
    else
      return nil, 'http.adapter must be a function or a table with a request method'
    end
  else
    local executorError
    adapter, executorError, adapterName, rawAdapter = createExecutorAdapter(config)
    if not adapter then
      return nil, executorError
    end
  end

  local self = setmetatable({
    config = config,
    adapter = adapter,
    adapterFn = rawAdapter or adapter,
    adapterName = adapterName,
    protection = protection,
  }, Http)

  if protection ~= nil then
    protection:snapshotTransport(self, adapter, adapterName, rawAdapter, isCustom)
    protection:sealValue(self, 'adapter', 'http.adapter')
    protection:sealValue(self, 'adapterFn', 'http.adapterFn')
    protection:sealMethod(self, 'request', 'http.request')
  end

  return self
end

function Http:buildUrl(path)
  if type(path) ~= 'string' or path == '' then
    return nil, 'Request path is required'
  end
  if path:find('^https?://') then
    return nil, 'Absolute request URLs are not allowed'
  end
  if path:sub(1, 1) ~= '/' then
    path = '/' .. path
  end
  if path:find('[%s]') then
    return nil, 'Request path must not contain whitespace'
  end
  return self.config.apiBaseUrl .. path
end

function Http:request(method, path, options)
  if self.protection ~= nil then
    local allowed, reason = checkTransport(self.protection)
    if not allowed then
      return nil, {
        code = 'TRANSPORT_TAMPERED',
        message = 'HTTP transport integrity check failed: ' .. tostring(reason),
      }
    end
  end

  options = options or {}
  if type(method) ~= 'string' then
    return nil, { code = 'NETWORK_ERROR', message = 'HTTP method is required' }
  end
  method = method:upper()
  if not ALLOWED_METHODS[method] then
    return nil, { code = 'NETWORK_ERROR', message = 'Unsupported HTTP method: ' .. method }
  end

  local url, urlError = self:buildUrl(path)
  if not url then
    return nil, { code = 'NETWORK_ERROR', message = urlError }
  end

  local body = options.body
  if isTable(body) then
    local encoded, encodeError = Json.encode(body)
    if not encoded then
      return nil, { code = 'ENCODING_ERROR', message = 'Unable to encode request body: ' .. tostring(encodeError) }
    end
    body = encoded
  elseif body ~= nil and type(body) ~= 'string' then
    return nil, { code = 'ENCODING_ERROR', message = 'Request body must be a table, string, or nil' }
  end

  local headers = {
    ['accept'] = 'application/json',
    ['accept-encoding'] = 'identity',
    ['user-agent'] = 'whitelist-lua/' .. Config.VERSION,
  }
  if body ~= nil then
    headers['content-type'] = 'application/json'
    headers['content-length'] = tostring(#body)
  end
  if options.authToken ~= nil then
    if type(options.authToken) ~= 'string' or #options.authToken < 20 then
      return nil, { code = 'INVALID_SESSION_TRANSITION', message = 'Access token is invalid' }
    end
    headers['authorization'] = 'Bearer ' .. options.authToken
  end
  if options.requestId ~= nil then
    headers['x-request-id'] = tostring(options.requestId)
  end
  if isTable(options.headers) then
    for key, value in pairs(options.headers) do
      if type(key) == 'string' then
        headers[key:lower()] = normalizeHeaderValue(value)
      end
    end
  end

  local request = {
    url = url,
    method = method,
    headers = headers,
    body = body,
    timeoutSeconds = options.timeoutSeconds or self.config.requestTimeoutSeconds,
    requestId = options.requestId,
  }

  local ok, result = pcall(self.adapter, request)
  if not ok then
    return nil, { code = 'NETWORK_ERROR', message = 'HTTP request failed: ' .. tostring(result) }
  end
  if result == nil then
    return nil, { code = 'NETWORK_ERROR', message = 'HTTP request returned no response' }
  end

  if type(result) == 'string' then
    result = { status = 200, headers = {}, body = result }
  end
  if not isTable(result) then
    return nil, { code = 'UNEXPECTED_RESPONSE_STRUCTURE', message = 'HTTP adapter returned an unexpected response' }
  end

  local status = result.status or result.StatusCode or result.statusCode or result.code or result.Code
  if type(status) == 'string' then
    status = tonumber(status)
  end
  if type(status) ~= 'number' or status % 1 ~= 0 or status < 100 or status > 599 then
    return nil, { code = 'UNEXPECTED_RESPONSE_STRUCTURE', message = 'HTTP response status is invalid' }
  end

  local headersValue = result.headers or result.Headers or {}
  local responseBody = result.body
  if responseBody == nil then
    responseBody = result.Body
  end
  local bodyIsTable = false
  if isTable(responseBody) then
    bodyIsTable = true
    local encoded = Json.encode(responseBody)
    responseBody = encoded or ''
  elseif responseBody == nil then
    responseBody = ''
  elseif type(responseBody) ~= 'string' then
    responseBody = tostring(responseBody)
  end

  if #responseBody > self.config.maxResponseBytes then
    return nil, { code = 'UNEXPECTED_RESPONSE_STRUCTURE', message = 'HTTP response exceeded the configured size limit' }
  end

  local responseUrl = result.url or result.Url
  if type(responseUrl) == 'string' and responseUrl ~= '' then
    local expectedOrigin = self.config.origin:lower()
    local actualOrigin = responseUrl:match('^(https?://[^/]+)')
    if not actualOrigin or actualOrigin:lower() ~= expectedOrigin then
      return nil, { code = 'NETWORK_ERROR', message = 'HTTP request was redirected to an untrusted origin' }
    end
  end

  return {
    status = status,
    headers = normalizeHeaders(headersValue),
    body = responseBody,
    bodyIsTable = bodyIsTable,
    url = responseUrl,
    adapter = self.adapterName,
  }
end

return Http
end

__wl_modules["session"] = function()
-- Opaque access/refresh token state and optional persistence hooks.
--
-- Refresh tokens are bearer secrets. By default this module keeps them in
-- memory only. A caller that configures sessionStore is responsible for using
-- a storage mechanism appropriate for its threat model.

local Session = {}
Session.__index = Session

local UUID_PATTERN = '^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$'

local function isUuid(value)
  return type(value) == 'string' and value:find(UUID_PATTERN) ~= nil
end

local function isToken(value)
  return type(value) == 'string' and #value >= 20 and #value <= 512
end

local function copyTable(value, seen)
  if type(value) ~= 'table' then
    return value
  end
  seen = seen or {}
  if seen[value] then
    return seen[value]
  end
  local copy = {}
  seen[value] = copy
  for key, item in pairs(value) do
    copy[copyTable(key, seen)] = copyTable(item, seen)
  end
  return copy
end

local function validateSnapshot(snapshot)
  if type(snapshot) ~= 'table' or snapshot.version ~= 1 then
    return nil, 'Session snapshot has an unsupported format'
  end
  if not isToken(snapshot.accessToken) then
    return nil, 'Session snapshot access token is invalid'
  end
  if not isToken(snapshot.refreshToken) then
    return nil, 'Session snapshot refresh token is invalid'
  end
  if not isUuid(snapshot.sessionId) then
    return nil, 'Session snapshot identifier is invalid'
  end
  if type(snapshot.accessExpiresAt) ~= 'number' or snapshot.accessExpiresAt <= 0 then
    return nil, 'Session snapshot access expiry is invalid'
  end
  if type(snapshot.refreshExpiresAt) ~= 'number' or snapshot.refreshExpiresAt <= 0 then
    return nil, 'Session snapshot refresh expiry is invalid'
  end
  if snapshot.license ~= nil and type(snapshot.license) ~= 'table' then
    return nil, 'Session snapshot license is invalid'
  end
  if snapshot.device ~= nil and type(snapshot.device) ~= 'table' then
    return nil, 'Session snapshot device is invalid'
  end
  if snapshot.keyId ~= nil and type(snapshot.keyId) ~= 'string' then
    return nil, 'Session snapshot key identifier is invalid'
  end
  return true
end

function Session.new(config)
  local self = setmetatable({
    config = config,
    store = config.sessionStore,
    accessToken = nil,
    refreshToken = nil,
    sessionId = nil,
    accessExpiresAt = nil,
    refreshExpiresAt = nil,
    license = nil,
    device = nil,
    keyId = nil,
    serverOffset = 0,
    loadError = nil,
  }, Session)
  if self.store ~= nil then
    local ok, snapshot = pcall(self.store.load)
    if not ok then
      self.loadError = 'Unable to load the session store: ' .. tostring(snapshot)
    elseif snapshot ~= nil then
      local valid, validationError = validateSnapshot(snapshot)
      if valid then
        self:_restore(snapshot)
      else
        self.loadError = validationError
        pcall(self.store.clear)
      end
    end
  end
  return self
end

function Session:_restore(snapshot)
  self.accessToken = snapshot.accessToken
  self.refreshToken = snapshot.refreshToken
  self.sessionId = snapshot.sessionId
  self.accessExpiresAt = snapshot.accessExpiresAt
  self.refreshExpiresAt = snapshot.refreshExpiresAt
  self.license = copyTable(snapshot.license)
  self.device = copyTable(snapshot.device)
  self.keyId = snapshot.keyId
  self.serverOffset = type(snapshot.serverOffset) == 'number' and snapshot.serverOffset or 0
end

function Session:snapshot()
  if self.accessToken == nil then
    return nil
  end
  return {
    version = 1,
    accessToken = self.accessToken,
    refreshToken = self.refreshToken,
    sessionId = self.sessionId,
    accessExpiresAt = self.accessExpiresAt,
    refreshExpiresAt = self.refreshExpiresAt,
    license = copyTable(self.license),
    device = copyTable(self.device),
    keyId = self.keyId,
    serverOffset = self.serverOffset,
  }
end

function Session:_save()
  if self.store == nil then
    return true
  end
  local snapshot = self:snapshot()
  if snapshot == nil then
    return self:_clearStore()
  end
  local ok, result = pcall(self.store.save, snapshot)
  if not ok then
    return nil, 'Unable to save the session store: ' .. tostring(result)
  end
  if result == false then
    return nil, 'Session store rejected the saved session'
  end
  return true
end

function Session:_clearStore()
  if self.store == nil then
    return true
  end
  local ok, result = pcall(self.store.clear)
  if not ok then
    return nil, 'Unable to clear the session store: ' .. tostring(result)
  end
  if result == false then
    return nil, 'Session store rejected the clear operation'
  end
  return true
end

function Session:setFromVerify(data, now)
  if type(data) ~= 'table' then
    return nil, 'Verification response is invalid'
  end
  if not isToken(data.accessToken) or not isToken(data.refreshToken) then
    return nil, 'Verification response tokens are invalid'
  end
  if not isUuid(data.sessionId) then
    return nil, 'Verification response session identifier is invalid'
  end
  if type(data.expiresIn) ~= 'number' or data.expiresIn <= 0 then
    return nil, 'Verification response access expiry is invalid'
  end
  if type(data.refreshExpiresIn) ~= 'number' or data.refreshExpiresIn <= 0 then
    return nil, 'Verification response refresh expiry is invalid'
  end

  self.accessToken = data.accessToken
  self.refreshToken = data.refreshToken
  self.sessionId = data.sessionId
  self.accessExpiresAt = now + data.expiresIn
  self.refreshExpiresAt = now + data.refreshExpiresIn
  self.license = copyTable(data.license)
  self.device = copyTable(data.device)
  self.keyId = data.keyId
  return self:_save()
end

function Session:setFromRefresh(data, now)
  if type(data) ~= 'table' then
    return nil, 'Refresh response is invalid'
  end
  if not isToken(data.accessToken) or not isToken(data.refreshToken) then
    return nil, 'Refresh response tokens are invalid'
  end
  if not isUuid(data.sessionId) then
    return nil, 'Refresh response session identifier is invalid'
  end
  if type(data.expiresIn) ~= 'number' or data.expiresIn <= 0 then
    return nil, 'Refresh response access expiry is invalid'
  end
  if type(data.refreshExpiresIn) ~= 'number' or data.refreshExpiresIn < 0 then
    return nil, 'Refresh response refresh expiry is invalid'
  end
  if self.sessionId ~= nil and data.sessionId ~= self.sessionId then
    return nil, 'Refresh response changed the session identifier'
  end

  self.accessToken = data.accessToken
  self.refreshToken = data.refreshToken
  self.sessionId = data.sessionId
  self.accessExpiresAt = now + data.expiresIn
  self.refreshExpiresAt = now + data.refreshExpiresIn
  if data.license ~= nil then
    self.license = copyTable(data.license)
  end
  if data.device ~= nil then
    self.device = copyTable(data.device)
  end
  if data.keyId ~= nil then
    self.keyId = data.keyId
  end
  return self:_save()
end

function Session:clear()
  self.accessToken = nil
  self.refreshToken = nil
  self.sessionId = nil
  self.accessExpiresAt = nil
  self.refreshExpiresAt = nil
  self.license = nil
  self.device = nil
  self.keyId = nil
  return self:_clearStore()
end

function Session:hasAccessToken()
  return self.accessToken ~= nil
end

function Session:hasRefreshToken()
  return self.refreshToken ~= nil
end

function Session:isAccessValid(now, leeway)
  if self.accessToken == nil or self.accessExpiresAt == nil then
    return false
  end
  return now < (self.accessExpiresAt - (leeway or 0))
end

function Session:isRefreshValid(now)
  if self.refreshToken == nil or self.refreshExpiresAt == nil then
    return false
  end
  return now < self.refreshExpiresAt
end

function Session:needsRefresh(now, leeway)
  if self.accessToken == nil or self.accessExpiresAt == nil then
    return true
  end
  return now >= (self.accessExpiresAt - (leeway or 0))
end

function Session:getAccessToken()
  return self.accessToken
end

function Session:getRefreshToken()
  return self.refreshToken
end

function Session:getSessionId()
  return self.sessionId
end

function Session:getLicense()
  return self.license
end

function Session:getDevice()
  return self.device
end

function Session:getKeyId()
  return self.keyId
end

function Session:getExpiry()
  return self.accessExpiresAt, self.refreshExpiresAt
end

function Session:isAuthenticated()
  return self.accessToken ~= nil and self.refreshToken ~= nil
end

return Session
end

__wl_modules["auth"] = function()
-- End-to-end authentication client for the whitelist platform.
--
-- The client never sends a public key during ordinary authentication. A
-- license key is used exactly once to register a signing key (or to add a key
-- through an already authenticated session); every subsequent login is an
-- Ed25519 challenge-response over an RFC 8785 canonical message.

local Config = __wl_require('config')
local Json = __wl_require('json')
local Canonical = __wl_require('canonical')
local Security = __wl_require('security')
local SecureChannel = __wl_require('secure_channel')
local Http = __wl_require('http')
local Session = __wl_require('session')
local Protection = __wl_require('protection')

local checkProtectionTransport = Protection.checkTransport
local checkProtectionIntegrity = Protection.checkIntegrity
local getProtectionStatus = Protection.getStatus

local Auth = {}
Auth.__index = Auth

local REQUEST_SIGNATURE_AUDIENCE = 'whitelist-request-v1'
local REQUEST_SIGNATURE_VERSION = 1
local REQUEST_SIGNATURE_NONCE_BYTES = 24
local PAYLOAD_SLUG_PATTERN = '^[a-z0-9][a-z0-9%-]*[a-z0-9]$'

local UUID_PATTERN = '^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$'

local CHALLENGE_KEYS = {
  audience = true,
  challenge_id = true,
  device_id = true,
  expires_at = true,
  issued_at = true,
  key_id = true,
  license_id = true,
  nonce = true,
  protocol_version = true,
}

local REGISTRATION_KEYS = {
  action = true,
  audience = true,
  expires_at = true,
  issued_at = true,
  key_id = true,
  license_id = true,
  nonce = true,
  protocol_version = true,
  registration_id = true,
}

local TERMINAL_CODES = {
  SESSION_REVOKED = true,
  SESSION_NOT_FOUND = true,
  REFRESH_TOKEN_REUSE = true,
  LICENSE_SUSPENDED = true,
  LICENSE_REVOKED = true,
  LICENSE_EXPIRED = true,
  LICENSE_NOT_ACTIVATED = true,
  DEVICE_REVOKED = true,
  DEVICE_NOT_FOUND = true,
  KEY_REVOKED = true,
  UNAUTHORIZED = true,
}

local RETRYABLE_CHALLENGE_CODES = {
  CHALLENGE_ALREADY_USED = true,
  CHALLENGE_NOT_FOUND = true,
  CHALLENGE_EXPIRED = true,
  CHALLENGE_CONSUMED = true,
}

local function isTable(value)
  return type(value) == 'table'
end

local function isUuid(value)
  return type(value) == 'string' and value:find(UUID_PATTERN) ~= nil
end

local function isBase64Url(value)
  return type(value) == 'string' and #value > 0 and value:find('^[A-Za-z0-9_-]+$') ~= nil
end

local function isInteger(value)
  return type(value) == 'number' and value % 1 == 0
end

local function isValidPayloadSlug(value)
  return type(value) == 'string'
    and #value >= 1
    and #value <= 80
    and value:find('^[a-z0-9][a-z0-9%-]*$') ~= nil
    and value:sub(-1) ~= '-'
end

local function newError(code, message, extra)
  local err = {
    code = code,
    message = message,
  }
  if isTable(extra) then
    for key, value in pairs(extra) do
      if err[key] == nil then
        err[key] = value
      end
    end
  end
  return err
end

local function raiseError(code, message, extra)
  error(newError(code, message, extra), 0)
end

local function wrapError(value)
  if isTable(value) and type(value.code) == 'string' then
    return value
  end
  return newError('INTERNAL_ERROR', tostring(value))
end

-- Module-local guards. Auth methods call these instead of the public
-- self:_guardAll/self:_guardProtection helpers so replacing an instance method
-- with a no-op cannot bypass the transport or integrity check.
local function enforceProtection(instance, kind, context)
  local protection = instance._protection
  if protection == nil then
    return
  end
  local allowed, reason
  if kind == 'transport' then
    allowed, reason = checkProtectionTransport(protection)
  else
    allowed, reason = checkProtectionIntegrity(protection)
  end
  local code = kind == 'transport' and 'TRANSPORT_TAMPERED' or 'INTEGRITY_VIOLATION'
  if reason ~= nil then
    instance:_recordTelemetry(
      code,
      'CRITICAL',
      'Client protection check failed during ' .. tostring(context),
      { reason = reason }
    )
  end
  if allowed ~= true then
    raiseError(code, 'Client protection check failed: ' .. tostring(reason))
  end
end

local function enforceAllProtection(instance, context)
  enforceProtection(instance, 'transport', context)
  enforceProtection(instance, 'integrity', context)
end

local function assertExactKeys(value, allowed, label)
  if type(value) ~= 'table' then
    raiseError('PROTOCOL_MISMATCH', label .. ' must be an object')
  end
  for key in pairs(value) do
    if not allowed[key] then
      raiseError('PROTOCOL_MISMATCH', label .. ' contains an unexpected field: ' .. tostring(key))
    end
  end
  for key in pairs(allowed) do
    if value[key] == nil then
      raiseError('PROTOCOL_MISMATCH', label .. ' is missing field: ' .. tostring(key))
    end
  end
end

local function assertString(value, label, minLength, maxLength)
  if type(value) ~= 'string' or #value < minLength or #value > maxLength then
    raiseError('PROTOCOL_MISMATCH', label .. ' is invalid')
  end
end

local function assertInteger(value, label)
  if not isInteger(value) then
    raiseError('PROTOCOL_MISMATCH', label .. ' must be an integer')
  end
end

local function detectExecutorName()
  local names = { 'identifyexecutor', 'getexecutorname' }
  for _, name in ipairs(names) do
    local fn = _G[name]
    if type(fn) ~= 'function' and type(getgenv) == 'function' then
      local ok, env = pcall(getgenv)
      if ok and isTable(env) then
        fn = env[name]
      end
    end
    if type(fn) == 'function' then
      local ok, value = pcall(fn)
      if ok and type(value) == 'string' and #value > 0 then
        return value
      end
    end
  end
  return nil
end

local function sanitizeMetadata(value, fallback, maxLength)
  if type(value) ~= 'string' then
    return fallback
  end
  value = value:gsub('[%z\1-\31\127]', ' ')
  value = value:gsub('^%s+', ''):gsub('%s+$', '')
  if value == '' then
    return fallback
  end
  if #value > maxLength then
    value = value:sub(1, maxLength)
  end
  return value
end

function Auth.new(options)
  local config, configError = Config.resolve(options)
  if not config then
    return nil, newError('INVALID_CONFIG', configError)
  end

  if config.executor == nil then
    config.executor = detectExecutorName() or 'unknown'
  end
  if config.platform == nil then
    config.platform = 'Roblox'
  end
  config.executor = sanitizeMetadata(config.executor, 'unknown', 120)
  config.platform = sanitizeMetadata(config.platform, 'Roblox', 80)
  config.deviceName = sanitizeMetadata(
    config.deviceName,
    config.executor .. ' device',
    120
  )

  local protection = Protection.new(config)

  local security, securityError = Security.new(config)
  if not security then
    return nil, newError('CRYPTO_UNAVAILABLE', securityError)
  end
  local http, httpError = Http.new(config, protection)
  if not http then
    return nil, newError('HTTP_UNAVAILABLE', httpError)
  end

  local session = Session.new(config)
  local self = setmetatable({
    config = config,
    security = security,
    http = http,
    session = session,
    _protection = protection,
    _loader = nil,
    _loaderName = nil,
    deviceId = nil,
    keyring = nil,
    key = nil,
    license = nil,
    serverKey = nil,
    secureChannel = nil,
    secureChannelKeyId = nil,
    pinnedServerKey = config.serverPublicKey ~= nil,
    clockOffset = 0,
    state = session:isAuthenticated() and 'authenticated' or 'idle',
    lastError = nil,
    lastWarning = nil,
    telemetryQueue = {},
    telemetryDropped = 0,
    flushingTelemetry = false,
    authFailureCount = 0,
    authFailureWindow = nil,
    seenNonces = {},
    nonceOrder = {},
    seenChallenges = {},
    challengeOrder = {},
  }, Auth)

  if config.serverPublicKey ~= nil then
    self.serverKey = {
      publicKey = config.serverPublicKey,
      keyId = config.serverKeyId,
      encryptionPublicKey = config.serverEncryptionPublicKey,
      encryptionKeyId = config.serverEncryptionKeyId,
    }
  end

  -- When both the signing and encryption keys are pinned, the client can build
  -- the secure channel without contacting /meta/keys. Pinning is an out-of-band
  -- trust decision, so the self-signature check is unnecessary here.
  if self.serverKey ~= nil
    and self.serverKey.keyId ~= nil
    and self.serverKey.encryptionPublicKey ~= nil
    and self.serverKey.encryptionKeyId ~= nil
  then
    local channel, channelError = SecureChannel.new({
      security = security,
      serverPublicKey = self.serverKey.encryptionPublicKey,
    })
    if not channel then
      return nil, newError('CRYPTO_UNAVAILABLE', channelError)
    end
    self.secureChannel = channel
    self.secureChannelKeyId = self.serverKey.encryptionKeyId
  end

  local deviceId, deviceError = security:getOrCreateDeviceId()
  if not deviceId then
    return nil, newError('STORAGE_UNAVAILABLE', deviceError)
  end
  self.deviceId = deviceId

  local keyring, keyringError = security:loadKeyring()
  if not keyring then
    return nil, newError('KEYRING_CORRUPT', keyringError)
  end
  self.keyring = keyring
  self:_selectCurrentKey()

  if session:getLicense() ~= nil then
    self.license = session:getLicense()
  end
  if session.loadError ~= nil then
    self:_recordTelemetry(
      'UNEXPECTED_RESPONSE_STRUCTURE',
      'LOW',
      'Stored session state was discarded',
      { reason = session.loadError }
    )
  end

  self:_protectState()
  protection:sealValue(self, 'config', 'client.config')
  protection:sealValue(self, 'security', 'client.security')
  protection:sealValue(self, 'http', 'client.http')
  protection:sealValue(self, 'session', 'client.session')
  protection:sealValue(self, '_protection', 'client._protection')

  for _, method in ipairs({
    '_send',
    '_publicRequest',
    '_authRequest',
    '_verify',
    '_activate',
    '_challenge',
    '_refresh',
    '_ensureServerKey',
    '_fetchServerKey',
    '_guardProtection',
    '_guardAll',
    '_protectState',
    '_sealSecureChannel',
    'authenticate',
    'refresh',
    'logout',
    'getStatus',
    'getSession',
    'getSecurityStatus',
    'listKeys',
    'listPayloads',
    'fetchPayload',
    'runPayload',
    'registerKey',
    'rotateKey',
    'revokeKey',
    'deactivate',
    'sendTelemetry',
    'getAccessToken',
    'getProtectionStatus',
    'checkProtection',
  }) do
    protection:sealMethod(self, method, 'client.' .. method)
  end

  for _, method in ipairs({
    'sign',
    'verify',
    'generateKeyPair',
    'verifyResponseSignature',
    'sha256Hex',
    'sha256Base64Url',
    'randomHex',
    'randomBytes',
    'newRequestId',
    'sanitizeTelemetryEvent',
    'publicKeyId',
    'loadKeyring',
    'saveKeyring',
  }) do
    protection:sealMethod(security, method, 'security.' .. method)
  end

  for _, method in ipairs({
    'getAccessToken',
    'getRefreshToken',
    'isAccessValid',
    'save',
    'clear',
    'getSessionId',
    'getLicense',
  }) do
    protection:sealMethod(session, method, 'session.' .. method)
  end

  protection:sealMethod(http, 'buildUrl', 'http.buildUrl')

  local loader, loaderName = protection:captureLoader()
  self._loader = loader
  self._loaderName = loaderName
  if loader ~= nil then
    protection:sealValue(self, '_loader', 'client._loader')
  end

  local allowed, reason = checkProtectionTransport(protection)
  if not allowed then
    return nil, newError('TRANSPORT_TAMPERED', reason)
  end
  allowed, reason = checkProtectionIntegrity(protection)
  if not allowed then
    return nil, newError('INTEGRITY_VIOLATION', reason)
  end

  return self
end

function Auth:_now()
  return os.time() + (self.clockOffset or 0)
end

function Auth:_selectCurrentKey()
  if self.keyring == nil then
    return nil
  end
  local current = self.security:currentKey(self.keyring)
  if current ~= nil and current.status ~= 'REVOKED' then
    self.key = current
    return current
  end
  for _, record in ipairs(self.keyring.keys) do
    if record.status ~= 'REVOKED' then
      self.keyring.current = record.localId
      self.key = record
      return record
    end
  end
  self.key = current
  return current
end

--- Registers newly created state tables for getgc() filtering and seals the
--- secure channel when it is rebuilt.
function Auth:_protectState()
  if self._protection == nil then
    return
  end
  self._protection:attachClient(self)
  if self.keyring ~= nil then
    self._protection.protectTable(self.keyring, 'client.keyring', 2)
  end
  if self.key ~= nil then
    self._protection.protectTable(self.key, 'client.key', 1)
  end
  self:_sealSecureChannel()
end

function Auth:_sealSecureChannel()
  if self._protection == nil or self.secureChannel == nil then
    return
  end
  self._protection.protectTable(self.secureChannel, 'client.secureChannel', 1)
  self._protection:sealMethod(self.secureChannel, 'seal', 'secureChannel.seal')
  self._protection:sealMethod(self.secureChannel, 'open', 'secureChannel.open')
  self._protection:sealMethod(self.secureChannel, 'signatureNonce', 'secureChannel.signatureNonce')
end

--- Runs an anti-HTTP-spy or anti-dump check. When failClosed is disabled the
--- violation is recorded and reported but the request continues.
function Auth:_guardProtection(kind, context)
  enforceProtection(self, kind, context)
end

function Auth:_guardAll(context)
  enforceAllProtection(self, context)
end

--- Returns a copy of the current client-protection status. Safe to call after
--- a violation so callers can inspect why the client stopped.
function Auth:getProtectionStatus()
  if self._protection == nil then
    return {
      enabled = false,
      violationCount = 0,
      lastViolation = nil,
    }
  end
  return getProtectionStatus(self._protection)
end

--- Performs an explicit transport and integrity check without sending a
--- request.
function Auth:checkProtection()
  local allowed, reason = checkProtectionTransport(self._protection)
  if allowed == true then
    allowed, reason = checkProtectionIntegrity(self._protection)
  end
  return allowed == true, reason
end

function Auth:_setClockFromHeaders(response)
  if type(response) ~= 'table' or type(response.headers) ~= 'table' then
    return
  end
  local timestamp = tonumber(response.headers['x-response-timestamp'])
  if timestamp and timestamp > 0 then
    local offset = timestamp - os.time()
    if math.abs(offset) <= 86400 then
      self.clockOffset = offset
    end
  end
end

function Auth:_setServerTime(serverTime)
  if type(serverTime) ~= 'string' then
    return
  end
  local epoch = self.security:parseIso8601Utc(serverTime)
  if not epoch then
    return
  end
  local offset = epoch - os.time()
  if math.abs(offset) <= 86400 then
    self.clockOffset = offset
  else
    self:_recordTelemetry(
      'PROTOCOL_SEQUENCE_VIOLATION',
      'MEDIUM',
      'Server time is outside the allowed clock skew',
      { serverTime = serverTime, offsetSeconds = offset }
    )
  end
end

function Auth:_recordTelemetry(eventType, severity, message, details, requestId)
  if not self.config.telemetry.enabled then
    return
  end
  local event, err = self.security:sanitizeTelemetryEvent({
    type = eventType,
    severity = severity,
    message = message,
    details = details,
    requestId = requestId,
    occurredAt = self.security:formatIso8601Utc(os.time()),
  }, self.config.telemetry)
  if not event then
    self.security:log('warn', 'Telemetry event rejected: ' .. tostring(err))
    return
  end
  self.telemetryQueue[#self.telemetryQueue + 1] = event
  local maxQueue = self.config.telemetry.maxQueue
  while #self.telemetryQueue > maxQueue do
    table.remove(self.telemetryQueue, 1)
    self.telemetryDropped = self.telemetryDropped + 1
  end
end

function Auth:_flushTelemetry()
  if not self.config.telemetry.enabled or #self.telemetryQueue == 0 or self.flushingTelemetry then
    return true
  end
  self.flushingTelemetry = true
  local ok, err = pcall(function()
    self:_ensureServerKey()
  end)
  if not ok then
    self.flushingTelemetry = false
    return nil, wrapError(err)
  end

  local batches = 0
  while #self.telemetryQueue > 0 and batches < 3 do
    batches = batches + 1
    local batch = {}
    local count = math.min(20, #self.telemetryQueue)
    for _ = 1, count do
      batch[#batch + 1] = table.remove(self.telemetryQueue, 1)
    end
    local token = nil
    if self.session:isAccessValid(self:_now(), 0) then
      token = self.session:getAccessToken()
    end
    local sent = pcall(function()
      self:_send('POST', '/security/telemetry', { events = batch }, {
        authToken = token,
        requestPrefix = 'telemetry',
      })
    end)
    if not sent then
      -- Telemetry is best-effort. Dropping the batch avoids an unbounded retry
      -- loop and avoids turning a telemetry failure into an auth failure.
      self.security:log('warn', 'Telemetry batch was not accepted')
    end
  end
  self.flushingTelemetry = false
  return true
end

function Auth:_recordAuthFailure(code)
  local now = os.time()
  if self.authFailureWindow == nil or now - self.authFailureWindow > 60 then
    self.authFailureWindow = now
    self.authFailureCount = 0
  end
  self.authFailureCount = self.authFailureCount + 1
  if self.authFailureCount >= 3 then
    self:_recordTelemetry(
      'SUSPICIOUS_AUTH_PATTERN',
      'MEDIUM',
      'Repeated authentication failures observed',
      { count = self.authFailureCount, lastCode = code }
    )
  end
end

function Auth:_resetAuthFailures()
  self.authFailureCount = 0
  self.authFailureWindow = nil
end

function Auth:_rememberNonce(nonce, challengeId)
  if self.seenNonces[nonce] ~= nil then
    self:_recordTelemetry(
      'NONCE_REUSE',
      'HIGH',
      'Server issued a previously used challenge nonce',
      { challengeId = challengeId, previousChallengeId = self.seenNonces[nonce] }
    )
    raiseError('PROTOCOL_MISMATCH', 'Challenge nonce was reused')
  end
  self.seenNonces[nonce] = challengeId
  self.nonceOrder[#self.nonceOrder + 1] = nonce
  if #self.nonceOrder > 128 then
    local oldest = table.remove(self.nonceOrder, 1)
    self.seenNonces[oldest] = nil
  end
end

function Auth:_rememberChallenge(challengeId)
  if self.seenChallenges[challengeId] then
    self:_recordTelemetry(
      'PROTOCOL_SEQUENCE_VIOLATION',
      'HIGH',
      'Server issued a previously used challenge identifier',
      { challengeId = challengeId }
    )
    raiseError('PROTOCOL_MISMATCH', 'Challenge identifier was reused')
  end
  self.seenChallenges[challengeId] = true
  self.challengeOrder[#self.challengeOrder + 1] = challengeId
  if #self.challengeOrder > 128 then
    local oldest = table.remove(self.challengeOrder, 1)
    self.seenChallenges[oldest] = nil
  end
end

function Auth:_ensureServerKey()
  if self.serverKey ~= nil
    and self.serverKey.publicKey ~= nil
    and self.serverKey.keyId ~= nil
    and self.serverKey.encryptionPublicKey ~= nil
    and self.serverKey.encryptionKeyId ~= nil
    and self.secureChannel ~= nil
  then
    return self.serverKey
  end
  self:_fetchServerKey()
  return self.serverKey
end

function Auth:_fetchServerKey()
  local requestId, requestIdError = self.security:newRequestId('meta')
  if not requestId then
    raiseError('REPEATED_REQUEST_ID', requestIdError)
  end
  local response, requestError = self.http:request('GET', '/meta/keys', {
    requestId = requestId,
  })
  if not response then
    raiseError(requestError and requestError.code or 'NETWORK_ERROR', requestError and requestError.message or 'Unable to fetch the server key')
  end
  if response.status ~= 200 then
    raiseError('SERVER_KEY_UNAVAILABLE', 'Server key endpoint returned HTTP ' .. tostring(response.status))
  end
  if response.bodyIsTable then
    self:_recordTelemetry(
      'UNEXPECTED_RESPONSE_STRUCTURE',
      'HIGH',
      'Server key response body was not raw text',
      nil,
      requestId
    )
    raiseError('INVALID_RESPONSE_SIGNATURE', 'Server key response cannot be verified')
  end
  local contentType = response.headers['content-type'] or ''
  if not contentType:lower():find('^application/json') then
    self:_recordTelemetry(
      'UNEXPECTED_CONTENT_TYPE',
      'HIGH',
      'Server key response used an unexpected content type',
      { contentType = contentType },
      requestId
    )
    raiseError('UNEXPECTED_CONTENT_TYPE', 'Server key response is not JSON')
  end
  local parsed, decodeError = Json.decode(response.body)
  if not parsed or type(parsed) ~= 'table' or parsed.success ~= true or type(parsed.data) ~= 'table' then
    self:_recordTelemetry(
      'UNEXPECTED_RESPONSE_STRUCTURE',
      'HIGH',
      'Server key response did not match the expected envelope',
      { decodeError = decodeError },
      requestId
    )
    raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Server key response is malformed')
  end
  local data = parsed.data
  if data.algorithm ~= 'Ed25519' then
    raiseError('PROTOCOL_MISMATCH', 'Server key algorithm is not Ed25519')
  end
  if not isBase64Url(data.keyId) or #data.keyId < 40 or #data.keyId > 64 then
    raiseError('PROTOCOL_MISMATCH', 'Server key identifier is invalid')
  end
  local publicRaw = self.security.decodeBase64Url(data.publicKey, 32)
  if not publicRaw then
    raiseError('PROTOCOL_MISMATCH', 'Server public key is invalid')
  end
  if data.protocolVersion ~= self.config.protocolVersion then
    raiseError('PROTOCOL_MISMATCH', 'Server protocol version does not match the client')
  end
  if data.audience ~= self.config.audience then
    raiseError('PROTOCOL_MISMATCH', 'Server audience does not match the client')
  end
  if data.encryptionAlgorithm ~= 'X25519' then
    raiseError('PROTOCOL_MISMATCH', 'Server encryption algorithm is not X25519')
  end
  local encryptionRaw = self.security.decodeBase64Url(data.encryptionPublicKey, 32)
  if not encryptionRaw then
    raiseError('PROTOCOL_MISMATCH', 'Server encryption public key is invalid')
  end
  if not isBase64Url(data.encryptionKeyId) or #data.encryptionKeyId < 40 or #data.encryptionKeyId > 64 then
    raiseError('PROTOCOL_MISMATCH', 'Server encryption key identifier is invalid')
  end
  local computedEncryptionKeyId = self.security:publicKeyId(data.encryptionPublicKey)
  if computedEncryptionKeyId ~= nil and computedEncryptionKeyId ~= data.encryptionKeyId then
    raiseError('PROTOCOL_MISMATCH', 'Server encryption key identifier does not match its key')
  end
  if self.config.serverEncryptionPublicKey ~= nil then
    if data.encryptionPublicKey ~= self.config.serverEncryptionPublicKey then
      self:_recordTelemetry(
        'INVALID_RESPONSE_SIGNATURE',
        'CRITICAL',
        'Server encryption key does not match the pinned key',
        { presentedKeyId = data.encryptionKeyId },
        requestId
      )
      raiseError('SERVER_KEY_MISMATCH', 'Server encryption key does not match the pinned key')
    end
    if self.config.serverEncryptionKeyId ~= nil and data.encryptionKeyId ~= self.config.serverEncryptionKeyId then
      self:_recordTelemetry(
        'INVALID_RESPONSE_SIGNATURE',
        'CRITICAL',
        'Server encryption key identifier does not match the pinned key',
        { presentedKeyId = data.encryptionKeyId },
        requestId
      )
      raiseError('SERVER_KEY_MISMATCH', 'Server encryption key identifier does not match the pinned key')
    end
  end

  local trusted
  if self.pinnedServerKey then
    if data.publicKey ~= self.config.serverPublicKey then
      self:_recordTelemetry(
        'INVALID_RESPONSE_SIGNATURE',
        'CRITICAL',
        'Server public key does not match the pinned key',
        { presentedKeyId = data.keyId },
        requestId
      )
      raiseError('SERVER_KEY_MISMATCH', 'Server public key does not match the pinned key')
    end
    if self.config.serverKeyId ~= nil and data.keyId ~= self.config.serverKeyId then
      self:_recordTelemetry(
        'INVALID_RESPONSE_SIGNATURE',
        'CRITICAL',
        'Server key identifier does not match the pinned key',
        { presentedKeyId = data.keyId },
        requestId
      )
      raiseError('SERVER_KEY_MISMATCH', 'Server key identifier does not match the pinned key')
    end
    trusted = {
      publicKey = self.config.serverPublicKey,
      keyId = data.keyId,
    }
  else
    trusted = {
      publicKey = data.publicKey,
      keyId = data.keyId,
    }
  end

  local verified, verifyError = self.security:verifyResponseSignature(response, trusted, self:_now())
  if not verified then
    self:_recordTelemetry(
      'INVALID_RESPONSE_SIGNATURE',
      'CRITICAL',
      'Server key response signature verification failed',
      { reason = verifyError },
      requestId
    )
    raiseError('INVALID_RESPONSE_SIGNATURE', 'Server key response signature is invalid')
  end

  self.serverKey = {
    publicKey = data.publicKey,
    keyId = data.keyId,
    encryptionPublicKey = data.encryptionPublicKey,
    encryptionKeyId = data.encryptionKeyId,
  }
  if self.secureChannel == nil or self.secureChannelKeyId ~= data.encryptionKeyId then
    local channel, channelError = SecureChannel.new({
      security = self.security,
      serverPublicKey = data.encryptionPublicKey,
    })
    if not channel then
      raiseError('CRYPTO_UNAVAILABLE', 'Unable to initialize application encryption: ' .. tostring(channelError))
    end
    self.secureChannel = channel
    self.secureChannelKeyId = data.encryptionKeyId
  end
  self:_protectState()
  self:_setClockFromHeaders(response)
  return self.serverKey
end

--- Returns the full wire path (API prefix + route) used by the request proof.
function Auth:_fullPath(path)
  if type(path) ~= 'string' or path == '' then
    raiseError('PROTOCOL_MISMATCH', 'Request path is required')
  end
  if path:sub(1, 1) ~= '/' then
    path = '/' .. path
  end
  local prefix = self.config.apiPrefix
  if path == prefix or path:sub(1, #prefix + 1) == prefix .. '/' then
    return path
  end
  return prefix .. path
end

function Auth:_send(method, path, body, options)
  enforceAllProtection(self, 'request')
  options = options or {}
  self:_ensureServerKey()
  if self.secureChannel == nil then
    raiseError('CRYPTO_UNAVAILABLE', 'Application encryption is not initialized')
  end
  -- Pin the channel used for this request. A response-signing-key refresh may
  -- rebuild the channel mid-flight; the response is still sealed with the key
  -- that encrypted the request.
  local channel = self.secureChannel

  local requestId = options.requestId
  if requestId == nil then
    local generated, requestIdError = self.security:newRequestId(options.requestPrefix or 'req')
    if not generated then
      raiseError('REPEATED_REQUEST_ID', requestIdError)
    end
    requestId = generated
  end

  method = method:upper()
  local bodyString = ''
  if body ~= nil then
    if type(body) == 'table' then
      local encoded, encodeError = Json.encode(body)
      if not encoded then
        raiseError('ENCODING_ERROR', 'Unable to encode request body: ' .. tostring(encodeError))
      end
      bodyString = encoded
    elseif type(body) == 'string' then
      bodyString = body
    else
      raiseError('ENCODING_ERROR', 'Request body must be a table, string, or nil')
    end
  end

  local fullPath = self:_fullPath(path)
  local timestamp = self:_now()
  local nonce, nonceError = channel:signatureNonce()
  if not nonce then
    raiseError('CRYPTO_UNAVAILABLE', nonceError)
  end
  local bodySha, hashError = self.security:sha256Base64Url(bodyString)
  if not bodySha then
    raiseError('CRYPTO_UNAVAILABLE', hashError)
  end

  local keyId = nil
  local signature = nil
  if options.authToken ~= nil then
    if self.key == nil or self.key.keyId == nil or self.key.secretKey == nil then
      raiseError('KEY_NOT_FOUND', 'No signing key is available for the request proof')
    end
    keyId = self.key.keyId
    local canonical, canonicalError = Canonical.encode({
      audience = REQUEST_SIGNATURE_AUDIENCE,
      body_sha256 = bodySha,
      key_id = keyId,
      method = method,
      nonce = nonce,
      path = fullPath,
      timestamp = timestamp,
    })
    if not canonical then
      raiseError('PROTOCOL_MISMATCH', 'Unable to canonicalize the request proof: ' .. tostring(canonicalError))
    end
    signature, signatureError = self.security:sign(canonical, self.key.secretKey, self.key.publicKey)
    if not signature then
      raiseError('INVALID_SIGNATURE', 'Unable to sign the request proof: ' .. tostring(signatureError))
    end
  end

  local envelope, sealError = channel:seal({
    version = REQUEST_SIGNATURE_VERSION,
    access_token = options.authToken,
    body = bodyString,
    body_sha256 = bodySha,
    key_id = keyId,
    method = method,
    nonce = nonce,
    path = fullPath,
    signature = signature,
    timestamp = timestamp,
  })
  if not envelope then
    raiseError('INVALID_ENCRYPTION', 'Unable to encrypt the request: ' .. tostring(sealError))
  end

  local httpOptions = {
    requestId = requestId,
    timeoutSeconds = options.timeoutSeconds,
    headers = {},
  }
  if bodyString ~= '' then
    httpOptions.body = envelope
    httpOptions.headers['content-type'] = SecureChannel.ENCRYPTED_CONTENT_TYPE
  else
    local headerValue, headerError = SecureChannel.headerValue(envelope)
    if not headerValue then
      raiseError('INVALID_ENCRYPTION', headerError)
    end
    httpOptions.headers[SecureChannel.REQUEST_HEADER] = headerValue
  end

  local response, requestError = self.http:request(method, path, httpOptions)
  if not response then
    raiseError(
      requestError and requestError.code or 'NETWORK_ERROR',
      requestError and requestError.message or 'HTTP request failed'
    )
  end

  local success = response.status >= 200 and response.status < 300
  local hasSignature = response.headers['x-response-timestamp'] ~= nil
    and response.headers['x-response-key-id'] ~= nil
    and response.headers['x-response-signature'] ~= nil

  if success and not hasSignature then
    self:_recordTelemetry(
      'INVALID_RESPONSE_SIGNATURE',
      'CRITICAL',
      'Successful response did not include a signature',
      { path = path, status = response.status },
      requestId
    )
    raiseError('INVALID_RESPONSE_SIGNATURE', 'Response signature is missing')
  end
  if not hasSignature then
    -- Error responses are signed by every license-facing route. A missing
    -- signature means the response did not come from the expected server (or
    -- an intermediary stripped it), so fail closed instead of trusting the
    -- error code.
    self:_recordTelemetry(
      'INVALID_RESPONSE_SIGNATURE',
      'HIGH',
      'Error response did not include a signature',
      { path = path, status = response.status },
      requestId
    )
    raiseError('INVALID_RESPONSE_SIGNATURE', 'Error response signature is missing')
  end

  if response.bodyIsTable then
    self:_recordTelemetry(
      'UNEXPECTED_RESPONSE_STRUCTURE',
      'HIGH',
      'Response body was parsed by the executor before signature verification',
      { path = path, status = response.status },
      requestId
    )
    raiseError('INVALID_RESPONSE_SIGNATURE', 'Response body cannot be verified')
  end
  local verified, verifyError = self.security:verifyResponseSignature(response, self.serverKey, self:_now())
  if not verified and not self.pinnedServerKey and not options.serverKeyRefreshed then
    -- The server may have rotated its response-signing key. Fetch the new
    -- key from the signed meta endpoint and verify the already-received
    -- response again without replaying the original request.
    local refreshed = pcall(function()
      self:_fetchServerKey()
    end)
    if refreshed then
      verified, verifyError = self.security:verifyResponseSignature(response, self.serverKey, self:_now())
      options.serverKeyRefreshed = true
    end
  end
  if not verified then
    self:_recordTelemetry(
      'INVALID_RESPONSE_SIGNATURE',
      'CRITICAL',
      'Response signature verification failed',
      { path = path, status = response.status, reason = verifyError },
      requestId
    )
    raiseError('INVALID_RESPONSE_SIGNATURE', 'Response signature is invalid')
  end
  self:_setClockFromHeaders(response)

  local contentType = response.headers['content-type'] or ''
  local lowerContentType = contentType:lower()
  local isJson = lowerContentType:find('^application/json') ~= nil
    or lowerContentType:find('^application/[%w.+-]+%+json') ~= nil
  if success and not isJson then
    self:_recordTelemetry(
      'UNEXPECTED_CONTENT_TYPE',
      'HIGH',
      'Response used an unexpected content type',
      { path = path, contentType = contentType },
      requestId
    )
    raiseError('UNEXPECTED_CONTENT_TYPE', 'Response is not JSON')
  end

  if response.headers[SecureChannel.RESPONSE_HEADER] == '1' then
    enforceProtection(self, 'integrity', 'decrypt')
    local plaintext, decryptError = channel:open(response)
    if not plaintext then
      self:_recordTelemetry(
        'INVALID_RESPONSE_SIGNATURE',
        'CRITICAL',
        'Application-encrypted response could not be decrypted',
        { path = path, status = response.status, reason = decryptError },
        requestId
      )
      raiseError('INVALID_ENCRYPTION', 'Response decryption failed')
    end
    response.body = plaintext
    response.bodyIsTable = false
  elseif success then
    self:_recordTelemetry(
      'UNEXPECTED_RESPONSE_STRUCTURE',
      'HIGH',
      'Successful response was not application-encrypted',
      { path = path, status = response.status },
      requestId
    )
    raiseError('INVALID_ENCRYPTION', 'Response was not application-encrypted')
  end

  local parsed, decodeError = Json.decode(response.body)
  if not parsed or type(parsed) ~= 'table' then
    self:_recordTelemetry(
      'UNEXPECTED_RESPONSE_STRUCTURE',
      'HIGH',
      'Response body is not a valid JSON object',
      { path = path, decodeError = decodeError },
      requestId
    )
    raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Response body is malformed')
  end

  if parsed.success == true then
    if not success then
      self:_recordTelemetry(
        'UNEXPECTED_RESPONSE_STRUCTURE',
        'HIGH',
        'Error status carried a success envelope',
        { path = path, status = response.status },
        requestId
      )
      raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Response envelope is inconsistent')
    end
    if type(parsed.data) ~= 'table' then
      self:_recordTelemetry(
        'UNEXPECTED_RESPONSE_STRUCTURE',
        'HIGH',
        'Success envelope is missing its data object',
        { path = path },
        requestId
      )
      raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Response data is missing')
    end
    return parsed.data, parsed.meta, parsed, response
  elseif parsed.success == false then
    local errorObject = parsed.error
    if type(errorObject) ~= 'table' or type(errorObject.code) ~= 'string' then
      self:_recordTelemetry(
        'UNEXPECTED_RESPONSE_STRUCTURE',
        'HIGH',
        'Error envelope is malformed',
        { path = path, status = response.status },
        requestId
      )
      raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Error response is malformed')
    end
    error(newError(errorObject.code, errorObject.message or errorObject.code, {
      status = response.status,
      details = errorObject.details,
      requestId = parsed.requestId,
      retryAfter = tonumber(response.headers['retry-after']),
    }), 0)
  end

  self:_recordTelemetry(
    'UNEXPECTED_RESPONSE_STRUCTURE',
    'HIGH',
    'Response envelope is missing the success flag',
    { path = path, status = response.status },
    requestId
  )
  raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Response envelope is malformed')
end

function Auth:_publicRequest(method, path, body, options)
  options = options or {}
  self:_ensureServerKey()
  return self:_send(method, path, body, options)
end

function Auth:_handleTerminal(code)
  local hadSession = self.session:hasAccessToken() or self.session:hasRefreshToken()
  self.session:clear()
  self.state = 'idle'
  if hadSession then
    self:_recordTelemetry(
      'INVALID_SESSION_TRANSITION',
      code == 'REFRESH_TOKEN_REUSE' and 'HIGH' or 'MEDIUM',
      'Session was terminated by the server',
      { code = code }
    )
  end
  if code == 'REFRESH_TOKEN_REUSE' then
    self:_recordTelemetry(
      'SUSPICIOUS_AUTH_PATTERN',
      'HIGH',
      'Refresh token reuse was detected',
      { code = code }
    )
  end
end

function Auth:_authRequest(method, path, body, options)
  options = options or {}
  self:_ensureSession()

  local function attempt()
    local token = self.session:getAccessToken()
    if token == nil then
      raiseError('INVALID_SESSION_TRANSITION', 'Authenticated request has no access token')
    end
    return self:_send(method, path, body, {
      authToken = token,
      requestId = options.requestId,
      requestPrefix = options.requestPrefix,
      timeoutSeconds = options.timeoutSeconds,
    })
  end

  local ok, first, second, third, fourth = pcall(attempt)
  if ok then
    return first, second, third, fourth
  end
  local err = wrapError(first)
  if (err.code == 'TOKEN_EXPIRED' or err.code == 'INVALID_TOKEN') and not options.retried then
    local refreshed = pcall(function()
      self:_refresh()
    end)
    if not refreshed then
      error(wrapError(refreshed), 0)
    end
    options.retried = true
    return self:_authRequest(method, path, body, options)
  end
  if TERMINAL_CODES[err.code] then
    self:_handleTerminal(err.code)
  end
  error(err, 0)
end

function Auth:_validateChallenge(data)
  if type(data) ~= 'table' then
    raiseError('PROTOCOL_MISMATCH', 'Challenge response is not an object')
  end
  if not isUuid(data.challengeId) then
    raiseError('PROTOCOL_MISMATCH', 'Challenge identifier is invalid')
  end
  if type(data.canonical) ~= 'string' or #data.canonical == 0 then
    raiseError('PROTOCOL_MISMATCH', 'Challenge canonical message is missing')
  end
  if data.algorithm ~= nil and data.algorithm ~= 'Ed25519' then
    raiseError('PROTOCOL_MISMATCH', 'Challenge algorithm is not Ed25519')
  end
  if data.protocolVersion ~= nil and data.protocolVersion ~= self.config.protocolVersion then
    raiseError('PROTOCOL_MISMATCH', 'Challenge protocol version does not match the client')
  end
  local challenge = data.challenge
  assertExactKeys(challenge, CHALLENGE_KEYS, 'Challenge')
  if challenge.challenge_id ~= data.challengeId then
    raiseError('PROTOCOL_MISMATCH', 'Challenge identifier is inconsistent')
  end
  if challenge.audience ~= self.config.audience then
    raiseError('PROTOCOL_MISMATCH', 'Challenge audience does not match the client')
  end
  if challenge.protocol_version ~= self.config.protocolVersion then
    raiseError('PROTOCOL_MISMATCH', 'Challenge protocol version does not match the client')
  end
  if challenge.device_id ~= self.deviceId then
    raiseError('PROTOCOL_MISMATCH', 'Challenge device identifier does not match this device')
  end
  if self.key == nil or self.key.keyId == nil or challenge.key_id ~= self.key.keyId then
    raiseError('PROTOCOL_MISMATCH', 'Challenge key identifier does not match the signing key')
  end
  assertString(challenge.license_id, 'Challenge license identifier', 1, 64)
  if self.license ~= nil and self.license.id ~= nil and challenge.license_id ~= self.license.id then
    raiseError('PROTOCOL_MISMATCH', 'Challenge license identifier does not match the active license')
  end
  if not isBase64Url(challenge.nonce) or #challenge.nonce < 40 or #challenge.nonce > 88 then
    raiseError('PROTOCOL_MISMATCH', 'Challenge nonce is invalid')
  end
  assertInteger(challenge.issued_at, 'Challenge issued_at')
  assertInteger(challenge.expires_at, 'Challenge expires_at')
  if challenge.expires_at <= challenge.issued_at then
    raiseError('PROTOCOL_MISMATCH', 'Challenge expiry precedes its issue time')
  end
  if challenge.expires_at - challenge.issued_at > self.config.challengeMaxTtlSeconds then
    raiseError('PROTOCOL_MISMATCH', 'Challenge lifetime exceeds the configured maximum')
  end
  local now = self:_now()
  if challenge.expires_at <= now - 5 then
    raiseError('CHALLENGE_EXPIRED', 'Challenge has already expired')
  end
  if math.abs(challenge.issued_at - now) > self.config.maxClockSkewSeconds then
    raiseError('PROTOCOL_MISMATCH', 'Challenge issue time is outside the allowed clock skew')
  end

  local expectedCanonical, canonicalError = Canonical.encode(challenge)
  if not expectedCanonical then
    self:_recordTelemetry(
      'PROTOCOL_SEQUENCE_VIOLATION',
      'HIGH',
      'Challenge could not be canonicalized',
      { reason = canonicalError }
    )
    raiseError('PROTOCOL_MISMATCH', 'Challenge could not be canonicalized')
  end
  if expectedCanonical ~= data.canonical then
    self:_recordTelemetry(
      'PROTOCOL_SEQUENCE_VIOLATION',
      'CRITICAL',
      'Challenge canonical message did not match the challenge fields',
      { challengeId = data.challengeId }
    )
    raiseError('PROTOCOL_MISMATCH', 'Challenge canonical message is inconsistent')
  end

  -- Carry the server-provided canonical message alongside the validated
  -- fields so _verify signs exactly the bytes the server will check.
  challenge.canonical = data.canonical
  self:_rememberChallenge(data.challengeId)
  self:_rememberNonce(challenge.nonce, data.challengeId)
  self:_setServerTime(data.serverTime)
  return challenge
end

function Auth:_challenge()
  enforceAllProtection(self, 'challenge')
  local requestId, requestIdError = self.security:newRequestId('challenge')
  if not requestId then
    raiseError('REPEATED_REQUEST_ID', requestIdError)
  end
  local body = {
    licenseKey = self.config.licenseKey,
    keyId = self.key.keyId,
    deviceId = self.deviceId,
    requestId = requestId,
    deviceName = self.config.deviceName,
    executor = self.config.executor,
    platform = self.config.platform,
  }
  local data = self:_publicRequest('POST', '/auth/challenge', body, {
    requestId = requestId,
  })
  return self:_validateChallenge(data)
end

function Auth:_validateSessionResponse(data, context)
  if type(data) ~= 'table' then
    raiseError('PROTOCOL_MISMATCH', context .. ' response is not an object')
  end
  assertString(data.accessToken, context .. ' access token', 20, 512)
  assertString(data.refreshToken, context .. ' refresh token', 20, 512)
  if data.tokenType ~= 'Bearer' then
    raiseError('PROTOCOL_MISMATCH', context .. ' token type is not Bearer')
  end
  assertInteger(data.expiresIn, context .. ' access expiry')
  assertInteger(data.refreshExpiresIn, context .. ' refresh expiry')
  if data.expiresIn <= 0 or data.refreshExpiresIn <= 0 then
    raiseError('PROTOCOL_MISMATCH', context .. ' token expiry is invalid')
  end
  if not isUuid(data.sessionId) then
    raiseError('PROTOCOL_MISMATCH', context .. ' session identifier is invalid')
  end
  if self.key ~= nil and self.key.keyId ~= nil and data.keyId ~= nil and data.keyId ~= self.key.keyId then
    raiseError('PROTOCOL_MISMATCH', context .. ' key identifier does not match the signing key')
  end
  if data.license ~= nil then
    if type(data.license) ~= 'table' or type(data.license.id) ~= 'string' or data.license.status ~= 'ACTIVE' then
      raiseError('PROTOCOL_MISMATCH', context .. ' license state is invalid')
    end
  end
  if data.device ~= nil then
    if type(data.device) ~= 'table' or data.device.deviceId ~= self.deviceId then
      raiseError('PROTOCOL_MISMATCH', context .. ' device identifier does not match this device')
    end
  end
  self:_setServerTime(data.serverTime)
  return data
end

function Auth:_verify(challenge)
  enforceProtection(self, 'integrity', 'sign')
  local signature, signatureError = self.security:sign(
    challenge.canonical,
    self.key.secretKey,
    self.key.publicKey
  )
  if not signature then
    raiseError('INVALID_SIGNATURE', signatureError or 'Unable to sign the challenge')
  end
  local requestId, requestIdError = self.security:newRequestId('verify')
  if not requestId then
    raiseError('REPEATED_REQUEST_ID', requestIdError)
  end
  local body = {
    challengeId = challenge.challenge_id,
    keyId = self.key.keyId,
    deviceId = self.deviceId,
    signature = signature,
    requestId = requestId,
  }
  local data = self:_publicRequest('POST', '/auth/verify', body, {
    requestId = requestId,
  })
  self:_validateSessionResponse(data, 'Verification')
  if data.license == nil or data.device == nil then
    raiseError('PROTOCOL_MISMATCH', 'Verification response is missing license or device state')
  end
  return data
end

function Auth:_activate()
  enforceAllProtection(self, 'activate')
  if self.config.licenseKey == nil then
    raiseError('MISSING_LICENSE_KEY', 'A license key is required for activation')
  end
  self.state = 'activating'

  local keyring, keyringError = self.security:loadKeyring()
  if not keyring then
    raiseError('KEYRING_CORRUPT', keyringError)
  end
  local key = self.security:currentKey(keyring)
  if key == nil or key.status == 'REVOKED' then
    if key ~= nil and key.status == 'REVOKED' then
      raiseError('KEY_REVOKED', 'The current signing key has been revoked')
    end
    local pair, pairError = self.security:generateKeyPair()
    if not pair then
      raiseError('CRYPTO_UNAVAILABLE', pairError)
    end
    local random, randomError = self.security:randomHex(8)
    if not random then
      raiseError('CRYPTO_UNAVAILABLE', randomError)
    end
    pair.localId = 'k_' .. random
    pair.name = self.config.keyName
    local added, addError = self.security:addKey(keyring, pair)
    if not added then
      raiseError('KEYRING_CORRUPT', addError)
    end
    keyring.current = pair.localId
    local saved, saveError = self.security:saveKeyring(keyring)
    if not saved then
      raiseError('STORAGE_UNAVAILABLE', saveError)
    end
    key = pair
  end

  self.keyring = keyring
  self.key = key
  self:_protectState()

  local requestId, requestIdError = self.security:newRequestId('activate')
  if not requestId then
    raiseError('REPEATED_REQUEST_ID', requestIdError)
  end
  local body = {
    licenseKey = self.config.licenseKey,
    publicKey = key.publicKey,
    deviceId = self.deviceId,
    deviceName = self.config.deviceName,
    executor = self.config.executor,
    platform = self.config.platform,
    keyName = key.name or self.config.keyName,
    requestId = requestId,
  }
  local data = self:_publicRequest('POST', '/licenses/activate', body, {
    requestId = requestId,
  })

  if type(data) ~= 'table' then
    raiseError('PROTOCOL_MISMATCH', 'Activation response is not an object')
  end
  assertString(data.licenseId, 'Activation license identifier', 1, 64)
  if data.licenseStatus ~= 'ACTIVE' then
    raiseError('LICENSE_NOT_ACTIVATED', 'License did not become active')
  end
  if type(data.key) ~= 'table' then
    raiseError('PROTOCOL_MISMATCH', 'Activation response is missing the signing key')
  end
  if data.key.publicKey ~= key.publicKey then
    raiseError('PROTOCOL_MISMATCH', 'Activation response public key does not match the local key')
  end
  if not isBase64Url(data.key.keyId) or #data.key.keyId < 40 or #data.key.keyId > 64 then
    raiseError('PROTOCOL_MISMATCH', 'Activation response key identifier is invalid')
  end
  if data.key.status ~= 'ACTIVE' then
    raiseError('PROTOCOL_MISMATCH', 'Activation response key is not active')
  end
  if type(data.device) ~= 'table' or data.device.deviceId ~= self.deviceId then
    raiseError('PROTOCOL_MISMATCH', 'Activation response device does not match this device')
  end

  local computedKeyId = self.security:publicKeyId(key.publicKey)
  if computedKeyId ~= nil and computedKeyId ~= data.key.keyId then
    raiseError('PROTOCOL_MISMATCH', 'Activation response key identifier is inconsistent')
  end

  key.keyId = data.key.keyId
  key.licenseId = data.licenseId
  key.name = data.key.name or key.name
  key.status = 'ACTIVE'
  local saved, saveError = self.security:saveKeyring(keyring)
  if not saved then
    raiseError('STORAGE_UNAVAILABLE', saveError)
  end

  self.license = {
    id = data.licenseId,
    status = data.licenseStatus,
    plan = data.plan,
    expiresAt = data.expiresAt,
    deviceLimit = data.deviceLimit,
    maxKeys = data.maxKeys,
  }
  self.state = self.session:isAuthenticated() and 'authenticated' or 'idle'
  return data
end

function Auth:_login()
  if self.config.licenseKey == nil then
    raiseError('MISSING_LICENSE_KEY', 'A license key is required to authenticate')
  end
  if self.key == nil or self.key.keyId == nil then
    self:_activate()
  end
  if self.key == nil or self.key.keyId == nil then
    raiseError('KEYRING_CORRUPT', 'No usable signing key is available')
  end

  self.state = 'challenging'
  local didActivate = false
  local lastError = nil

  for attempt = 1, 2 do
    local challengeOk, challenge = pcall(function()
      return self:_challenge()
    end)
    if not challengeOk then
      local err = wrapError(challenge)
      lastError = err
      if (err.code == 'KEY_NOT_FOUND' or err.code == 'LICENSE_NOT_ACTIVATED') and not didActivate then
        didActivate = true
        local activated = pcall(function()
          self:_activate()
        end)
        if not activated then
          self.state = 'idle'
          error(wrapError(activated), 0)
        end
        self.state = 'challenging'
      else
        self.state = 'idle'
        error(err, 0)
      end
    else
      local verifyOk, verified = pcall(function()
        return self:_verify(challenge)
      end)
      if not verifyOk then
        local err = wrapError(verified)
        lastError = err
        if RETRYABLE_CHALLENGE_CODES[err.code] and attempt < 2 then
          -- A previous verification may have been consumed even though its
          -- response was lost. A fresh challenge is safe to request.
        else
          self.state = 'idle'
          error(err, 0)
        end
      else
        local saved, saveError = self.session:setFromVerify(verified, self:_now())
        if not saved then
          self.state = 'idle'
          raiseError('INVALID_SESSION_TRANSITION', saveError)
        end
        self.license = verified.license
        self.state = 'authenticated'
        self:_resetAuthFailures()
        self:_flushTelemetry()
        return true
      end
    end
  end

  self.state = 'idle'
  error(lastError or newError('AUTHENTICATION_FAILED', 'Authentication failed'), 0)
end

function Auth:_refresh()
  enforceAllProtection(self, 'refresh')
  if self.state == 'refreshing' then
    self:_recordTelemetry(
      'INVALID_SESSION_TRANSITION',
      'MEDIUM',
      'Concurrent refresh attempted',
      nil
    )
    raiseError('INVALID_SESSION_TRANSITION', 'A refresh is already in progress')
  end
  if not self.session:hasRefreshToken() then
    self:_recordTelemetry(
      'INVALID_SESSION_TRANSITION',
      'MEDIUM',
      'Refresh requested without a refresh token',
      nil
    )
    raiseError('INVALID_SESSION_TRANSITION', 'No refresh token is available')
  end
  local now = self:_now()
  if not self.session:isRefreshValid(now) then
    self:_handleTerminal('TOKEN_EXPIRED')
    raiseError('TOKEN_EXPIRED', 'Refresh token has expired')
  end

  self.state = 'refreshing'
  local requestId, requestIdError = self.security:newRequestId('refresh')
  if not requestId then
    self.state = 'authenticated'
    raiseError('REPEATED_REQUEST_ID', requestIdError)
  end
  local body = {
    refreshToken = self.session:getRefreshToken(),
    deviceId = self.deviceId,
    requestId = requestId,
  }
  local ok, data = pcall(function()
    return self:_publicRequest('POST', '/auth/refresh', body, {
      requestId = requestId,
    })
  end)
  if not ok then
    local err = wrapError(data)
    if TERMINAL_CODES[err.code] or err.code == 'INVALID_TOKEN' or err.code == 'TOKEN_EXPIRED' then
      self:_handleTerminal(err.code)
    else
      self.state = self.session:isRefreshValid(self:_now()) and 'authenticated' or 'idle'
    end
    error(err, 0)
  end

  self:_validateSessionResponse(data, 'Refresh')
  local saved, saveError = self.session:setFromRefresh(data, self:_now())
  if not saved then
    self.state = 'idle'
    raiseError('INVALID_SESSION_TRANSITION', saveError)
  end
  self.state = 'authenticated'
  return true
end

function Auth:_authenticate()
  local now = self:_now()
  if self.state == 'authenticated' then
    if self.session:isAccessValid(now, self.config.refreshLeewaySeconds) then
      return true
    end
    if self.session:isRefreshValid(now) then
      return self:_refresh()
    end
    self:_recordTelemetry(
      'INVALID_SESSION_TRANSITION',
      'LOW',
      'Session expired without a usable refresh token',
      nil
    )
    self.session:clear()
    self.state = 'idle'
  end
  if self.state == 'idle' or self.state == 'revoked' then
    self.state = 'idle'
    return self:_login()
  end
  self:_recordTelemetry(
    'INVALID_SESSION_TRANSITION',
    'MEDIUM',
    'Authentication was requested during an incompatible state',
    { state = self.state }
  )
  raiseError('INVALID_SESSION_TRANSITION', 'Authentication is already in progress')
end

function Auth:_ensureSession()
  local now = self:_now()
  if self.state == 'authenticated' then
    if self.session:isAccessValid(now, self.config.refreshLeewaySeconds) then
      return true
    end
    if self.session:isRefreshValid(now) then
      return self:_refresh()
    end
    self:_recordTelemetry(
      'INVALID_SESSION_TRANSITION',
      'LOW',
      'Session expired without a usable refresh token',
      nil
    )
    self.session:clear()
    self.state = 'idle'
    return self:_login()
  end
  if self.state == 'idle' or self.state == 'revoked' then
    self.state = 'idle'
    return self:_login()
  end
  self:_recordTelemetry(
    'INVALID_SESSION_TRANSITION',
    'MEDIUM',
    'Session was requested during an incompatible state',
    { state = self.state }
  )
  raiseError('INVALID_SESSION_TRANSITION', 'Session is not available')
end

function Auth:authenticate()
  local ok, result = pcall(function()
    enforceAllProtection(self, 'authenticate')
    return self:_authenticate()
  end)
  if ok then
    self.lastError = nil
    return true
  end
  local err = wrapError(result)
  self.lastError = err
  self:_recordAuthFailure(err.code)
  self:_recordTelemetry(
    'SUSPICIOUS_AUTH_PATTERN',
    'MEDIUM',
    'Authentication attempt failed',
    { code = err.code }
  )
  if self.config.telemetry.autoFlush then
    pcall(function()
      self:_flushTelemetry()
    end)
  end
  return nil, err
end

function Auth:refresh()
  local ok, result = pcall(function()
    enforceAllProtection(self, 'refresh')
    return self:_refresh()
  end)
  if ok then
    return true
  end
  local err = wrapError(result)
  self.lastError = err
  return nil, err
end

function Auth:logout()
  enforceAllProtection(self, 'logout')
  local now = self:_now()
  if self.session:hasAccessToken() and (self.session:isAccessValid(now, 0) or self.session:isRefreshValid(now)) then
    pcall(function()
      self:_authRequest('POST', '/auth/logout', {}, {})
    end)
  end
  self.session:clear()
  self.state = 'idle'
  return true
end

function Auth:getStatus()
  enforceAllProtection(self, 'getStatus')
  local ok, data = pcall(function()
    return self:_authRequest('GET', '/licenses/status', nil, {})
  end)
  if not ok then
    error(wrapError(data), 0)
  end
  if type(data) ~= 'table' or type(data.license) ~= 'table' or type(data.session) ~= 'table' then
    self:_recordTelemetry(
      'UNEXPECTED_RESPONSE_STRUCTURE',
      'HIGH',
      'Status response did not contain license and session state',
      nil
    )
    raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Status response is malformed')
  end
  if type(data.security) ~= 'table' or data.security.sessionValid ~= true then
    self:_recordTelemetry(
      'INVALID_SESSION_TRANSITION',
      'HIGH',
      'Status response reported an invalid session',
      nil
    )
    self:_handleTerminal('SESSION_REVOKED')
    raiseError('SESSION_REVOKED', 'Session is no longer valid')
  end
  return data
end

function Auth:getSession()
  enforceAllProtection(self, 'getSession')
  local ok, data = pcall(function()
    return self:_authRequest('GET', '/auth/session', nil, {})
  end)
  if not ok then
    error(wrapError(data), 0)
  end
  if type(data) ~= 'table' or type(data.session) ~= 'table' or type(data.license) ~= 'table' then
    raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Session response is malformed')
  end
  return data
end

function Auth:getSecurityStatus()
  enforceAllProtection(self, 'getSecurityStatus')
  local ok, data = pcall(function()
    return self:_authRequest('GET', '/security/status', nil, {})
  end)
  if not ok then
    error(wrapError(data), 0)
  end
  if type(data) ~= 'table' or type(data.security) ~= 'table' then
    raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Security status response is malformed')
  end
  return data
end

function Auth:listKeys()
  enforceAllProtection(self, 'listKeys')
  local ok, data = pcall(function()
    return self:_authRequest('GET', '/licenses/keys', nil, {})
  end)
  if not ok then
    error(wrapError(data), 0)
  end
  if type(data) ~= 'table' or type(data.items) ~= 'table' then
    raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Key list response is malformed')
  end
  return data.items
end

--- Lists the protected payloads that this license may fetch.
function Auth:listPayloads()
  enforceAllProtection(self, 'listPayloads')
  local ok, data = pcall(function()
    return self:_authRequest('GET', '/payloads', nil, {})
  end)
  if not ok then
    error(wrapError(data), 0)
  end
  if type(data) ~= 'table' or type(data.items) ~= 'table' then
    raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Payload list response is malformed')
  end
  for _, item in ipairs(data.items) do
    if type(item) ~= 'table'
      or type(item.slug) ~= 'string'
      or type(item.sha256) ~= 'string'
      or not isInteger(item.version)
    then
      raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Payload list entry is malformed')
    end
  end
  return data.items
end

--- Fetches a protected payload and verifies its SHA-256 before returning it.
function Auth:fetchPayload(slug)
  enforceAllProtection(self, 'fetchPayload')
  if not isValidPayloadSlug(slug) then
    raiseError('PAYLOAD_NOT_FOUND', 'Payload slug is invalid')
  end
  local ok, data = pcall(function()
    return self:_authRequest('GET', '/payloads/' .. slug, nil, {})
  end)
  if not ok then
    error(wrapError(data), 0)
  end
  if type(data) ~= 'table'
    or type(data.code) ~= 'string'
    or #data.code == 0
    or type(data.sha256) ~= 'string'
  then
    raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Payload response is malformed')
  end
  local digest, digestError = self.security:sha256Hex(data.code)
  if not digest then
    raiseError('CRYPTO_UNAVAILABLE', 'Unable to hash the payload: ' .. tostring(digestError))
  end
  if digest:lower() ~= data.sha256:lower() then
    self:_recordTelemetry(
      'PROTOCOL_SEQUENCE_VIOLATION',
      'CRITICAL',
      'Protected payload failed its integrity check',
      { slug = slug, expected = data.sha256, actual = digest }
    )
    raiseError('PAYLOAD_INTEGRITY', 'Payload integrity check failed')
  end
  return data
end

--- Fetches, verifies, and executes a protected payload with the loader that was
--- captured and pinned when the client was created.
function Auth:runPayload(slug, ...)
  local payload = self:fetchPayload(slug)
  enforceAllProtection(self, 'runPayload')
  local loader = self._loader
  if type(loader) ~= 'function' then
    loader = loadstring or load
  end
  if type(loader) ~= 'function' then
    raiseError('LOADSTRING_UNAVAILABLE', 'This executor does not expose loadstring')
  end
  local chunk, loadError = loader(payload.code, '@whitelist-payload-' .. payload.slug)
  if type(chunk) ~= 'function' then
    raiseError('PAYLOAD_LOAD_ERROR', 'Payload could not be compiled: ' .. tostring(loadError))
  end
  return chunk(...)
end

function Auth:_validateRegistrationChallenge(data, publicKey)
  if type(data) ~= 'table' then
    raiseError('PROTOCOL_MISMATCH', 'Key registration challenge is not an object')
  end
  if not isUuid(data.registrationId) then
    raiseError('PROTOCOL_MISMATCH', 'Registration identifier is invalid')
  end
  if not isBase64Url(data.keyId) or #data.keyId < 40 or #data.keyId > 64 then
    raiseError('PROTOCOL_MISMATCH', 'Registration key identifier is invalid')
  end
  if data.algorithm ~= nil and data.algorithm ~= 'Ed25519' then
    raiseError('PROTOCOL_MISMATCH', 'Registration algorithm is not Ed25519')
  end
  if type(data.canonical) ~= 'string' or #data.canonical == 0 then
    raiseError('PROTOCOL_MISMATCH', 'Registration canonical message is missing')
  end

  local message, decodeError = Json.decode(data.canonical)
  if not message then
    self:_recordTelemetry(
      'PROTOCOL_SEQUENCE_VIOLATION',
      'HIGH',
      'Registration canonical message is not valid JSON',
      { reason = decodeError }
    )
    raiseError('PROTOCOL_MISMATCH', 'Registration canonical message is malformed')
  end
  assertExactKeys(message, REGISTRATION_KEYS, 'Registration message')
  if message.action ~= 'register_signing_key' then
    raiseError('PROTOCOL_MISMATCH', 'Registration message action is invalid')
  end
  if message.audience ~= self.config.audience then
    raiseError('PROTOCOL_MISMATCH', 'Registration audience does not match the client')
  end
  if message.protocol_version ~= self.config.protocolVersion then
    raiseError('PROTOCOL_MISMATCH', 'Registration protocol version does not match the client')
  end
  if message.key_id ~= data.keyId then
    raiseError('PROTOCOL_MISMATCH', 'Registration key identifier is inconsistent')
  end
  if message.registration_id ~= data.registrationId then
    raiseError('PROTOCOL_MISMATCH', 'Registration identifier is inconsistent')
  end
  if self.license ~= nil and self.license.id ~= nil and message.license_id ~= self.license.id then
    raiseError('PROTOCOL_MISMATCH', 'Registration license identifier does not match the active license')
  end
  if not isBase64Url(message.nonce) or #message.nonce < 40 or #message.nonce > 88 then
    raiseError('PROTOCOL_MISMATCH', 'Registration nonce is invalid')
  end
  assertInteger(message.issued_at, 'Registration issued_at')
  assertInteger(message.expires_at, 'Registration expires_at')
  if message.expires_at <= message.issued_at then
    raiseError('PROTOCOL_MISMATCH', 'Registration expiry precedes its issue time')
  end
  if message.expires_at - message.issued_at > self.config.keyRegistrationMaxTtlSeconds then
    raiseError('PROTOCOL_MISMATCH', 'Registration lifetime exceeds the configured maximum')
  end
  if message.expires_at <= self:_now() - 5 then
    raiseError('CHALLENGE_EXPIRED', 'Registration challenge has expired')
  end
  if math.abs(message.issued_at - self:_now()) > self.config.maxClockSkewSeconds then
    raiseError('PROTOCOL_MISMATCH', 'Registration issue time is outside the allowed clock skew')
  end

  local expectedCanonical, canonicalError = Canonical.encode(message)
  if not expectedCanonical or expectedCanonical ~= data.canonical then
    self:_recordTelemetry(
      'PROTOCOL_SEQUENCE_VIOLATION',
      'CRITICAL',
      'Registration canonical message did not match its fields',
      { reason = canonicalError }
    )
    raiseError('PROTOCOL_MISMATCH', 'Registration canonical message is inconsistent')
  end

  local computedKeyId = self.security:publicKeyId(publicKey)
  if computedKeyId ~= nil and computedKeyId ~= data.keyId then
    raiseError('PROTOCOL_MISMATCH', 'Registration key identifier does not match the public key')
  end
  return message
end

function Auth:registerKey(name)
  enforceAllProtection(self, 'registerKey')
  self:_ensureSession()
  local keyring, keyringError = self.security:loadKeyring()
  if not keyring then
    raiseError('KEYRING_CORRUPT', keyringError)
  end
  local pair, pairError = self.security:generateKeyPair()
  if not pair then
    raiseError('CRYPTO_UNAVAILABLE', pairError)
  end
  local random, randomError = self.security:randomHex(8)
  if not random then
    raiseError('CRYPTO_UNAVAILABLE', randomError)
  end
  pair.localId = 'k_' .. random
  pair.name = name or 'additional'
  pair.licenseId = self.license and self.license.id or nil

  local challenge = self:_authRequest('POST', '/licenses/keys/challenge', {
    publicKey = pair.publicKey,
    keyName = name,
  }, {})
  self:_validateRegistrationChallenge(challenge, pair.publicKey)

  local signature, signatureError = self.security:sign(
    challenge.canonical,
    pair.secretKey,
    pair.publicKey
  )
  if not signature then
    raiseError('INVALID_SIGNATURE', signatureError or 'Unable to sign the registration challenge')
  end
  local requestId, requestIdError = self.security:newRequestId('keyreg')
  if not requestId then
    raiseError('REPEATED_REQUEST_ID', requestIdError)
  end
  local registered = self:_authRequest('POST', '/licenses/keys/register', {
    registrationId = challenge.registrationId,
    signature = signature,
    name = name,
    requestId = requestId,
  }, {
    requestId = requestId,
  })

  if type(registered) ~= 'table' then
    raiseError('UNEXPECTED_RESPONSE_STRUCTURE', 'Key registration response is malformed')
  end
  if registered.keyId ~= challenge.keyId then
    raiseError('PROTOCOL_MISMATCH', 'Registered key identifier does not match the challenge')
  end
  if registered.publicKey ~= pair.publicKey then
    raiseError('PROTOCOL_MISMATCH', 'Registered public key does not match the local key')
  end
  if registered.status ~= 'ACTIVE' then
    raiseError('PROTOCOL_MISMATCH', 'Registered key is not active')
  end

  pair.keyId = registered.keyId
  pair.status = 'ACTIVE'
  pair.name = registered.name or pair.name
  pair.createdAt = os.time()
  local added, addError = self.security:addKey(keyring, pair)
  if not added then
    raiseError('KEYRING_CORRUPT', addError)
  end
  local saved, saveError = self.security:saveKeyring(keyring)
  if not saved then
    raiseError('STORAGE_UNAVAILABLE', saveError)
  end
  self.keyring = keyring
  self:_protectState()
  return {
    keyId = pair.keyId,
    publicKey = pair.publicKey,
    name = pair.name,
    status = pair.status,
    localId = pair.localId,
  }
end

function Auth:rotateKey(name)
  enforceAllProtection(self, 'rotateKey')
  if self.key == nil or self.key.keyId == nil then
    raiseError('KEY_NOT_FOUND', 'No active signing key is available')
  end
  local oldKey = self.key
  local oldSession = self.session:snapshot()

  local ok, result = pcall(function()
    return self:registerKey(name or 'rotated')
  end)
  if not ok then
    error(wrapError(result), 0)
  end
  local newKey = self.security:findKey(self.keyring, result.keyId)
  if newKey == nil then
    raiseError('KEYRING_CORRUPT', 'Newly registered key was not stored')
  end

  self.keyring.current = newKey.localId
  self.key = newKey
  local saved, saveError = self.security:saveKeyring(self.keyring)
  if not saved then
    raiseError('STORAGE_UNAVAILABLE', saveError)
  end
  self:_protectState()
  self.session:clear()
  self.state = 'idle'

  local loginOk, loginError = pcall(function()
    return self:_login()
  end)
  if not loginOk then
    self.keyring.current = oldKey.localId
    self.key = oldKey
    self:_protectState()
    self.security:saveKeyring(self.keyring)
    if oldSession ~= nil then
      self.session:_restore(oldSession)
      self.state = 'authenticated'
    else
      self.state = 'idle'
    end
    error(wrapError(loginError), 0)
  end

  if oldKey.keyId ~= nil and oldKey.keyId ~= newKey.keyId then
    local revokeOk, revokeError = pcall(function()
      return self:_authRequest('POST', '/licenses/keys/' .. oldKey.keyId .. '/revoke', {
        reason = 'Rotated to a new signing key',
      }, {})
    end)
    if revokeOk then
      self.security:removeKey(self.keyring, oldKey.localId)
      self.security:saveKeyring(self.keyring)
    else
      oldKey.status = 'RETIRED'
      self.security:saveKeyring(self.keyring)
      self.lastWarning = wrapError(revokeError)
      self:_recordTelemetry(
        'INVALID_SESSION_TRANSITION',
        'MEDIUM',
        'Key rotation succeeded but the old key could not be revoked',
        { oldKeyId = oldKey.keyId }
      )
    end
  end
  return true
end

function Auth:revokeKey(keyId)
  enforceAllProtection(self, 'revokeKey')
  if type(keyId) ~= 'string' or not isBase64Url(keyId) or #keyId < 40 or #keyId > 64 then
    raiseError('KEY_NOT_FOUND', 'Key identifier is invalid')
  end
  self:_authRequest('POST', '/licenses/keys/' .. keyId .. '/revoke', {
    reason = 'Revoked by client',
  }, {})
  local keyring = self.security:loadKeyring()
  if keyring then
    local record = self.security:findKey(keyring, keyId)
    if record ~= nil then
      if self.key ~= nil and record.localId == self.key.localId then
        self.session:clear()
        self.state = 'idle'
        self.key = nil
      end
      self.security:removeKey(keyring, record.localId)
      self.security:saveKeyring(keyring)
      self.keyring = keyring
      self:_protectState()
    end
  end
  return true
end

function Auth:deactivate()
  enforceAllProtection(self, 'deactivate')
  self:_authRequest('POST', '/licenses/deactivate', {
    deviceId = self.deviceId,
  }, {})
  self.session:clear()
  self.state = 'idle'
  return true
end

function Auth:sendTelemetry(events)
  local guardOk, guardError = pcall(enforceAllProtection, self, 'sendTelemetry')
  if not guardOk then
    return nil, wrapError(guardError)
  end
  if not self.config.telemetry.enabled then
    return true
  end
  if type(events) ~= 'table' then
    return nil, newError('INVALID_TELEMETRY', 'Telemetry events must be a table')
  end
  if events.type ~= nil then
    events = { events }
  end
  local accepted = 0
  for _, event in ipairs(events) do
    local sanitized, sanitizeError = self.security:sanitizeTelemetryEvent(event, self.config.telemetry)
    if sanitized then
      self.telemetryQueue[#self.telemetryQueue + 1] = sanitized
      accepted = accepted + 1
    else
      self.security:log('warn', 'Telemetry event rejected: ' .. tostring(sanitizeError))
    end
  end
  local maxQueue = self.config.telemetry.maxQueue
  while #self.telemetryQueue > maxQueue do
    table.remove(self.telemetryQueue, 1)
    self.telemetryDropped = self.telemetryDropped + 1
  end
  if self.config.telemetry.autoFlush then
    local ok, flushError = pcall(function()
      return self:_flushTelemetry()
    end)
    if not ok then
      return nil, wrapError(flushError)
    end
  end
  return true, { accepted = accepted, queued = #self.telemetryQueue }
end

function Auth:flushTelemetry()
  local ok, result = pcall(function()
    enforceAllProtection(self, 'flushTelemetry')
    return self:_flushTelemetry()
  end)
  if ok then
    return true
  end
  return nil, wrapError(result)
end

function Auth:getAccessToken()
  local ok, result = pcall(function()
    enforceAllProtection(self, 'getAccessToken')
    self:_ensureSession()
    return self.session:getAccessToken()
  end)
  if ok then
    return result
  end
  return nil, wrapError(result)
end

function Auth:isAuthenticated()
  if self.state ~= 'authenticated' then
    return false
  end
  local now = self:_now()
  return self.session:isAccessValid(now, 0) or self.session:isRefreshValid(now)
end

function Auth:getState()
  return self.state
end

function Auth:getLastError()
  return self.lastError
end

function Auth:getLastWarning()
  return self.lastWarning
end

function Auth:getDeviceId()
  return self.deviceId
end

function Auth:getKeyId()
  return self.key and self.key.keyId or nil
end

function Auth:getLicenseId()
  return self.license and self.license.id or nil
end

function Auth:getLicense()
  return self.license
end

function Auth:getServerKey()
  if self.serverKey == nil then
    return nil
  end
  return {
    publicKey = self.serverKey.publicKey,
    keyId = self.serverKey.keyId,
  }
end

function Auth:getTelemetryStats()
  return {
    queued = #self.telemetryQueue,
    dropped = self.telemetryDropped,
  }
end

function Auth:setLicenseKey(licenseKey)
  local guardOk, guardError = pcall(enforceAllProtection, self, 'setLicenseKey')
  if not guardOk then
    return nil, wrapError(guardError)
  end
  if type(licenseKey) ~= 'string' then
    return nil, newError('INVALID_CONFIG', 'License key must be a string')
  end
  licenseKey = licenseKey:gsub('^%s+', ''):gsub('%s+$', '')
  if #licenseKey < 20 or #licenseKey > 200 or licenseKey:find('[%z\1-\31\127]') then
    return nil, newError('INVALID_CONFIG', 'License key is invalid')
  end
  self.config.licenseKey = licenseKey
  return true
end

function Auth:resetSession()
  local guardOk, guardError = pcall(enforceAllProtection, self, 'resetSession')
  if not guardOk then
    return nil, wrapError(guardError)
  end
  self.session:clear()
  self.state = 'idle'
  return true
end

return Auth
end

__wl_modules["init"] = function()
-- Public entry point for the whitelist Lua client.
--
-- Requiring this module has no side effects. Nothing touches the executor,
-- the filesystem, or the network until Whitelist.new / Whitelist.authenticate
-- is called with a resolved configuration.

local Auth = __wl_require('auth')
local Canonical = __wl_require('canonical')
local Config = __wl_require('config')
local Http = __wl_require('http')
local Protection = __wl_require('protection')
local SecureChannel = __wl_require('secure_channel')
local Security = __wl_require('security')
local Session = __wl_require('session')
local Json = __wl_require('json')

local Whitelist = {
  version = Config.VERSION,
  protocolVersion = Config.PROTOCOL_VERSION,
  audience = Config.AUDIENCE,
}

Whitelist.Auth = Auth
Whitelist.Canonical = Canonical
Whitelist.Config = Config
Whitelist.Http = Http
Whitelist.Protection = Protection
Whitelist.SecureChannel = SecureChannel
Whitelist.Security = Security
Whitelist.Session = Session
Whitelist.Json = Json

--- Creates a client without performing any network request.
--- @param options table
--- @return table|nil client
--- @return table|nil error
function Whitelist.new(options)
  return Auth.new(options)
end

--- Creates a client, authenticates it, and returns it only on success.
--- @param options table
--- @return table|nil client
--- @return table|nil error
function Whitelist.authenticate(options)
  local client, clientError = Auth.new(options)
  if not client then
    return nil, clientError
  end
  local ok, authError = client:authenticate()
  if not ok then
    return nil, authError
  end
  return client
end

--- Returns an in-memory storage adapter. Intended for tests and for executors
--- where the caller provides its own persistence layer.
function Whitelist.memoryStorage()
  return Security.memoryStorage()
end

--- Returns a file-backed storage adapter rooted at a relative folder.
--- @param root string
--- @return table|nil storage
--- @return string|nil error
function Whitelist.fileStorage(root)
  return Security.fileStorage(root)
end

-- Mark the public module tables and every exposed function as protected. The
-- anti-dump tripwires and getgc() filtering use this registry so a dumper
-- cannot enumerate the client's internals through the Lua heap.
Protection.registerModules({
  Whitelist = Whitelist,
  Auth = Auth,
  Canonical = Canonical,
  Config = Config,
  Http = Http,
  Protection = Protection,
  SecureChannel = SecureChannel,
  Security = Security,
  Session = Session,
  Json = Json,
})

return Whitelist
end

return __wl_require('init')
